/// A world that gives vitae back gives the Crystalabra's cure its two points to its user and
/// fellows, and has its quest as a row whose giving puts the cure on, over in time for another
/// item. A world with no such rows gives none back.
/// Behaviour: server.effects.vitae-restore-rows
#[test]
fn the_worlds_crystalabra_rows_give_its_cure_through_its_quest() {
    use yalain_world::effect_defs::VitaeRestore;
    let t = &compiled().tables;
    if t.effect_rules.vitae_restores.is_empty() {
        return;
    }
    assert_eq!(
        t.effect_rules.vitae_restores,
        std::collections::BTreeMap::from([(
            yalain_testkit::CRYSTALABRA_CURE,
            VitaeRestore {
                points: 2.0,
                most: None,
                fellows: true
            }
        )])
    );
    let quest = t
        .quests
        .quest(0x4000_0312)
        .expect("the Crystalabra's quest");
    assert!(
        quest
            .effects
            .iter()
            .any(|(_, e, _)| *e == yalain_testkit::CRYSTALABRA_CURE),
        "{:?}",
        quest.effects
    );
    assert!(quest.duration > 0.0, "over in time");
    assert!(quest.hidden);
}

/// The world's teaching stones named by their own scripts (the three vaults', the maps', the
/// Tumerok hall's loot stone) are examined by their name and page, each from its own table as 2017
/// sent them: every one placed carries both.
/// Behaviour: server.examination.teaching-stone-rows
#[test]
fn the_worlds_teaching_stones_named_by_their_scripts_have_their_name_and_page() {
    let t = &compiled().tables;
    for (template, table) in [
        (0x4700_2E4D, 0x2500_1AAE),
        (0x4700_2E4E, 0x2500_1AAF),
        (0x4700_2E4F, 0x2500_1AB0),
        (0x4700_2E46, 0x2500_1AA7),
        (0x4700_2DF2, 0x2500_091B),
    ] {
        let placed: Vec<_> = t
            .content
            .objects
            .iter()
            .filter(|o| o.template == template)
            .collect();
        assert!(!placed.is_empty(), "{template:08X} placed");
        for o in placed {
            assert_eq!(
                (o.facts.name, o.facts.description),
                (Some((0xA860_7CEC, table)), Some((0x6C45_9364, table))),
                "{template:08X}"
            );
        }
    }
}

/// The world's Fickle Fate picks among its fourteen outcomes, each as likely as another, for its
/// user and the fellows within 20 m, the range its skills hold in the install.
/// Behaviour: server.effects.fickle-fate-rows
#[test]
fn the_worlds_fickle_fate_picks_its_fourteen_outcomes_evenly_within_20_m() {
    let t = &compiled().tables;
    let pick = t
        .effect_rules
        .picks
        .get(&0x7000_1EC7)
        .expect("Fickle Fate's row");
    assert!(pick.fellows);
    assert_eq!(pick.reach, Some(20));
    let mut outcomes: Vec<u32> = pick.effects.iter().map(|(e, _)| *e).collect();
    outcomes.sort_unstable();
    assert_eq!(outcomes, (0x7000_1EC8..=0x7000_1ED5).collect::<Vec<_>>());
    assert!(
        pick.effects.iter().all(|(_, w)| *w == pick.effects[0].1),
        "even weights: {:?}",
        pick.effects
    );
}

/// A world's mine and map region rows hold the test world's, entry for entry: each mining skill's
/// behavior, tools, answers, delving node, lodestones and finds, each region's nodes by their
/// effects, and what each mining tool yields unmade.
/// Behaviour: server.craft.gathering-rows-hold-the-servers-own
#[test]
fn the_worlds_mine_and_map_region_rows_hold_the_test_worlds_entry_for_entry() {
    let t = &compiled().tables;
    let mut craft = yalain_world::craft::Crafting {
        tool_yields: t.crafting.tool_yields.clone().into_iter().collect(),
        ..yalain_world::craft::Crafting::default()
    };
    yalain_world::mining::take_world_gathering(&mut craft, &t.gathering);
    let own = yalain_testkit::test_gathering();
    for (skill, mine) in &own.mines {
        assert_eq!(craft.gathering.mines.get(skill), Some(mine), "{skill:08X}");
    }
    for (region, nodes) in &own.map_regions {
        assert_eq!(
            craft.gathering.map_regions.get(region),
            Some(nodes),
            "{region}"
        );
    }
    for (tool, unmade) in yalain_testkit::test_mining_tool_yields() {
        assert_eq!(craft.tool_yields.get(&tool), Some(&unmade), "{tool:08X}");
    }
}

/// A world's corpse finds give a lodestone of each of the five kinds a mine unearths at the killer's
/// level, the same band mining gives, never from a creature its template marks or more than a level
/// below the killer; and a Tessera only from a creature of level 42 or more, for a killer under its
/// hero skill credit cap. A world older than these rows has none.
/// Behaviour: server.loot.corpse-find-rows
#[test]
fn the_worlds_corpse_finds_give_mining_bands_lodestones_and_tesserae_from_level_42() {
    let t = &compiled().tables;
    let Some(stones) = t.loot.finds.iter().find(|f| f.key == "lodestones") else {
        return;
    };
    for level in [1, 24, 25, 39, 40, 54, 55, 69, 70, 150] {
        let mut band = stones.band(level).to_vec();
        let mut mined: Vec<u32> = t
            .gathering
            .mines
            .values()
            .filter_map(|m| m.lodestone(level))
            .collect();
        band.sort_unstable();
        mined.sort_unstable();
        assert_eq!(band, mined, "level {level}");
    }
    assert_eq!(
        (
            stones.never.as_deref(),
            stones.below_killer,
            stones.hero_cap
        ),
        (Some("NPC_NeverDropLodestones"), Some(1), false)
    );
    let tesserae = t
        .loot
        .finds
        .iter()
        .find(|f| f.key == "tesserae")
        .expect("Tesserae beside the lodestones");
    assert_eq!(
        (
            tesserae.never.as_deref(),
            tesserae.least_level,
            tesserae.hero_cap
        ),
        (Some("NPC_NeverDropTesserae"), Some(42), true)
    );
    assert_eq!(tesserae.items().collect::<Vec<_>>(), [0x4700_052F]);
}

