/// A world's plant and plant cross rows hold the test world's, entry for entry: each dye plant's
/// plant, seed, pollen, plant item and pollen's name (a species with lines of its own is no dye
/// plant), and each of its crosses' seeds and how many; and every other cross is of a species'
/// plant and pollen and gives a species' seeds, one to three.
/// Behaviour: server.plants.plant-rows-hold-the-servers-own
#[test]
fn the_worlds_plant_and_plant_cross_rows_hold_the_test_worlds_entry_for_entry() {
    let plants = &compiled().tables.plants;
    let own = yalain_testkit::test_plants();
    let dye: std::collections::BTreeMap<_, _> = plants
        .species
        .iter()
        .filter(|(_, s)| s.texts.is_none())
        .map(|(k, s)| (*k, *s))
        .collect();
    assert_eq!(dye, own.species);
    for (pair, cross) in &own.crosses {
        assert_eq!(plants.crosses.get(pair), Some(cross), "{pair:08X?}");
    }
    for c in plants.crosses.values() {
        assert!(plants.species.contains_key(&c.plant), "{:08X}", c.plant);
        assert!(plants.pollen_of(c.pollen).is_some(), "{:08X}", c.pollen);
        assert!(plants.sown_by(c.seeds).is_some(), "{:08X}", c.seeds);
        assert!((1..=3).contains(&c.count), "{c:?}");
    }
}

