/// **The Skyport nexus' guards let the archive amulet's wearer by**: the amulet's effect for its
/// wearer resolves to its one effect by the world's name for it, and the world lets that effect's
/// bearer by every Imperial Servitor Guard; one guard stands in the Nexus Room by the heart. The
/// nexus door, its key used on it at the quest's phase, leads to the landing; every spot of the
/// nexus' camps stands in its own room, the guard moving there, and is reached on foot; the
/// farthest is run to and back. Played with the guards standing: the walker wears the amulet, the
/// effect goes on, and it runs from the landing to the heart and waits there, and no guard takes it
/// on; the amulet taken off, the Nexus Room's guard comes at it. The way out leads back to the
/// Skyport by the door.
/// Behaviour: server.world.skyport-nexus-guards-let-the-amulet-by
#[test]
fn the_skyport_nexus_guards_let_the_archive_amulets_wearer_walk_to_the_heart() {
    use yalain_content::creature_rows::{Guards, Pass, SafePassage};
    use yalain_world::usable::maps::ground_distance;
    const QUEST: u32 = 0x8000_027D;
    const GUARD: u32 = 0x4700_2AA5;
    const AMULET: u32 = 0x4700_1668;
    const AMULET_EFFECT: u32 = 0x6F00_1D2C;
    const NEXUS_KEY: u32 = 0x4700_166B;
    const NEXUS_DOOR: u32 = 0x4700_1670;
    const NEXUS_HEART: u32 = 0x4700_1676;
    const SKYPORT: u32 = 0xAA58;
    const NEXUS: u32 = 0x06C6;
    const LANDING: u32 = 0x06C6_017E;
    let c = compiled();
    let t = &c.tables;
    assert_eq!(
        t.effect_names.get("Eff_ArchiveConcealSkyportQuest"),
        Some(&AMULET_EFFECT),
        "the amulet's worn effect named"
    );
    assert!(
        t.creatures.safe_passage.contains(&SafePassage {
            guards: Guards::Template(GUARD),
            pass: Pass::Effect(AMULET_EFFECT),
        }),
        "the guards let its bearer by"
    );
    let camps = pack_camps(c, "skyport-nexus-guards", NEXUS);
    let heart = &t.content.objects[placed(t, NEXUS_HEART)];
    let at_heart = spot(heart.cell, heart.origin);
    assert!(
        camps.iter().any(|&i| {
            let k = &t.spawns.camps[i];
            k.cell == heart.cell && ground_distance(&spot(k.cell, k.origin), &at_heart) < 8.0
        }),
        "a guard in the Nexus Room by the heart"
    );

    // On foot: in by the locked door with its key, every camp's spots, the farthest and back.
    let portal = yalain_testkit::authored::Portal::open();
    let mut w = walled(t, &[SKYPORT, NEXUS]);
    let door = placed(t, NEXUS_DOOR);
    serve_locked_doors(&mut w.h, t, &portal, &[(door, NEXUS_KEY)]);
    put_at_phase(&mut w.h, QUEST, 10);
    let cell = used_on_object(&mut w.h, w.b, w.me, t, (NEXUS_KEY, door));
    assert_eq!(cell, LANDING, "the key carries the walker to the landing");
    let landing = w.at();
    let n = camps_reached_on_foot(c, &mut w, &camps, &[GUARD], 1.5);
    assert!(n >= 55, "guards throughout: {n}");

    // Played: the guards stand, and the walker wears the amulet.
    w.h.server.creature_rows = t.creatures.clone();
    w.h.server.catalog.insert(as_installed(&portal, GUARD));
    w.h.server.spawns.camps = camps.iter().map(|&i| t.spawns.camps[i].clone()).collect();
    w.h.server.camps = vec![yalain_world::spawn::CampState::default(); camps.len()];
    w.h.server.worn_effects = portal.worn_effects_named(&[AMULET], &t.effect_names);
    let read = portal.effects(&[AMULET_EFFECT]);
    let def = read.get(AMULET_EFFECT).expect("the effect reads").clone();
    w.h.server.effect_table.effects.insert(AMULET_EFFECT, def);
    put_at_phase(&mut w.h, QUEST, 11);
    take_item(&mut w.h, &portal, AMULET);
    let world = w.world;
    let amulet = w.h.server.players[&world]
        .play
        .items
        .iter()
        .find(|i| i.template == AMULET)
        .map(|i| i.id)
        .expect("the amulet held");
    let wear = |w: &mut Walled| {
        w.h.bots[w.b].send(
            true,
            queue::WEENIE,
            &server_call(0x8216_0016, &[use_of(amulet, w.me)]),
        );
        w.h.run(10);
    };
    let bears = |w: &Walled| {
        w.h.server.players[&world]
            .play
            .effects
            .iter()
            .any(|e| e.state == AMULET_EFFECT)
    };
    wear(&mut w);
    assert!(bears(&w), "worn, its effect is on");
    w.put(landing);
    // The client draws the nexus after the trip in: only then may a creature take the walker on.
    w.h.bots[w.b].send(
        true,
        queue::WEENIE,
        &auberean_protocol::ClientMessage::SceneRenderingComplete(auberean_protocol::login::Empty),
    );
    w.wait(5.0);
    assert!(
        w.h.server.players[&world].scene_drawn,
        "the walker is in the world, to be seen"
    );
    let guards = living_of(&w.h, GUARD);
    assert_eq!(
        u32::try_from(guards.len()).unwrap_or(0),
        n,
        "every guard stands"
    );
    let me = w.me;
    let on_me = |w: &Walled| {
        guards
            .iter()
            .filter(|id| {
                w.h.server
                    .things
                    .get(**id)
                    .and_then(|x| x.creature.as_ref())
                    .is_some_and(|c| c.target == Some(me))
            })
            .count()
    };
    let health = |w: &Walled| {
        yalain_world::quals::int(
            &w.h.server.players[&world].qualities,
            yalain_world::player::quality::HEALTH,
        )
    };
    let whole = health(&w);
    assert!(whole.is_some_and(|x| x > 0), "the walker's health");
    assert!(
        w.run_far(heart.cell, heart.origin, 3.0),
        "the heart on foot"
    );
    w.wait(10.0);
    assert_eq!(on_me(&w), 0, "no guard takes the amulet's wearer on");
    assert_eq!(health(&w), whole, "none has struck it");
    // Back on foot to the landing, still let by.
    assert!(
        w.run_far(landing.cell, landing.origin, 3.0),
        "the landing on foot"
    );
    assert_eq!(on_me(&w), 0, "none on the way back");
    assert_eq!(health(&w), whole, "nor struck it");
    // Taken off by the heart, the Nexus Room's guard comes at it.
    w.put(at_heart);
    wear(&mut w);
    assert!(!bears(&w), "taken off, its effect is gone");
    let until = w.h.now.0 + 10.0;
    while on_me(&w) == 0 && w.h.now.0 < until {
        w.h.step();
    }
    assert!(on_me(&w) > 0, "without it the guards come");
    // Worn again, out by the way out beside the landing, to the Skyport by its door.
    wear(&mut w);
    let out = way_out_of(t, LANDING, SKYPORT);
    w.put(landing);
    let back = run_through(&mut w, t, out);
    assert_eq!(back.cell >> 16, SKYPORT, "out to the Skyport");
    let by = ground_distance(&back, &place_of(t, door));
    assert!(by < 10.0, "by the nexus door: {by}");
}

/// **The breach's chaos wisps spare the necklace's ward**: the world lets the ward's bearer by
/// every Empowered Chaos Wisp, and the necklace's use puts the ward on for half an hour. The
/// necklace takes its user to the breach's first part; every spot of the wisps' camps there stands
/// in its own room, the wisp moving there, and is reached on foot; the farthest is run to and back.
/// Played with the wisps standing: the warded walker runs to the camp farthest from the landing and
/// waits there, and back, and no wisp takes it on; the way out beside the landing leads to Rakani.
/// In again by another necklace, the walker waits by that camp: no wisp takes it on while the ward
/// holds, and once its half hour has run out the wisps come.
/// Behaviour: server.world.chaos-breach-wisps-spare-the-ward
#[test]
fn the_breachs_chaos_wisps_let_the_necklaces_ward_by_until_it_runs_out() {
    use yalain_content::creature_rows::{Guards, Pass, SafePassage};
    use yalain_world::usable::maps::ground_distance;
    const WISP: u32 = 0x4700_2DE7;
    const WARD: u32 = 0x6F00_1DEA;
    const NECKLACE: u32 = 0x4700_175A;
    const RAKANI: u32 = 0xC6A1;
    const BREACH: u32 = 0x04BB;
    const LANDING: u32 = 0x04BB_0100;
    let c = compiled();
    let t = &c.tables;
    assert!(
        t.creatures.safe_passage.contains(&SafePassage {
            guards: Guards::Template(WISP),
            pass: Pass::Effect(WARD),
        }),
        "the wisps let the ward's bearer by"
    );
    let camps = pack_camps(c, "chaos-breach-wisps", BREACH);

    // In by the necklace's use, warded; every camp's spots on foot, the farthest and back.
    let mut w = walled(t, &[RAKANI, BREACH]);
    with_uses(&mut w.h, t, &[NECKLACE]);
    w.h.server.creature_rows = t.creatures.clone();
    let world = w.world;
    yalain_world::inventory::give(&mut w.h.server, &mut w.h.net, world, NECKLACE, 1);
    w.h.run(2);
    use_held(&mut w.h, w.b, w.me, NECKLACE);
    w.h.run(260);
    assert_eq!(w.at().cell, LANDING, "the necklace takes its user in");
    let ward = |w: &Walled| {
        w.h.server.players[&world]
            .play
            .effects
            .iter()
            .find(|e| e.state == WARD)
            .copied()
    };
    let on = ward(&w).expect("the necklace's ward is on");
    assert!(
        (on.timeout - 1800.0).abs() < 1.0,
        "for half an hour: {}",
        on.timeout
    );
    let landing = w.at();
    let n = camps_reached_on_foot(c, &mut w, &camps, &[WISP], 1.5);
    assert!(n >= 16, "wisps throughout: {n}");

    // Played: the wisps stand.
    w.put(landing);
    let portal = yalain_testkit::authored::Portal::open();
    w.h.server.catalog.insert(as_installed(&portal, WISP));
    w.h.server.spawns.camps = camps.iter().map(|&i| t.spawns.camps[i].clone()).collect();
    w.h.server.camps = vec![yalain_world::spawn::CampState::default(); camps.len()];
    // The client draws the breach after the trip in: only then may a creature take the walker on.
    w.h.bots[w.b].send(
        true,
        queue::WEENIE,
        &auberean_protocol::ClientMessage::SceneRenderingComplete(auberean_protocol::login::Empty),
    );
    w.wait(5.0);
    assert!(
        w.h.server.players[&world].scene_drawn,
        "the walker is in the world, to be seen"
    );
    let wisps = living_of(&w.h, WISP);
    assert_eq!(
        u32::try_from(wisps.len()).unwrap_or(0),
        n,
        "every wisp stands"
    );
    let me = w.me;
    let on_me = |w: &Walled| {
        wisps
            .iter()
            .filter(|id| {
                w.h.server
                    .things
                    .get(**id)
                    .and_then(|x| x.creature.as_ref())
                    .is_some_and(|c| c.target == Some(me))
            })
            .count()
    };
    let health = |w: &Walled| {
        yalain_world::quals::int(
            &w.h.server.players[&world].qualities,
            yalain_world::player::quality::HEALTH,
        )
    };
    let whole = health(&w);
    assert!(whole.is_some_and(|x| x > 0), "the walker's health");
    let ends = on.cast + f64::from(on.timeout);
    assert!(
        ends - w.h.server.game_now > 300.0,
        "the ward still holds a while"
    );
    let far = camps
        .iter()
        .map(|&i| &t.spawns.camps[i])
        .max_by(|a, b| {
            ground_distance(&spot(a.cell, a.origin), &landing)
                .total_cmp(&ground_distance(&spot(b.cell, b.origin), &landing))
        })
        .expect("a camp");
    assert!(
        w.run_far(far.cell, far.origin, 3.0),
        "the farthest camp on foot"
    );
    w.wait(10.0);
    assert_eq!(on_me(&w), 0, "no wisp takes the ward's bearer on");
    assert_eq!(health(&w), whole, "none has struck it");
    assert!(
        w.run_far(landing.cell, landing.origin, 3.0),
        "the landing on foot"
    );
    assert_eq!(on_me(&w), 0, "none on the way back");
    assert_eq!(health(&w), whole, "nor struck it");

    // Out to Rakani by the way out beside the landing.
    let out = way_out_of(t, LANDING, RAKANI);
    let back = run_through(&mut w, t, out);
    assert_eq!(back.cell >> 16, RAKANI, "out to Rakani");

    // In again by another necklace, and by the farthest camp the ward runs out its half hour:
    // then the wisps come.
    yalain_world::inventory::give(&mut w.h.server, &mut w.h.net, world, NECKLACE, 1);
    w.h.run(2);
    use_held(&mut w.h, w.b, w.me, NECKLACE);
    w.h.run(260);
    assert_eq!(w.at().cell, LANDING, "in again");
    w.h.bots[w.b].send(
        true,
        queue::WEENIE,
        &auberean_protocol::ClientMessage::SceneRenderingComplete(auberean_protocol::login::Empty),
    );
    w.wait(5.0);
    assert!(
        w.h.server.players[&world].scene_drawn,
        "drawn again, to be seen"
    );
    // The last of its records to end (the first use's may still hold).
    let ends = w.h.server.players[&world]
        .play
        .effects
        .iter()
        .filter(|e| e.state == WARD)
        .map(|e| e.cast + f64::from(e.timeout))
        .fold(f64::MIN, f64::max);
    assert!(ends > w.h.server.game_now + 1700.0, "warded again");
    assert!(
        w.run_far(far.cell, far.origin, 3.0),
        "the farthest camp again"
    );
    let until = yalain_net::LocalTime(w.h.now.0 + (ends - w.h.server.game_now) - 5.0);
    w.h.run_to(until);
    assert!(ward(&w).is_some(), "the ward holds to its end");
    assert_eq!(on_me(&w), 0, "and they spare its bearer till then");
    let until = w.h.now.0 + 20.0;
    while on_me(&w) == 0 && w.h.now.0 < until {
        w.h.step();
    }
    assert!(ward(&w).is_none(), "the ward has run out");
    assert!(on_me(&w) > 0, "without the ward the wisps come");
}

