/// **The drudges' cave near Rithwic walks through**: from the land the walker runs in through its
/// mouth on foot; every spot of its camps of drudges and reedsharks stands in its own passage, each
/// kind moving there, and is reached on foot, with the despot alone in a camp of his own; the
/// farthest is run to and back, every report followed; and the walker runs out to the land again.
/// Behaviour: server.world.drudge-hideout-walk-through
#[test]
fn the_drudges_cave_is_walked_in_from_the_land_to_every_camp_and_out() {
    const CAVE: u32 = 0x959E;
    const DESPOT: u32 = 0x4700_23A2;
    let kinds = [
        0x4700_2378,
        0x4700_2389,
        0x4700_2373,
        0x4700_232C,
        0x4700_29EE,
        0x4700_29F3,
        DESPOT,
    ];
    let c = compiled();
    let t = &c.tables;
    let camps = pack_camps(c, "drudge-hideout", CAVE);
    let despots: Vec<_> = camps
        .iter()
        .filter(|&&i| {
            t.spawns.camps[i]
                .templates
                .iter()
                .any(|(k, _)| *k == DESPOT)
        })
        .collect();
    assert_eq!(despots.len(), 1, "one camp holds the despot");
    let despot = &t.spawns.camps[*despots[0]];
    assert_eq!(
        (despot.templates.len(), despot.population),
        (1, 1),
        "the despot alone"
    );
    for &i in &camps {
        let camp = &t.spawns.camps[i];
        assert!(
            camp.spots.iter().all(|(cell, _)| cell & 0xFFFF >= 0x100),
            "{} inside the cave",
            camp.id
        );
    }
    let mut w = walled(t, &[CAVE]);
    let land = spot(0x959E_0024, [89.94, 70.02, 215.2]);
    w.put(land);
    assert!(w.at().cell & 0xFFFF < 0x100, "on the land");
    assert!(w.run_to([87.82, 36.07, 215.5], 2.0), "in through the mouth");
    assert!(w.at().cell & 0xFFFF >= 0x100, "inside the cave");
    let n = camps_reached_on_foot(c, &mut w, &camps, &kinds, 1.0);
    assert!(n >= 25, "the map's dots: {n}");
    assert!(w.run_to(land.origin, 2.0), "out to the land");
    assert!(w.at().cell & 0xFFFF < 0x100, "on the land again");
}

/// Every spot of some camps of a block at least `m` meters from every spot of the block's other
/// camps (its boss, a quest's guards) and from every object placed in it (its landing's ways, a
/// quest's chest).
fn camps_clear_of_the_rest(c: &Compiled, camps: &[usize], block: u32, m: f32) {
    let t = &c.tables;
    let mut others: Vec<(String, [f32; 3])> = t
        .content
        .objects
        .iter()
        .filter(|o| o.cell >> 16 == block)
        .map(|o| (format!("object {:08X}", o.template), o.origin))
        .collect();
    for (i, camp) in t.spawns.camps.iter().enumerate() {
        if camp.cell >> 16 == block && !camps.contains(&i) {
            others.extend(camp.spots.iter().map(|&(_, at)| (camp.id.clone(), at)));
            others.push((camp.id.clone(), camp.origin));
        }
    }
    assert!(!others.is_empty(), "something else in {block:04X}");
    for &i in camps {
        let camp = &t.spawns.camps[i];
        for &(_, at) in &camp.spots {
            for (what, o) in &others {
                use dereth_primitives::num::math::hypotf;
                let d = hypotf(hypotf(at[0] - o[0], at[1] - o[1]), at[2] - o[2]);
                assert!(d >= m, "{}: {at:?} is {d} m from {what}", camp.id);
            }
        }
    }
}

/// A dungeon entered from another block whose way out stands beside its landing, walked: the way in
/// to the landing; the way out the portal of the landing's block nearest it, leading back, within
/// 4 m; every spot of the pack's camps there clear of the dungeon's other camps and objects by 8 m
/// and reached on foot (steps of 1.5 m), of the given kinds alone and all of them, the farthest run
/// to and back; and the way out to the block it came from, within `back_by` m of the way in (where
/// a list of the game's destinations puts its way out). Returns the camps' creatures.
fn landing_dungeon_walk(pack: &str, from: u32, landing: u32, kinds: &[u32], back_by: f32) -> u32 {
    let c = compiled();
    let t = &c.tables;
    let way_in = way_into(t, from, landing);
    let mut w = walled(t, &[from, landing >> 16]);
    let at = through(&mut w, t, way_in);
    assert_eq!(at.cell, landing, "the way in to its landing");
    let (out, by) = t
        .content
        .objects
        .iter()
        .enumerate()
        .filter(|(_, o)| {
            o.template == 0x4700_1154
                && o.cell >> 16 == landing >> 16
                && o.destination.as_ref().is_some_and(|d| d.cell >> 16 == from)
        })
        .map(|(i, _)| {
            (
                i,
                yalain_world::usable::maps::ground_distance(&at, &place_of(t, i)),
            )
        })
        .min_by(|a, b| a.1.total_cmp(&b.1))
        .expect("a way out");
    assert!(by < 4.0, "its way out beside its landing: {by}");
    let camps = pack_camps(c, pack, landing >> 16);
    camps_clear_of_the_rest(c, &camps, landing >> 16, 8.0);
    let creatures = camps_reached_on_foot(c, &mut w, &camps, kinds, 1.5);
    let back = run_through(&mut w, t, out);
    assert_eq!(back.cell >> 16, from, "out to where it came from");
    let by = yalain_world::usable::maps::ground_distance(&back, &place_of(t, way_in));
    assert!(by < back_by, "by the way in: {by}");
    creatures
}

