/// **The grievvers' nest near the Aerie walks through**: its door on the land leads to its landing,
/// its way out beside it; every spot of its camps of Scrawed, Noxious, Baby Virulent, Virulent and
/// Toxic Grievvers stands in its own tunnel clear of the lair's master and its eggs, each kind
/// moving there, and is reached on foot; the Scrawed and Noxious stand nearer the landing than the
/// rest, as the map colors its dots; the farthest is run to and back, every report followed; and
/// the way out leads back to the land by the door.
/// Behaviour: server.world.grievver-nest-walk-through
#[test]
fn the_grievvers_nest_near_the_aerie_is_walked_from_its_door_to_every_camp_and_out() {
    use dereth_primitives::num::math::hypotf;
    const NEST: u32 = 0x09C3;
    const LANDING: [f32; 2] = [-30.75, 4.80];
    let nearer = [0x4700_2592, 0x4700_258E];
    let deeper = [0x4700_259A, 0x4700_2597, 0x4700_2594];
    let c = compiled();
    let (mut near, mut deep) = (Vec::new(), Vec::new());
    for i in pack_camps(c, "grievver-nest-camps", NEST) {
        let camp = &c.tables.spawns.camps[i];
        let mut kinds: Vec<u32> = camp.templates.iter().map(|&(t, _)| t).collect();
        kinds.sort_unstable();
        let side = if kinds == [0x4700_258E, 0x4700_2592] {
            &mut near
        } else {
            assert_eq!(
                kinds,
                [0x4700_2594, 0x4700_2597, 0x4700_259A],
                "{}",
                camp.id
            );
            &mut deep
        };
        side.extend(
            camp.spots
                .iter()
                .map(|&(_, at)| hypotf(at[0] - LANDING[0], at[1] - LANDING[1])),
        );
    }
    let mean = |v: &[f32]| v.iter().sum::<f32>() / v.len() as f32;
    assert!(
        near.len() >= 20 && deep.len() >= 18,
        "both halves: {} and {}",
        near.len(),
        deep.len()
    );
    assert!(
        mean(&near) + 30.0 < mean(&deep),
        "the nearer half nearer the landing: {} and {}",
        mean(&near),
        mean(&deep)
    );
    let kinds: Vec<u32> = nearer.iter().chain(&deeper).copied().collect();
    let n = landing_dungeon_walk("grievver-nest-camps", 0xA949, 0x09C3_0150, &kinds, 4.0);
    assert!(n >= 45, "as many as the map dots: {n}");
}

/// **The hive dungeon's entry halls in the Olthoi Wastes walk through**: its portal on the land
/// leads to its landing, its way out beside it; every spot of its camps of Grub Tender and Worker
/// Nymphs, Drones and Legionary and Noble Grubs stands in one of its six halls clear of the ways
/// on, each kind moving there, and is reached on foot, each hall holding as many as the map dots in
/// it; the farthest is run to and back, every report followed; and the way out leads back to the
/// land by the portal.
/// Behaviour: server.world.hive-entry-halls-walk-through
#[test]
fn the_hive_dungeons_entry_halls_are_walked_from_its_way_in_to_every_camp_and_out() {
    const ENTRY: u32 = 0x06DE;
    let olthoi = [
        0x4700_2956,
        0x4700_2958,
        0x4700_2903,
        0x4700_292C,
        0x4700_2928,
    ];
    let c = compiled();
    // The halls by where they stand: the north and south ends, and a pair on either side between.
    let hall = |at: [f32; 3]| match (at[1], at[0]) {
        (y, _) if y > 330.0 => "north",
        (y, _) if y < -380.0 => "south",
        (y, x) if (40.0..280.0).contains(&y) && x.abs() > 60.0 => "upper",
        (y, x) if (-300.0..-40.0).contains(&y) && x.abs() > 60.0 => "lower",
        _ => "between",
    };
    let mut by_hall = std::collections::BTreeMap::new();
    for i in pack_camps(c, "hive-entry-camps", ENTRY) {
        let camp = &c.tables.spawns.camps[i];
        for &(_, at) in &camp.spots {
            *by_hall.entry(hall(at)).or_insert(0) += 1;
        }
    }
    assert_eq!(
        by_hall.into_iter().collect::<Vec<_>>(),
        [("lower", 52), ("north", 13), ("south", 13), ("upper", 50)],
        "the map's dots, hall by hall"
    );
    let n = landing_dungeon_walk("hive-entry-camps", 0xDAAC, 0x06DE_0101, &olthoi, 4.0);
    assert!(n >= 120, "as many as the map dots in its halls: {n}");
}

/// The five ordinary olthoi of the Olthoi Wastes' hives and of the warren under the northeast one:
/// Harvester, Gardener and Drone Grubs, Harvester and Gardener Nymphs.
const HIVE_OLTHOI: [u32; 5] = [
    0x4700_2936,
    0x4700_0829,
    0x4700_2935,
    0x4700_2957,
    0x4700_2954,
];

/// The walker runs on foot from where it stands to a place in its block, by the places reached on
/// foot from there (steps of a meter, each followed as the server follows a report) to the one
/// nearest the place, within 3 m of it across (a portal's body keeps a walker off its middle) and
/// 2 m up or down.
fn on_foot_to(w: &mut Walled, goal: yalain_store::StoredPosition, what: &str) {
    use yalain_world::usable::maps::ground_distance;
    let (places, from) = reached_on_foot(w, 1.0);
    let near = (0..places.len())
        .filter(|&i| (places[i].origin[2] - goal.origin[2]).abs() <= 2.0)
        .map(|i| (i, ground_distance(&places[i], &goal)))
        .filter(|&(_, d)| d <= 3.0)
        .min_by(|a, b| a.1.total_cmp(&b.1))
        .unwrap_or_else(|| panic!("{what} reached on foot"))
        .0;
    let way: Vec<_> = way_from_first(&from, near)
        .into_iter()
        .map(|i| places[i])
        .collect();
    assert_eq!(w.run_along(&way), way.len(), "on foot to {what}");
}

/// A hive under a mound on the land, walked: from the land outside the mound on foot into it and
/// down to the portal at its bottom, through to the hive's landing; the way out the portal of the
/// landing's block nearest it, leading back into the mound, within 4 m; every spot of the pack's
/// camps in the hive clear of its other camps and objects by 8 m and reached on foot (steps of
/// 1.5 m), of the given kinds alone and all of them, the farthest run to and back; the way out to
/// the mound within `back_by` m of the portal; and from there on foot up through the mound to the
/// land again. Returns the camps' creatures.
fn mound_hive_walk(
    pack: &str,
    land: yalain_store::StoredPosition,
    landing: u32,
    kinds: &[u32],
    back_by: f32,
) -> u32 {
    use yalain_world::usable::maps::ground_distance;
    let c = compiled();
    let t = &c.tables;
    let mound = land.cell >> 16;
    let way_in = way_into(t, mound, landing);
    let mut w = walled(t, &[mound, landing >> 16]);
    w.put(land);
    assert!(w.at().cell & 0xFFFF < 0x100, "on the land");
    on_foot_to(
        &mut w,
        place_of(t, way_in),
        "the portal at the mound's bottom",
    );
    assert!(w.at().cell & 0xFFFF >= 0x100, "inside the mound");
    w.use_placed(t, way_in);
    let at = w.at();
    assert_eq!(at.cell, landing, "the portal to the hive's landing");
    let (out, by) = t
        .content
        .objects
        .iter()
        .enumerate()
        .filter(|(_, o)| {
            o.template == 0x4700_1154
                && o.cell >> 16 == landing >> 16
                && o.destination
                    .as_ref()
                    .is_some_and(|d| d.cell >> 16 == mound)
        })
        .map(|(i, _)| (i, ground_distance(&at, &place_of(t, i))))
        .min_by(|a, b| a.1.total_cmp(&b.1))
        .expect("a way out");
    assert!(by < 4.0, "its way out beside its landing: {by}");
    let camps = pack_camps(c, pack, landing >> 16);
    camps_clear_of_the_rest(c, &camps, landing >> 16, 8.0);
    let creatures = camps_reached_on_foot(c, &mut w, &camps, kinds, 1.5);
    let back = run_through(&mut w, t, out);
    assert_eq!(back.cell >> 16, mound, "out into the mound");
    let by = ground_distance(&back, &place_of(t, way_in));
    assert!(by < back_by, "by the portal: {by}");
    on_foot_to(&mut w, land, "the land outside the mound");
    assert!(w.at().cell & 0xFFFF < 0x100, "on the land again");
    creatures
}

