/// **The dungeon under the Gurog fortress walks through from its landing and out**: the king's death
/// stands the portal that leads to its landing; every spot of its camps of Gurog Elders, Guardians
/// and Protectors stands in its own room clear of the debris the quest searches, each kind moving
/// there, and is reached on foot from the landing; the farthest is run to and back, every report
/// followed; and the way out, at the far end of the landing's room, is run to on foot and leads up
/// to the fortress's plaza by the platform where the king's portal stands.
/// Behaviour: server.world.gurog-undercrofts-walk-through
#[test]
fn the_dungeon_under_the_gurog_fortress_is_walked_from_its_landing_to_every_camp_and_out() {
    use yalain_world::usable::maps::ground_distance;
    const KING: u32 = 0x4700_2663;
    const DUNGEON: u32 = 0x03E6;
    const FORTRESS: u32 = 0x4651;
    const LANDING: u32 = 0x03E6_0100;
    let gurogs = [0x4700_2610, 0x4700_2662, 0x4700_2642];
    let c = compiled();
    let t = &c.tables;
    let portal = t
        .death_spawns
        .get(&yalain_content::DeathSpawn::of_creature(KING))
        .expect("the king's death stands a portal");
    let way_in = portal.to.expect("the king's portal leads in");
    let platform = portal.at.expect("on the platform");
    assert_eq!(way_in.cell, LANDING, "to the landing");
    let camps = pack_camps(c, "undercrofts-camps", DUNGEON);
    camps_clear_of_the_rest(c, &camps, DUNGEON, 8.0);
    let mut w = walled(t, &[DUNGEON, FORTRESS]);
    let landing = spot(way_in.cell, way_in.origin);
    w.put(landing);
    assert_eq!(w.at().cell, LANDING, "on the landing");
    let n = camps_reached_on_foot(c, &mut w, &camps, &gurogs, 1.0);
    assert!(
        n >= 50,
        "as densely as the Gurogs' vault in the mountain: {n}"
    );

    // Out: from the landing on foot along its room to the way out at its far end, and up.
    let outs: Vec<usize> = (0..t.content.objects.len())
        .filter(|&i| {
            let o = &t.content.objects[i];
            o.cell >> 16 == DUNGEON
                && o.destination
                    .as_ref()
                    .is_some_and(|d| d.cell >> 16 == FORTRESS)
        })
        .collect();
    assert_eq!(outs.len(), 1, "one way out");
    let by = ground_distance(&landing, &place_of(t, outs[0]));
    assert!(by < 100.0, "in the landing's room: {by}");
    w.put(landing);
    let back = run_through(&mut w, t, outs[0]);
    assert_eq!(back.cell >> 16, FORTRESS, "up to the fortress");
    let from = ground_distance(&back, &spot(platform.cell, platform.origin));
    assert!(from < 65.0, "on the plaza by the platform: {from}");
}

/// **The renegade fortress's fanatics stand at its map's dots and leave the disguised alone**: the
/// players' map dots 38 fanatics, room by room, and the fortress holds one at each: its guards'
/// six spots in Kogun's room and the renegade lord's, and a camp of Fanatic Mages and Rangers at
/// every other dot (20 in the garbage hall, 4 on the cross on the corridor to Kogun's room, 4 in
/// Kogun's room, 1 in the renegade lord's, and 3 by the wisps' trap), each in its room. Both kinds are of the
/// fanatics' class; the disguise's use puts on its one effect, for three hours and through
/// portals, which the world's rows make that class spare. Every spot stands clear of the fortress's other camps, people and ways, each kind
/// moving there, and is reached on foot from inside the fortress's door or from the inner rooms'
/// landing; the farthest is run to and back. Played with the garbage hall's fanatics standing: the
/// walker uses the disguise, runs to the hall's far end among them and waits, and none takes it on
/// or strikes it; the disguise worn off, they come at it.
/// Behaviour: server.world.renegade-fortress-fanatics-spare-the-disguised
#[test]
fn the_renegade_fortress_fanatics_stand_at_its_maps_dots_and_leave_the_disguised_alone() {
    use yalain_content::creature_rows::Regard;
    const MAGE: u32 = 0x4700_2688;
    const RANGER: u32 = 0x4700_268B;
    const KOGUN: u32 = 0x4700_276C;
    const DISGUISE: u32 = 0x4700_1281;
    const DISGUISED: u32 = 0x6F00_19F1;
    const FANATIC: u32 = 0x59;
    const DOOR: u32 = 0x048F;
    const MAZE: u32 = 0x048E;
    const INNER: u32 = 0x048D;
    const ENTRANCE: u32 = 0x048F_0100;
    const FOOT: u32 = 0xB674;
    const SANCTUM: u32 = 0x048D_0100;
    // Each room by its key and its floor's bounds in the block: x, then y.
    let rooms: [(&str, usize, [f32; 4]); 5] = [
        ("garbage", 20, [-79.3, -40.7, -40.0, 40.0]),
        ("wisp", 3, [14.4, 25.6, -120.2, -100.0]),
        ("cross", 4, [-5.2, 45.2, -100.0, -89.0]),
        ("kogun", 4, [-39.3, 39.3, -225.0, -160.0]),
        ("tanua", 1, [-49.3, 9.3, -347.5, -298.4]),
    ];
    let c = compiled();
    let t = &c.tables;
    let portal = yalain_testkit::authored::Portal::open();
    let kinds = [MAGE, RANGER];
    for k in kinds {
        let props = as_installed(&portal, k).props;
        assert_eq!(props.word("AI_AISuperClass"), Some(FANATIC), "{k:08X}");
    }
    let used = portal.item_uses(&[DISGUISE]);
    let puts: Vec<u32> = used
        .get(&DISGUISE)
        .map(|l| l.iter().map(|e| e.state).collect())
        .unwrap_or_default();
    assert_eq!(puts, [DISGUISED], "the disguise's use puts on its effect");
    assert_eq!(
        t.creatures.concealing.get(&(DISGUISED, Some(FANATIC))),
        Some(&Regard::Spares),
        "which the fanatics spare"
    );

    // Room by room, the map's dots.
    let door = pack_camps(c, "renegade-fortress-camps", DOOR);
    let inner = pack_camps(c, "renegade-fortress-camps", INNER);
    let guards: usize = pack_camps(c, "aun-tanua-fortress", INNER)
        .iter()
        .map(|&i| &t.spawns.camps[i])
        .filter(|k| !k.templates.iter().any(|(x, _)| *x == KOGUN))
        .map(|k| k.spots.len())
        .sum();
    assert_eq!(guards + door.len() + inner.len(), 38, "the map's dots");
    for (room, n, [x0, x1, y0, y1]) in rooms {
        let prefix = format!("atl-{room}-");
        let these: Vec<&yalain_content::spawns::Camp> = door
            .iter()
            .chain(&inner)
            .map(|&i| &t.spawns.camps[i])
            .filter(|k| k.id.starts_with(&prefix))
            .collect();
        assert_eq!(these.len(), n, "{room}: the map's dots less the guards'");
        for k in these {
            assert_eq!(k.population, 1, "{}: one at a dot", k.id);
            for &(_, at) in &k.spots {
                assert!(
                    (x0..=x1).contains(&at[0]) && (y0..=y1).contains(&at[1]),
                    "{}: {at:?} in its room",
                    k.id
                );
            }
        }
    }
    camps_clear_of_the_rest(c, &door, DOOR, 8.0);
    camps_clear_of_the_rest(c, &inner, INNER, 8.0);

    // On foot: inside the door, by the way out beside the way in; the inner rooms from their landing.
    let mut w = walled(t, &[DOOR, INNER]);
    let inside = place_of(t, way_out_of(t, ENTRANCE, FOOT));
    w.put(inside);
    assert_eq!(w.at().cell, ENTRANCE, "inside the door");
    let n = camps_reached_on_foot(c, &mut w, &door, &kinds, 1.0);
    assert_eq!(n, 23, "the halls inside the door");
    let landing = t.content.objects[way_to(t, MAZE, SANCTUM)]
        .destination
        .expect("the maze's real portal leads in");
    w.put(spot(landing.cell, landing.origin));
    assert_eq!(w.at().cell, SANCTUM, "on the inner rooms' landing");
    let n = camps_reached_on_foot(c, &mut w, &inner, &kinds, 1.0);
    assert_eq!(n, 9, "the inner rooms");

    // Played: the garbage hall's fanatics stand, and the walker uses the disguise.
    let hall: Vec<usize> = door
        .iter()
        .copied()
        .filter(|&i| t.spawns.camps[i].id.starts_with("atl-garbage-"))
        .collect();
    w.h.server.creature_rows = t.creatures.clone();
    for k in kinds {
        w.h.server.catalog.insert(as_installed(&portal, k));
    }
    w.h.server.spawns.camps = hall.iter().map(|&i| t.spawns.camps[i].clone()).collect();
    w.h.server.camps = vec![yalain_world::spawn::CampState::default(); hall.len()];
    with_uses(&mut w.h, t, &[DISGUISE]);
    let world = w.world;
    yalain_world::inventory::give(&mut w.h.server, &mut w.h.net, world, DISGUISE, 1);
    w.h.run(2);
    use_held(&mut w.h, w.b, w.me, DISGUISE);
    let bears = |w: &Walled| {
        w.h.server.players[&world]
            .play
            .effects
            .iter()
            .any(|e| e.state == DISGUISED)
    };
    assert!(bears(&w), "used, the disguise is on");
    let lasts = w.h.server.players[&world]
        .play
        .effects
        .iter()
        .find(|e| e.state == DISGUISED)
        .map_or(0.0, |e| e.timeout);
    assert!((lasts - 10_800.0).abs() < 1.0, "for three hours: {lasts}");
    let def = w.h.server.effect_table.get(DISGUISED).expect("read");
    assert!(!def.ends_at_teleport, "through the fortress's portals");
    // The hall's near end, where its corridor comes in, and its far end, by the garbage portal's way.
    let near_end = [-60.0, -37.0, 101.0];
    let far_end = [-60.0, 37.0, 101.0];
    let start = t.spawns.camps[hall[0]].spots[0];
    w.put(spot(start.0, start.1));
    assert!(w.run_to(near_end, 3.0), "the hall's near end");
    w.wait(5.0);
    let fanatics: Vec<u64> = kinds.iter().flat_map(|&k| living_of(&w.h, k)).collect();
    assert_eq!(fanatics.len(), 20, "every one stands");
    let me = w.me;
    let on_me = |w: &Walled| {
        fanatics
            .iter()
            .filter(|id| {
                w.h.server
                    .things
                    .get(**id)
                    .and_then(|x| x.creature.as_ref())
                    .is_some_and(|c| c.target == Some(me))
            })
            .count()
    };
    let health = |w: &Walled| {
        yalain_world::quals::int(
            &w.h.server.players[&world].qualities,
            yalain_world::player::quality::HEALTH,
        )
    };
    let whole = health(&w);
    assert!(whole.is_some_and(|x| x > 0), "the walker's health");
    assert!(w.run_to(far_end, 3.0), "among them to the far end");
    w.wait(10.0);
    assert_eq!(on_me(&w), 0, "none takes the disguised on");
    assert_eq!(health(&w), whole, "none has struck it");
    // The disguise worn off, they come.
    if let Some(p) = w.h.server.players.get_mut(&world) {
        p.play.effects.retain(|e| e.state != DISGUISED);
    }
    assert!(!bears(&w), "worn off");
    let until = w.h.now.0 + 10.0;
    while on_me(&w) == 0 && w.h.now.0 < until {
        w.h.step();
    }
    assert!(on_me(&w) > 0, "without it the fanatics come");
}

/// **Dianech's house and its hidden archive walk through**: the house's door on the island leads to
/// its landing, its way back beside it; every spot of the house's camps of Imperial Servitor Guards
/// stands in its own room clear of the quest's guards, people and doors, the guard moving there, and
/// is reached on foot; the farthest is run to and back, every report followed, and the way back
/// leads out by the door. The bookcase's hidden door leads to the archive's landing, from which
/// every spot of the archive's camps, all in its middle part short of the Skyport's defenses and
/// outside the amulet droppers' wing, is reached on foot the same way.
/// Behaviour: server.world.skyport-mansion-walk-through
#[test]
fn dianechs_house_and_its_hidden_archive_are_walked_from_their_landings_to_every_camp() {
    use yalain_world::usable::maps::ground_distance;
    const ISLAND: u32 = 0x9F5E;
    const HOUSE: u32 = 0x06C3;
    const LANDING: u32 = 0x06C3_0113;
    const BOOKCASE_ID: u64 = 0x4006_C300_0000_00F1;
    // The archive's part past the Skyport's defenses, and the amulet droppers' wing beside it.
    const DEFENSES: f32 = -120.0;
    const WING: f32 = -15.0;
    let guards = [0x4700_2AA5];
    let c = compiled();
    let t = &c.tables;
    let camps = pack_camps(c, "skyport-mansion-camps", HOUSE);
    camps_clear_of_the_rest(c, &camps, HOUSE, 8.0);
    let part = |prefix: &str| -> Vec<usize> {
        camps
            .iter()
            .copied()
            .filter(|&i| t.spawns.camps[i].id.starts_with(prefix))
            .collect()
    };
    let (house, archive) = (part("mansion-house-"), part("mansion-archive-"));
    assert_eq!(
        house.len() + archive.len(),
        camps.len(),
        "the house's or the archive's"
    );
    for &i in &archive {
        let camp = &t.spawns.camps[i];
        for &(_, at) in &camp.spots {
            assert!(
                at[1] < DEFENSES && at[0] < WING,
                "{}: {at:?} in the archive's middle part",
                camp.id
            );
        }
    }
    let way_in = way_into(t, ISLAND, LANDING);
    let mut w = walled(t, &[ISLAND, HOUSE]);
    let at = through(&mut w, t, way_in);
    assert_eq!(at.cell, LANDING, "the door to the house's landing");
    let out = (0..t.content.objects.len())
        .find(|&i| {
            let o = &t.content.objects[i];
            o.cell >> 16 == HOUSE
                && o.destination
                    .as_ref()
                    .is_some_and(|d| d.cell >> 16 == ISLAND)
        })
        .expect("the house's way back");
    let by = ground_distance(&at, &place_of(t, out));
    assert!(by < 4.0, "its way back beside its landing: {by}");
    let n = camps_reached_on_foot(c, &mut w, &house, &guards, 1.0);
    assert!(
        n >= 7,
        "the map's dots in the house less the key guards: {n}"
    );
    let back = run_through(&mut w, t, out);
    assert_eq!(back.cell >> 16, ISLAND, "out to the island");
    let by = ground_distance(&back, &place_of(t, way_in));
    assert!(by < 4.0, "by the door: {by}");
    let archive_in = t
        .content
        .objects
        .iter()
        .find(|o| o.object == Some(BOOKCASE_ID))
        .and_then(|o| o.destination)
        .expect("the bookcase leads to the archive");
    assert_eq!(archive_in.cell >> 16, HOUSE, "within the house's block");
    w.put(spot(archive_in.cell, archive_in.origin));
    let n = camps_reached_on_foot(c, &mut w, &archive, &guards, 1.0);
    assert!(
        n >= 16,
        "the map's dots in the archive less the amulet guards: {n}"
    );
}

/// **The Order's lost scholars walk through**: the quest's giver gives it; the scholars' remains lie
/// where January 2017's recordings found them, each on ground a body moves from, one of them at a
/// time. Searched before the quest is given, the one lying stays; one not lying gives nothing; the
/// one lying gives the chest's key and moves the quest on, crumbles, and after a while another lies
/// in a different place. The chest stands in the scholars' camp, reached on foot
/// from its middle, refuses a plain use while locked, and the key used on it opens it, moving the
/// quest on, with the surveying device and the notebook inside. The device, used away from where it
/// leads, is refused and kept; used there it sets down the summoning device, which no player may
/// harm and its row's attackers come for; defended (each attacker killed as it comes) it holds its
/// time, goes, and leaves the portal to the tunnels, which takes the player to their landing and
/// moves the quest to its last phase. From the landing the boss's room is reached on foot; the boss
/// stands there alone and, fallen near the player, opens the rupture beside its place, which ends
/// the quest, gives the next and takes the player to the island; the rupture goes at its time.
/// Behaviour: server.quests.osteth-fate-of-the-scholars-walk-through
#[test]
fn the_lost_scholars_are_followed_from_their_remains_through_the_defended_device_to_the_island() {
    use yalain_content::quests::{Trigger, Update};
    use yalain_world::quests::status;
    const QUEST: u32 = 0x4000_033B;
    const NEXT: u32 = 0x4000_0337;
    const GIVER: u32 = 0x4700_2F55;
    const CORPSE: u32 = 0x4700_12FC;
    const KEY: u32 = 0x4700_10CF;
    const CHEST: u32 = 0x4700_0EFD;
    const SURVEYOR: u32 = 0x4700_1318;
    const NOTEBOOK: u32 = 0x4700_0E38;
    const DEVICE: u32 = 0x4700_29A1;
    const TUNNELS: u32 = 0x4700_1304;
    const BOSS: u32 = 0x4700_2232;
    const RUPTURE: u32 = 0x4700_1307;
    /// The kinds the wiki says attack the device.
    const ATTACKERS: [u32; 3] = [0x4700_2D35, 0x4700_21CD, 0x4700_2AFD];
    const CAMP: u32 = 0x677B;
    const TUNNELS_BLOCK: u32 = 0x07F0;
    const ISLAND: u32 = 0x6884;
    let t = &compiled().tables;
    let portal = yalain_testkit::authored::Portal::open();
    let install = dat_install();
    let objects = &t.content.objects;

    // The remains: statics in the delta, each where a body moves from, and their use's step.
    let remains: Vec<usize> = (0..objects.len())
        .filter(|&i| objects[i].template == CORPSE)
        .collect();
    assert_eq!(remains.len(), 11, "every place 2017 found the remains");
    let shift = t
        .content
        .shifting
        .rows
        .iter()
        .find(|r| r.objects.contains(&remains[0]))
        .expect("the remains shift");
    let mut shifted = shift.objects.clone();
    shifted.sort_unstable();
    assert_eq!(shifted, remains, "one row moves all of them");
    let gone_for = shift
        .gone_for
        .expect("none lies for a while after a search");
    assert!(
        shift.moves_after.is_none(),
        "one unsearched stays where it lies"
    );
    let step = t
        .quests
        .steps
        .iter()
        .find(|s| s.quest == QUEST && s.trigger == Trigger::Use(CORPSE))
        .expect("the remains' step");
    assert_eq!(
        (step.needs, step.update),
        (1, Update::Advance(2)),
        "the remains at the first phase"
    );
    assert_eq!(step.gives, [KEY], "the remains give the key");
    let mut walls = spot_walls();
    let records = super::invariants::world_records();
    walls.player_walker =
        yalain_world::walls::setup_walker(&records, HUMAN_BODY, 1.0).expect("the body");
    for &i in &remains {
        let o = &objects[i];
        let ways = ways_off(&mut walls, &place_of(t, i));
        assert!(ways >= 4, "{:08X}: {ways} ways off", o.cell);
    }
    // The chest in the camp, its key and its two treasures.
    let chest_i = placed(t, CHEST);
    assert_eq!(objects[chest_i].cell >> 16, CAMP, "the chest in the camp");
    let chest_t = as_installed(&portal, CHEST);
    let key_t = as_installed(&portal, KEY);
    assert_eq!(
        chest_t.props.word("Lock_KeyID"),
        key_t.props.word("Lock_KeyID"),
        "the key fits the chest"
    );
    for item in [SURVEYOR, NOTEBOOK] {
        assert!(
            t.loot.treasures.iter().any(|d| d.item == item
                && d.chance >= 1.0
                && d.from == yalain_content::loot::Dropper::Template(CHEST)),
            "{item:08X} in the chest"
        );
    }
    // The device: what the surveyor's use makes, its row, and players kept from harming it.
    let spawn = t
        .death_spawns
        .get("Eff_CreateTransitCCP")
        .expect("the device's row");
    assert_eq!(
        spawn.template, DEVICE,
        "the surveyor's use sets down the device"
    );
    let row = t
        .content
        .defenses
        .rows
        .iter()
        .find(|r| r.device == DEVICE)
        .expect("its defense")
        .clone();
    assert_eq!(
        row.then,
        Some(TUNNELS),
        "it leaves the portal to the tunnels"
    );
    let mut kinds: Vec<u32> = row.spawns.iter().map(|s| s.0).collect();
    kinds.sort_unstable();
    let mut wiki = ATTACKERS;
    wiki.sort_unstable();
    assert_eq!(kinds, wiki, "the wiki's attackers");
    assert!(
        t.creatures.kept_out.contains_key(&DEVICE),
        "no player may harm it"
    );
    // The tunnels: their landing, the boss's camp alone, the rupture an event's.
    let landing = t.places_named.get(&TUNNELS).expect("the tunnels' landing");
    assert_eq!(
        landing.cell >> 16,
        TUNNELS_BLOCK,
        "the landing in the tunnels"
    );
    let boss: Vec<&yalain_content::spawns::Camp> = t
        .spawns
        .camps
        .iter()
        .filter(|c| c.templates.iter().any(|(x, _)| *x == BOSS))
        .collect();
    assert_eq!(boss.len(), 1, "one camp keeps the boss");
    assert_eq!((boss[0].population, boss[0].templates.len()), (1, 1));
    assert_eq!(boss[0].cell >> 16, TUNNELS_BLOCK);
    let rupture = placed(t, RUPTURE);
    assert_eq!(objects[rupture].cell >> 16, TUNNELS_BLOCK);
    let island = objects[rupture].destination.expect("the rupture's island");
    assert_eq!(island.cell >> 16, ISLAND, "the rupture leads to the island");

    // On foot: the chest from the camp's middle; the boss's room and the rupture from the landing.
    let mut w = walled(t, &[CAMP]);
    w.put(spot(objects[chest_i].cell, [60.0, 90.0, 113.5]));
    assert!(
        w.run_to(objects[chest_i].origin, 2.0),
        "the chest reached from the camp's middle"
    );
    let mut w = walled(t, &[TUNNELS_BLOCK]);
    w.put(spot(landing.cell, landing.origin));
    assert!(w.run_to(boss[0].origin, 3.0), "the boss's room on foot");
    assert!(
        w.run_to(objects[rupture].origin, 2.0),
        "the rupture's place on foot"
    );
    let mut walls = spot_walls();
    let at_boss = spot(boss[0].cell, boss[0].origin);
    assert!(
        moves_from(&mut walls, &portal, BOSS, &at_boss) >= 0.5,
        "the boss moves from its place"
    );

    // Played.
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    set_level(&mut h, 60);
    let world = player_world(&h);
    h.server.loot = t.loot.clone();
    with_uses(&mut h, t, &[SURVEYOR, TUNNELS, RUPTURE]);
    h.server.death_spawns = t
        .death_spawns
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    h.server.creature_rows = t.creatures.clone();
    h.server.chests.packages.insert(chest_t.description.package);
    for item in [
        CORPSE, SURVEYOR, NOTEBOOK, DEVICE, TUNNELS, RUPTURE, BOSS, KEY,
    ]
    .iter()
    .chain(&ATTACKERS)
    {
        h.server.catalog.insert(as_installed(&portal, *item));
    }
    h.server.catalog.insert(chest_t);
    let ids_of = |h: &Harness, item: u32| -> Vec<u64> {
        h.server.players[&world]
            .play
            .items
            .iter()
            .filter(|i| i.template == item)
            .map(|i| i.id)
            .collect()
    };
    let living = |h: &Harness, template: u32| -> Vec<u64> {
        h.server
            .things
            .by_id
            .values()
            .filter(|x| x.template == template && x.at.is_some() && x.alive())
            .filter(|x| {
                x.creature
                    .as_ref()
                    .is_none_or(|c| c.mode != yalain_world::things::Mode::Dead)
            })
            .map(|x| x.id)
            .collect()
    };
    let use_now = |h: &mut Harness, item: u64| {
        h.bots[b].send(
            true,
            queue::WEENIE,
            &server_call(0x8216_0016, &[use_of(item, me)]),
        );
        h.run(20);
        let until = h.now.0 + 4.0;
        while h.now.0 < until {
            h.step();
        }
    };
    let stand_at = |h: &mut Harness, at: yalain_store::StoredPosition| {
        let p = h.server.players.get_mut(&world).expect("in");
        p.position.cell = at.cell;
        p.position.origin = at.origin;
    };

    // The remains: one lies at a time; searched before the quest is given, it stays.
    let lying = |h: &Harness| -> Vec<usize> {
        remains
            .iter()
            .copied()
            .filter(|&i| !yalain_world::shifting::hides(&h.server, i))
            .collect()
    };
    world_step(&mut h);
    let [first] = lying(&h)[..] else {
        panic!("one of the remains lies: {:?}", lying(&h));
    };
    use_person(&mut h, b, me, t, first);
    assert_eq!(state_of(&h, QUEST), None, "nothing before the quest");
    assert!(!holds_item(&h, KEY));
    assert_eq!(lying(&h), [first], "unsearched, it stays");

    use_person(&mut h, b, me, t, placed(t, GIVER));
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)), "given");
    let away = h.server.players[&world].position;
    let elsewhere = *remains.iter().find(|&&i| i != first).expect("another");
    use_person(&mut h, b, me, t, elsewhere);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 1)),
        "remains not lying give nothing"
    );
    assert!(!holds_item(&h, KEY));
    use_person(&mut h, b, me, t, first);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 2)),
        "the remains"
    );
    assert!(holds_item(&h, KEY), "the chest's key");
    assert!(lying(&h).is_empty(), "crumbled, and none lies");
    let wait = |h: &mut Harness, seconds: f64| {
        let until = h.now.0 + seconds;
        while h.now.0 < until {
            h.step();
        }
    };
    wait(&mut h, gone_for - 5.0);
    assert!(lying(&h).is_empty(), "none lies for a while");
    wait(&mut h, 10.0);
    let [next] = lying(&h)[..] else {
        panic!("another lies: {:?}", lying(&h));
    };
    assert_ne!(next, first, "somewhere else");

    // The chest: shut to a plain use, opened by its key, the quest moved on as it opens.
    let chest = yalain_world::presence::content_id(objects, chest_i);
    let o = &objects[chest_i];
    stand_at(
        &mut h,
        spot(o.cell, [o.origin[0] + 1.5, o.origin[1], o.origin[2]]),
    );
    h.bots[b].send(
        true,
        queue::WEENIE,
        &server_call(0x8216_0016, &[use_of(chest, me)]),
    );
    h.run(40);
    assert!(
        yalain_world::usable::chests::contents(&h.server, chest).is_none(),
        "locked to a plain use"
    );
    assert_eq!(state_of(&h, QUEST).map(|q| q.1), Some(2));
    let key = ids_of(&h, KEY)[0];
    h.bots[b].send(
        true,
        queue::WEENIE,
        &server_call(0x8216_0016, &[use_on(key, me, chest)]),
    );
    let until = h.now.0 + 4.0;
    while h.now.0 < until {
        h.step();
    }
    assert!(ids_of(&h, KEY).is_empty(), "the key used up unlocking it");
    h.bots[b].send(
        true,
        queue::WEENIE,
        &server_call(0x8216_0016, &[use_of(chest, me)]),
    );
    assert!(
        h.run_until(400, |h| yalain_world::usable::chests::contents(
            &h.server, chest
        )
        .is_some_and(|c| !c.is_empty())),
        "unlocked, it opens"
    );
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 3)), "opened");
    let inside = yalain_world::usable::chests::contents(&h.server, chest).expect("open");
    let mut held: Vec<u32> = inside
        .iter()
        .filter_map(|i| h.server.things.get(*i).map(|x| x.template))
        .collect();
    held.sort_unstable();
    assert_eq!(held, [NOTEBOOK, SURVEYOR], "the device and the notebook");
    // Its opening plays out.
    let until = h.now.0 + 3.0;
    while h.now.0 < until {
        h.step();
    }
    assert_eq!(
        yalain_world::inventory::open_corpse_of(&h.server, world),
        Some(chest),
        "open to its opener"
    );
    h.bots[b].send(
        true,
        queue::WEENIE,
        &server_call(
            yalain_world::pack::function::TAKE_ALL,
            &[take_all_request(chest, me)],
        ),
    );
    // The taking plays out.
    let until = h.now.0 + 4.0;
    while h.now.0 < until {
        h.step();
    }
    assert!(
        holds_item(&h, SURVEYOR) && holds_item(&h, NOTEBOOK),
        "both taken"
    );

    // The surveying device: kept away from its place; there, the summoning device set down.
    let surveyor = ids_of(&h, SURVEYOR)[0];
    stand_at(&mut h, away);
    use_now(&mut h, surveyor);
    assert_eq!(ids_of(&h, SURVEYOR), [surveyor], "away, kept");
    assert!(living(&h, DEVICE).is_empty(), "and nothing set down");
    let place = h
        .server
        .things
        .get(surveyor)
        .and_then(|m| m.destination)
        .expect("its place, chosen at its first use");
    assert_eq!(place.cell >> 16 & 0xFF00, CAMP & 0xFF00, "in the delta");
    stand_at(&mut h, place);
    use_now(&mut h, surveyor);
    assert!(ids_of(&h, SURVEYOR).is_empty(), "there, spent");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 4)), "set down");
    let device = living(&h, DEVICE);
    assert_eq!(device.len(), 1, "the summoning device");
    let device = device[0];
    let came = h.now.0;

    // Defended: each attacker killed as it comes; the device holds and leaves the portal.
    let mut came_at = 0usize;
    while h.now.0 < came + row.holds + 2.0 {
        for _ in 0..4 {
            h.step();
        }
        let clock = h.clock();
        for kind in ATTACKERS {
            for a in living(&h, kind) {
                came_at += 1;
                yalain_world::combat::hurt_creature(
                    &mut h.server,
                    &mut h.net,
                    a,
                    me,
                    1_000_000,
                    clock,
                );
            }
        }
        // The device came as the use played out, before `came`.
        if h.now.0 < came + row.holds - 5.0 {
            assert!(
                h.server.things.get(device).is_some_and(|x| x.alive()),
                "the device stands its time"
            );
        }
    }
    assert!(
        u32::try_from(came_at).unwrap_or(u32::MAX) >= row.population,
        "its attackers came: {came_at}"
    );
    assert!(
        h.server.things.get(device).is_none_or(|x| !x.alive()),
        "gone once it has held"
    );
    let ways: Vec<u64> = h
        .server
        .things
        .by_id
        .values()
        .filter(|x| x.template == TUNNELS && x.at.is_some())
        .map(|x| x.id)
        .collect();
    assert_eq!(ways.len(), 1, "the portal to the tunnels in its place");
    use_thing(&mut h, b, me, ways[0]);
    h.run(100);
    assert_eq!(
        h.server.players[&world].position.cell >> 16,
        TUNNELS_BLOCK,
        "into the tunnels"
    );
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 5)),
        "the last phase"
    );

    // The boss fallen near the player opens the rupture, which ends the quest and gives the next.
    assert!(
        yalain_world::events::hides(&h.server, rupture),
        "no rupture while the boss stands"
    );
    for p in h.server.players.values_mut() {
        p.scene_drawn = true;
    }
    killed_as(&mut h, me, BOSS, &install);
    world_step(&mut h);
    assert!(
        !yalain_world::events::hides(&h.server, rupture),
        "the rupture opens"
    );
    use_person(&mut h, b, me, t, rupture);
    h.run(100);
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "ended at the rupture"
    );
    assert_eq!(
        state_of(&h, NEXT),
        Some((status::UNDERWAY, 1)),
        "the next given"
    );
    assert_eq!(
        h.server.players[&world].position.cell >> 16,
        ISLAND,
        "to the island"
    );
    h.unix += 301;
    world_step(&mut h);
    assert!(
        yalain_world::events::hides(&h.server, rupture),
        "the rupture gone at its time"
    );
}

/// The living creatures of a template in the world.
fn living_of(h: &Harness, template: u32) -> Vec<u64> {
    let mut v: Vec<u64> = h
        .server
        .things
        .by_id
        .values()
        .filter(|x| x.template == template)
        .filter(|x| {
            x.creature
                .as_ref()
                .is_some_and(|c| c.mode != yalain_world::things::Mode::Dead)
        })
        .map(|x| x.id)
        .collect();
    v.sort_unstable();
    v
}

/// The portals of a template standing in the world.
fn portals_of(h: &Harness, template: u32) -> Vec<u64> {
    h.server
        .things
        .by_id
        .values()
        .filter(|x| x.template == template && x.kind == yalain_world::things::Kind::Portal)
        .map(|x| x.id)
        .collect()
}

/// **The Dominion's mine raids walk from its headquarters' beacons through a bore's defense to the
/// portal home**: each crystal's use names a bore of the world's rows, and each bore keeps the
/// golems of its mine at it for ten minutes and leaves its raiders' portal home, for their kingdom
/// alone; Linvak's beacons are for heroes alone, Omishan's not; the Dominion's four beacons stand
/// in its headquarters, each reached on foot from its way in. A player of another kingdom is given
/// nothing, and so is a Dominion player who is no hero; a Dominion hero is given the Linvak raid and
/// its crystal, and a second beacon gives nothing within the hour. The crystal is kept away from its
/// mine; at it the bore comes four meters ahead, the raid moves to its second phase, and the bore's
/// four golems come at it; killed, each is replaced, and once the bore has stood its ten minutes it
/// goes and the portal home stands there, which refuses a player of another kingdom and takes the
/// raider to the headquarters, ending the raid. An hour on, the second beacon gives the raid again;
/// that bore killed first leaves nothing, the raid stays, and an hour on the beacon gives another
/// crystal. An hour on, to one who is no hero, Linvak's beacon gives nothing and Omishan's its raid,
/// whose bore draws its own mine's golems.
/// Behaviour: server.quests.linvak-omishan-mine-raids-walk-through
#[test]
fn the_dominions_mine_raids_walk_from_its_headquarters_beacons_through_a_bores_defense_to_the_portal_home(
) {
    use yalain_world::quests::status;
    use yalain_world::usable::maps::ground_distance;
    const LIN_RAID: u32 = 0x4000_0354;
    const OMI_RAID: u32 = 0x4000_0355;
    const PERMISSION: u32 = 0x4000_0359;
    const HQ: u32 = 0x0BF4;
    // The Dominion's beacons, each with the crystal it hands over and the bore that crystal calls.
    const BEACONS: [(u32, u32, u32); 4] = [
        (0x4700_1480, 0x4700_146D, 0x4700_342B),
        (0x4700_1481, 0x4700_146F, 0x4700_342C),
        (0x4700_1486, 0x4700_1474, 0x4700_3431),
        (0x4700_1487, 0x4700_1475, 0x4700_3432),
    ];
    // Every crystal and the bore it calls, with the raiders' portal home that bore leaves.
    const BORES: [(u32, u32, u32); 12] = [
        (0x4700_146D, 0x4700_342B, 0x4700_14A1),
        (0x4700_146F, 0x4700_342C, 0x4700_14A1),
        (0x4700_1470, 0x4700_342D, 0x4700_14A2),
        (0x4700_1471, 0x4700_342E, 0x4700_14A2),
        (0x4700_1472, 0x4700_342F, 0x4700_14A3),
        (0x4700_1473, 0x4700_3430, 0x4700_14A3),
        (0x4700_1474, 0x4700_3431, 0x4700_149E),
        (0x4700_1475, 0x4700_3432, 0x4700_149E),
        (0x4700_1476, 0x4700_3433, 0x4700_149F),
        (0x4700_1477, 0x4700_3434, 0x4700_149F),
        (0x4700_1478, 0x4700_3435, 0x4700_14A0),
        (0x4700_1479, 0x4700_3436, 0x4700_14A0),
    ];
    // Each portal home and the kingdom it is for: the Dominion's, the Order's, the Shadow's.
    const HOMES: [(u32, u32); 6] = [
        (0x4700_149E, 4),
        (0x4700_149F, 2),
        (0x4700_14A0, 1),
        (0x4700_14A1, 4),
        (0x4700_14A2, 2),
        (0x4700_14A3, 1),
    ];
    const LIN_GOLEMS: [u32; 4] = [0x4700_24E1, 0x4700_24D4, 0x4700_24EF, 0x4700_24DA];
    const OMI_GOLEMS: [u32; 4] = [0x4700_24C4, 0x4700_24EC, 0x4700_24EA, 0x4700_24F1];
    let t = &compiled().tables;
    let authored = yalain_testkit::authored::Portal::open();
    let defense = |bore: u32| {
        t.content
            .defenses
            .rows
            .iter()
            .find(|d| d.device == bore)
            .unwrap_or_else(|| panic!("{bore:08X} defended"))
    };
    for (crystal, bore, home) in BORES {
        let props = as_installed(&authored, crystal).props;
        let name = props
            .text("Usage_Effect1")
            .expect("names its bore")
            .to_string();
        assert_eq!(
            t.death_spawns.get(&name).map(|s| s.template),
            Some(bore),
            "{crystal:08X}'s {name}"
        );
        let d = defense(bore);
        assert!((d.holds - 600.0).abs() < 1e-6, "{bore:08X} ten minutes");
        assert_eq!((d.then, d.population), (Some(home), 4), "{bore:08X}");
        let golems = if bore < 0x4700_3431 {
            LIN_GOLEMS
        } else {
            OMI_GOLEMS
        };
        assert_eq!(
            d.spawns.iter().map(|(x, _)| *x).collect::<Vec<_>>(),
            golems,
            "{bore:08X}'s mine's golems"
        );
    }
    for (home, kingdom) in HOMES {
        assert_eq!(
            yalain_world::usable::portals::required_kingdom(&as_installed(&authored, home).props),
            Some(kingdom),
            "{home:08X} for its kingdom alone"
        );
    }
    // Linvak's beacons' steps for heroes alone, Omishan's for anyone of their kingdom.
    let beacon_steps = |quest: u32| -> Vec<&yalain_content::quests::Step> {
        t.quests
            .steps
            .iter()
            .filter(|s| {
                s.quest == quest
                    && BEACONS
                        .iter()
                        .any(|b| s.trigger == yalain_content::quests::Trigger::Use(b.0))
            })
            .collect()
    };
    let gates = &t.content.hero_gates;
    let lin = beacon_steps(LIN_RAID);
    assert_eq!(lin.len(), 6, "Linvak's beacons' steps");
    assert!(
        lin.iter().all(|s| gates.of_step(s)),
        "Linvak's beacons for heroes alone"
    );
    let omi = beacon_steps(OMI_RAID);
    assert_eq!(omi.len(), 6, "Omishan's beacons' steps");
    assert!(
        !omi.iter().any(|s| gates.of_step(s)),
        "Omishan's for anyone"
    );
    let way_in = way_to(t, 0xD08B, 0x0BF4_010F);
    let arrival = t.content.objects[way_in].destination.expect("a landing");
    let hq_place = t
        .places_by_name
        .get("dng_dominionhq")
        .expect("the headquarters");
    assert!(
        ground_distance(
            &spot(hq_place.cell, hq_place.origin),
            &spot(arrival.cell, arrival.origin)
        ) < 1.0,
        "the portals home lead where the way in does"
    );
    let beacon_at = |template: u32| {
        let i = placed(t, template);
        assert_eq!(
            t.content.objects[i].cell >> 16,
            HQ,
            "{template:08X} in the headquarters"
        );
        i
    };

    // On foot from the way in to each beacon.
    let mut w = walled(t, &[HQ]);
    w.put(spot(arrival.cell, arrival.origin));
    for (beacon, _, _) in BEACONS {
        let o = t.content.objects[beacon_at(beacon)].clone();
        assert!(w.run_to(o.origin, 3.0), "{beacon:08X} reached on foot");
        w.put(spot(arrival.cell, arrival.origin));
    }

    // The raid, its crystal, its bore and its defense.
    let mut items: Vec<u32> = BORES.iter().map(|b| b.0).collect();
    items.extend(BEACONS.iter().map(|b| b.0));
    with_uses(&mut w.h, t, &items);
    w.h.server.quest_ids = quest_ids();
    w.h.server.kingdom_rows = t.kingdoms.clone();
    w.h.server.death_spawns = t
        .death_spawns
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    for (_, bore, home) in BORES {
        w.h.server.catalog.insert(as_installed(&authored, bore));
        w.h.server.catalog.insert(as_installed(&authored, home));
    }
    for golem in LIN_GOLEMS.iter().chain(&OMI_GOLEMS) {
        w.h.server.catalog.insert(as_installed(&authored, *golem));
    }
    let world = w.world;
    {
        let p = w.h.server.players.get_mut(&world).expect("in");
        yalain_world::quals::set_int(&mut p.qualities, yalain_world::examine::LEVEL, 60);
        yalain_world::quals::set_bool(&mut p.qualities, yalain_world::focus::HERO, true);
        yalain_world::kingdoms::set_kingdom(&mut p.qualities, 2);
    }
    let (lin_do, lin_ds, omi_do) = (
        beacon_at(BEACONS[0].0),
        beacon_at(BEACONS[1].0),
        beacon_at(BEACONS[2].0),
    );
    let beside = |w: &mut Walled, i: usize| {
        let o = &t.content.objects[i];
        w.put(spot(o.cell, [o.origin[0] + 1.0, o.origin[1], o.origin[2]]));
    };
    beside(&mut w, lin_do);
    w.use_placed(t, lin_do);
    assert_eq!(state_of(&w.h, LIN_RAID), None, "nothing for the Order");
    assert!(!holds_item(&w.h, BEACONS[0].1));
    yalain_world::kingdoms::set_kingdom(
        &mut w.h.server.players.get_mut(&world).expect("in").qualities,
        4,
    );
    let hero = |w: &mut Walled, on: bool| {
        let p = w.h.server.players.get_mut(&world).expect("in");
        yalain_world::quals::set_bool(&mut p.qualities, yalain_world::focus::HERO, on);
    };
    hero(&mut w, false);
    w.use_placed(t, lin_do);
    assert_eq!(state_of(&w.h, LIN_RAID), None, "nothing for one no hero");
    assert_eq!(state_of(&w.h, PERMISSION), None);
    assert!(!holds_item(&w.h, BEACONS[0].1));
    hero(&mut w, true);
    w.use_placed(t, lin_do);
    assert_eq!(
        state_of(&w.h, LIN_RAID),
        Some((status::UNDERWAY, 1)),
        "the raid given"
    );
    assert_eq!(
        state_of(&w.h, PERMISSION).map(|q| q.0),
        Some(status::UNDERWAY),
        "the hour begun"
    );
    assert!(holds_item(&w.h, BEACONS[0].1), "its crystal");
    beside(&mut w, lin_ds);
    w.use_placed(t, lin_ds);
    assert!(
        !holds_item(&w.h, BEACONS[1].1),
        "nothing more within the hour"
    );
    use_held(&mut w.h, w.b, w.me, BEACONS[0].1);
    assert!(holds_item(&w.h, BEACONS[0].1), "kept away from its mine");
    assert!(living_of(&w.h, BEACONS[0].2).is_empty());

    // At the mine.
    let at_mine = |w: &mut Walled, crystal: u32| {
        let props = as_installed(&authored, crystal).props;
        let (cell, origin) = props.place("Usage_RequiredLocation").expect("its mine");
        let at = spot(cell, origin);
        w.put(at);
        use_held(&mut w.h, w.b, w.me, crystal);
        at
    };
    let defend = |w: &mut Walled, bore: u32, golems: [u32; 4], seconds: f64| -> usize {
        // Every attacker killed as it comes, ten seconds at a time: how many came.
        let mut came = std::collections::BTreeSet::new();
        let end = w.h.now.0 + seconds;
        while w.h.now.0 < end {
            for g in golems {
                for id in living_of(&w.h, g) {
                    came.insert(id);
                    let clock = w.h.clock();
                    yalain_world::death::creature_dies(
                        &mut w.h.server,
                        &mut w.h.net,
                        id,
                        w.me,
                        clock,
                    );
                }
            }
            if living_of(&w.h, bore).is_empty() {
                break;
            }
            w.wait(10.0);
        }
        came.len()
    };
    let (crystal, bore, home) = BORES[0];
    let at = at_mine(&mut w, crystal);
    assert!(!holds_item(&w.h, crystal), "spent");
    assert_eq!(
        state_of(&w.h, LIN_RAID),
        Some((status::UNDERWAY, 2)),
        "the bore placed"
    );
    let [device] = living_of(&w.h, bore)[..] else {
        panic!("one bore");
    };
    let stands =
        w.h.server
            .things
            .get(device)
            .and_then(|x| x.at)
            .expect("stands");
    let off = ground_distance(&stands, &at);
    assert!((off - 4.0).abs() < 0.5, "{off} m ahead");
    w.wait(2.0);
    let attackers: Vec<u64> = LIN_GOLEMS
        .iter()
        .flat_map(|g| living_of(&w.h, *g))
        .collect();
    assert_eq!(attackers.len(), 4, "its mine's golems at it");
    for id in &attackers {
        let a =
            w.h.server
                .things
                .get(*id)
                .and_then(|x| x.at)
                .expect("stands");
        let d = ground_distance(&a, &stands);
        assert!(d < 20.0, "{d} m off");
    }
    let came = defend(&mut w, bore, LIN_GOLEMS, 620.0);
    assert!(came > 8, "each killed replaced: {came}");
    assert!(living_of(&w.h, bore).is_empty(), "held, and gone");
    let [portal] = portals_of(&w.h, home)[..] else {
        panic!("the portal home");
    };
    let there =
        w.h.server
            .things
            .get(portal)
            .and_then(|x| x.at)
            .expect("stands");
    assert!(
        ground_distance(&there, &stands) < 0.5,
        "where the bore stood"
    );
    assert_eq!(
        w.h.server.things.get(portal).and_then(|x| x.facts.kingdom),
        Some(4),
        "for the Dominion alone"
    );
    let kingdom = |w: &mut Walled, k: u32| {
        let p = w.h.server.players.get_mut(&world).expect("in");
        yalain_world::kingdoms::set_kingdom(&mut p.qualities, k);
    };
    kingdom(&mut w, 2);
    use_thing(&mut w.h, w.b, w.me, portal);
    w.h.run(60);
    assert_ne!(w.at().cell, hq_place.cell, "the Order refused");
    assert_eq!(
        state_of(&w.h, LIN_RAID),
        Some((status::UNDERWAY, 2)),
        "the raid not ended"
    );
    kingdom(&mut w, 4);
    use_thing(&mut w.h, w.b, w.me, portal);
    w.h.run(60);
    // Out of portal space once its client has drawn the place.
    w.h.bots[w.b].send(
        true,
        queue::WEENIE,
        &auberean_protocol::ClientMessage::SceneRenderingComplete(auberean_protocol::login::Empty),
    );
    w.h.run(5);
    assert_eq!(w.at().cell, hq_place.cell, "home");
    assert_eq!(
        state_of(&w.h, LIN_RAID).map(|q| q.0),
        Some(status::COMPLETED),
        "the raid ended"
    );

    // An hour on, the raid again; a bore killed first leaves nothing, and another crystal comes.
    beside(&mut w, lin_ds);
    w.use_placed(t, lin_ds);
    assert!(!holds_item(&w.h, BEACONS[1].1), "the hour not over");
    w.wait(3610.0);
    w.use_placed(t, lin_ds);
    assert_eq!(
        state_of(&w.h, LIN_RAID),
        Some((status::UNDERWAY, 1)),
        "given again"
    );
    assert!(holds_item(&w.h, BEACONS[1].1));
    at_mine(&mut w, BEACONS[1].1);
    let [device] = living_of(&w.h, BEACONS[1].2)[..] else {
        panic!("the second bore");
    };
    w.wait(2.0);
    let clock = w.h.clock();
    yalain_world::death::creature_dies(&mut w.h.server, &mut w.h.net, device, 0, clock);
    defend(&mut w, BEACONS[1].2, LIN_GOLEMS, 620.0);
    assert!(
        portals_of(&w.h, home).is_empty(),
        "a fallen bore leaves nothing"
    );
    assert_eq!(
        state_of(&w.h, LIN_RAID),
        Some((status::UNDERWAY, 2)),
        "the raid stays"
    );
    beside(&mut w, lin_ds);
    w.wait(3610.0);
    w.use_placed(t, lin_ds);
    assert!(holds_item(&w.h, BEACONS[1].1), "another crystal");
    assert_eq!(state_of(&w.h, LIN_RAID), Some((status::UNDERWAY, 2)));

    // An hour on, to one who is no hero: no crystal from Linvak's beacon; Omishan's raid, its own
    // crystal, bore and golems.
    w.wait(3610.0);
    hero(&mut w, false);
    beside(&mut w, lin_do);
    w.use_placed(t, lin_do);
    assert!(!holds_item(&w.h, BEACONS[0].1), "Linvak's for heroes alone");
    assert_eq!(state_of(&w.h, LIN_RAID), Some((status::UNDERWAY, 2)));
    beside(&mut w, omi_do);
    w.use_placed(t, omi_do);
    assert_eq!(
        state_of(&w.h, OMI_RAID),
        Some((status::UNDERWAY, 1)),
        "Omishan's raid"
    );
    at_mine(&mut w, BEACONS[2].1);
    assert_eq!(state_of(&w.h, OMI_RAID), Some((status::UNDERWAY, 2)));
    assert_eq!(living_of(&w.h, BEACONS[2].2).len(), 1, "its bore");
    w.wait(2.0);
    let n: usize = OMI_GOLEMS.iter().map(|g| living_of(&w.h, *g).len()).sum();
    assert_eq!(n, 4, "its own mine's golems");
}

/// **The mage's untraining sales walk through**: his place in the Dominion's headquarters is
/// reached on foot from its way in. Coins or a token from a player untraining nothing are handed
/// back with his line for each; from one untraining a skill, 15,000 coins (no other count) finish
/// the untraining and move his quest on, the first giving it and the fifth ending it, with his line
/// each time; a sixth within his five days is handed back; a token then still finishes an
/// untraining, his quest unmoved; once his five days are over the coins give his quest again.
/// Behaviour: server.quests.soul-eater-walk-through
#[test]
fn the_mages_five_untraining_sales_walk_from_the_headquarters_way_in_to_his_break_and_back() {
    use std::collections::HashMap;
    use yalain_world::quests::status;
    const QUEST: u32 = 0x4000_02A4;
    const EATER: u32 = 0x4700_338D;
    const COINS: u32 = 0x4700_0538;
    const TOKEN: u32 = 0x4700_1B42;
    const UNTRAIN: u32 = 0xF62B_9C8E;
    const UNDERWAY: u32 = 0x61B4_57E8;
    const TOKEN_REFUSED: u32 = 0xFD56_B34A;
    const SKILL: u32 = 15;
    let t = &compiled().tables;
    // On foot from the headquarters' way in.
    let way_in = way_to(t, 0xD08B, 0x0BF4_010F);
    let arrival = t.content.objects[way_in].destination.expect("a landing");
    let i = t
        .content
        .objects
        .iter()
        .position(|o| o.template == EATER && o.cell >> 16 == 0x0BF4)
        .expect("the mage in the headquarters");
    let mut w = walled(t, &[0x0BF4]);
    w.put(spot(arrival.cell, arrival.origin));
    assert!(
        w.run_to(t.content.objects[i].origin, 3.0),
        "reached on foot"
    );

    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    h.server.effect_table = effects_read(
        &t.quests.effect_states().collect::<Vec<_>>(),
        &t.effect_rules,
    );
    let mut skills = HashMap::new();
    skills.insert(
        SKILL,
        yalain_world::skills::SkillDef {
            id: SKILL,
            name: (0xA860_7CEC, 0x2500_085B),
            cost: 2,
            flags: 0x1,
            ..yalain_world::skills::SkillDef::default()
        },
    );
    h.server.skill_table = yalain_world::skills::SkillTable {
        skills,
        tables: HashMap::new(),
        ..yalain_world::skills::SkillTable::default()
    };
    let world = player_world(&h);
    let untraining = |h: &mut Harness, on: bool| {
        let p = h.server.players.get_mut(&world).expect("in");
        p.play.skills.retain(|s| s.skill != SKILL);
        p.play.skills.push(yalain_world::state::SkillState {
            skill: SKILL,
            granted: 0,
            mask: 0x3,
            cost: 2,
            children: 0,
            dependents: 0,
            spent: 40,
        });
        p.untraining = on.then_some(yalain_world::skills::Untraining {
            skill: SKILL,
            xp: 40,
            total_at_start: 0,
        });
    };
    let finished = |h: &Harness| {
        let p = &h.server.players[&world];
        p.untraining.is_none() && !p.play.skills.iter().any(|s| s.skill == SKILL)
    };
    untraining(&mut h, false);
    let (said, left) = offered(&mut h, b, me, t, (EATER, COINS), (15_000, 15_000));
    assert_eq!(left, Some(15_000), "handed back to one untraining nothing");
    assert!(
        said.contains(&UNDERWAY),
        "his line for the coins: {said:08X?}"
    );
    let (said, left) = offered(&mut h, b, me, t, (EATER, TOKEN), (1, 1));
    assert_eq!(left, Some(1));
    assert!(
        said.contains(&TOKEN_REFUSED),
        "his line for the token: {said:08X?}"
    );
    assert_eq!(state_of(&h, QUEST), None);

    untraining(&mut h, true);
    let (_, left) = offered(&mut h, b, me, t, (EATER, COINS), (14_999, 14_999));
    assert_eq!(left, Some(14_999), "no other count");
    assert_eq!(state_of(&h, QUEST), None);
    for (n, want) in [
        (1, Some((status::UNDERWAY, 1))),
        (2, Some((status::UNDERWAY, 2))),
        (3, Some((status::UNDERWAY, 3))),
        (4, Some((status::UNDERWAY, 4))),
    ] {
        untraining(&mut h, true);
        let (said, left) = offered(&mut h, b, me, t, (EATER, COINS), (15_000, 15_000));
        assert!(left.is_none(), "sale {n}: kept");
        assert!(said.contains(&UNTRAIN), "sale {n}: his spell");
        assert!(finished(&h), "sale {n}: the untraining finished");
        assert_eq!(state_of(&h, QUEST), want, "sale {n}");
    }
    untraining(&mut h, true);
    let (_, left) = offered(&mut h, b, me, t, (EATER, COINS), (15_000, 15_000));
    assert!(left.is_none() && finished(&h), "the fifth");
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "his five done"
    );
    untraining(&mut h, true);
    let (said, left) = offered(&mut h, b, me, t, (EATER, COINS), (15_000, 15_000));
    assert_eq!(
        left,
        Some(15_000),
        "a sixth within his five days handed back"
    );
    assert!(said.contains(&UNDERWAY));
    assert!(!finished(&h));
    let (said, left) = offered(&mut h, b, me, t, (EATER, TOKEN), (1, 1));
    assert!(left.is_none() && finished(&h), "the token still sells one");
    assert!(said.contains(&UNTRAIN));
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "outside the five"
    );
    for p in h.server.players.values_mut() {
        for q in p.play.quests.iter_mut().filter(|q| q.quest == QUEST) {
            q.updated -= 432_001;
        }
    }
    untraining(&mut h, true);
    let (_, left) = offered(&mut h, b, me, t, (EATER, COINS), (15_000, 15_000));
    assert!(left.is_none(), "his break over");
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 1)),
        "given again"
    );
}

/// **The golden bean walks through**: Elenura and her garden plot stand outdoors in one block, the
/// plot a few meters from her, and a body walks from her to the plot and back. Before her quest the
/// plot's use says only its own line. Her use offers the bean for 1,000 coins and gives nothing;
/// the coins are handed back to one who is no hero, or a hero under level 46, and another sum with
/// her line asking her price; a hero of level 46 paying her 1,000 of a larger stack keeps the rest
/// and is given her quest with the bean, the can and the trowel, with her line for the purchase;
/// the bean used where it is held plants nothing; given to the plot it is kept, the plot
/// says its planting line and the bean's plant stands where the plot stands, the player's; a second
/// bean is handed back with the plot's busy line. The plant refuses a harvest too early; examined,
/// it shows its stage and how it fares, a new plant dry and hungry; the can and the trowel used on
/// it each time it is dry or hungry keep it alive, two times or more each, its stages moving on;
/// ripe (in a few minutes), it shows its ripe line, and its harvest says its line, gives its bean
/// and leaves. The bean handed back to Elenura ends her quest with her line and her coins, and a
/// twentieth of a level's experience.
/// Behaviour: server.quests.osteth-golden-bean-walk-through
#[test]
fn elenuras_bean_planted_in_her_plot_tended_and_harvested_is_handed_back_to_her() {
    use auberean_script::args::Arg;
    use auberean_script::native_object::NativeObject;
    use yalain_content::quests::Trigger;
    use yalain_world::calls::Node;
    use yalain_world::plants;
    use yalain_world::quests::status;
    use yalain_world::usable::maps::ground_distance;
    const QUEST: u32 = 0x8000_0096;
    const ELENURA: u32 = 0x4700_3391;
    const PLOT: u32 = 0x4700_3393;
    const SEED: u32 = 0x4700_1B48;
    const PLANT: u32 = 0x4700_1B4A;
    const BEAN: u32 = 0x4700_1B46;
    const CAN: u32 = 0x4700_1B51;
    const TROWEL: u32 = 0x4700_1B49;
    const COINS: u32 = 0x4700_0538;
    // The plot's lines: its own at a use, planted, busy.
    const DIRT: u32 = 0x367B_0D95;
    const PLANTED: u32 = 0xC84A_F9AA;
    const BUSY: u32 = 0x75BB_918D;
    // The plant's lines, and Elenura's thanks.
    const STAGES: [u32; 3] = [0xA8AE_7D4D, 0x2B64_913D, 0xAFA1_19CC];
    const DRY: u32 = 0xCD52_FC4E;
    const HUNGRY: u32 = 0x28A1_0E7C;
    const MATURE: u32 = 0x979A_5B8B;
    const REFUSED: u32 = 0xA544_694A;
    const HARVESTED: u32 = 0x54AC_9502;
    const THANKS: u32 = 0xEDC5_3877;
    // Elenura's offer of the bean, her price asked, and her line for the purchase.
    const OFFER: u32 = 0xBD65_E99B;
    const PRICE: u32 = 0x686D_E421;
    const BOUGHT: u32 = 0x1D80_3BA2;
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let portal = yalain_testkit::authored::Portal::open();
    let (elenura, plot) = (placed(t, ELENURA), placed(t, PLOT));
    let (her, its) = (&objects[elenura], &objects[plot]);
    assert!(her.cell >> 16 >= 0x1000, "she stands outdoors");
    assert_eq!(its.cell >> 16, her.cell >> 16, "the plot in her block");
    let by = ground_distance(&spot(its.cell, its.origin), &spot(her.cell, her.origin));
    assert!(by < 6.0, "the plot {by} m from her");
    // On foot: from beside her to within the can's reach of the plot, and back.
    let mut w = walled(t, &[her.cell >> 16]);
    w.put(spot(
        her.cell,
        [her.origin[0] + 1.0, her.origin[1], her.origin[2]],
    ));
    assert!(w.run_to(its.origin, 1.5), "the plot reached on foot");
    assert!(w.run_to(her.origin, 3.0), "and back to her");
    // The row: the bean plants in the plot, and nowhere by its use.
    let sp = t
        .plants
        .sown_in(SEED, PLOT)
        .expect("the bean planted in the plot");
    assert_eq!(
        (sp.plant, sp.harvest, sp.water, sp.fertilizer, sp.tended),
        (PLANT, BEAN, CAN, TROWEL, true)
    );
    assert!(t.plants.sown_by(SEED).is_none(), "its use plants nothing");
    assert!(sp.ripe <= 300.0, "ripe in a few minutes: {}", sp.ripe);
    let back = t
        .quests
        .steps
        .iter()
        .find(|s| s.quest == QUEST && s.trigger == Trigger::Give(BEAN, ELENURA))
        .expect("the hand-in");
    assert!(
        (back.xp_share - 0.05).abs() < 1e-6,
        "a twentieth of a level"
    );
    let conditions = sp.texts.and_then(|x| x.conditions).expect("how it fares");

    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    set_level(&mut h, 46);
    for x in [SEED, PLANT, BEAN, CAN, TROWEL, PLOT] {
        h.server.catalog.insert(as_installed(&portal, x));
    }
    h.server.plants.kinds = t.plants.clone();
    let package = portal.template(PLANT).description.package;
    h.server.interactions = portal.interactions(&[CAN, TROWEL], &[(PLANT, package)]);
    let world = player_world(&h);
    let held = |h: &Harness, template: u32| {
        h.server.players[&world]
            .play
            .items
            .iter()
            .filter(|i| i.template == template)
            .map(|i| (i.id, i.quantity.max(1)))
            .next()
    };
    let count = |h: &Harness, template: u32| -> u32 {
        h.server.players[&world]
            .play
            .items
            .iter()
            .filter(|i| i.template == template)
            .map(|i| i.quantity.max(1))
            .sum()
    };
    let text_of = |m: &ServerMessage| match m {
        ServerMessage::PlayerCall(c) => {
            yalain_world::calls::values(&c.args.as_ref().map(|a| a.0.clone()).unwrap_or_default())
                .unwrap_or_default()
                .iter()
                .find_map(|x| match x.root() {
                    Some(Node::TextInfo(t)) => Some(t.string_id),
                    _ => None,
                })
        }
        _ => None,
    };
    // A held item given to a placed object or a thing: the lines the player was told.
    let give = |h: &mut Harness, template: u32, target: u64| -> Vec<u32> {
        use yalain_world::inventory::{move_graph, Move};
        let (item, _) = held(h, template).expect("held");
        let slot = h.server.players[&world]
            .play
            .items
            .iter()
            .find(|x| x.id == item)
            .map_or(0, |x| i32::try_from(x.slot).unwrap_or(0));
        let m = Move {
            move_type: yalain_world::gives::GIVE,
            merge: true,
            unlock: true,
            check_take: true,
            all_taken: true,
            grab: true,
            contain: true,
            auto_merge: true,
            target,
            actual_target: target,
            merge_container: target,
            from: me,
            actual_from: me,
            item,
            split_item: item,
            quantity: 1,
            quantity_left: 1,
            from_slot: slot,
            actual_from_slot: slot,
            ..Move::default()
        };
        let from = h.bots[b].inbox.len();
        h.bots[b].send(
            true,
            queue::WEENIE,
            &server_call(yalain_world::drops::function::MOVE_ITEM, &[move_graph(&m)]),
        );
        h.run(150);
        h.world_messages(b, from)
            .iter()
            .filter_map(text_of)
            .collect()
    };
    // A held item used on a thing (none: used itself): the lines the player was told.
    let use_it = |h: &mut Harness, item: u64, on: u64| -> Vec<u32> {
        let from = h.bots[b].inbox.len();
        let arg = if on == 0 {
            use_of(item, me)
        } else {
            use_on(item, me, on)
        };
        h.bots[b].send(true, queue::WEENIE, &server_call(0x8216_0016, &[arg]));
        let end = h.now.0 + 3.0;
        while h.now.0 < end {
            h.step();
        }
        h.world_messages(b, from)
            .iter()
            .filter_map(text_of)
            .collect()
    };
    // What the player's examination of a thing shows.
    let examined = |h: &mut Harness, thing: u64| -> Vec<u8> {
        let mut bytes = Vec::new();
        for x in [0x4000_0002u32, 0] {
            bytes.extend(x.to_le_bytes());
        }
        bytes.extend(thing.to_le_bytes());
        bytes.extend(0x3FFu32.to_le_bytes());
        let mut g = yalain_world::graph::Builder::new();
        g.native(154, NativeObject::Packed { ty: 154, bytes });
        let from = h.bots[b].inbox.len();
        h.ask(
            b,
            yalain_world::requests::function::EXAMINE,
            &[Arg::Object(g.graph())],
            3,
        );
        h.world_messages(b, from)
            .into_iter()
            .rev()
            .find_map(|m| match m {
                ServerMessage::PlayerCall(c)
                    if c.function.0 == yalain_world::profile::EXAMINATION_PROFILE =>
                {
                    let v = yalain_world::calls::values(&c.args?.0).ok()?;
                    match v[0].root() {
                        Some(Node::Native { bytes, .. }) => Some(bytes.clone()),
                        _ => None,
                    }
                }
                _ => None,
            })
            .expect("a profile")
    };
    let shows = |bytes: &[u8], line: u32| bytes.windows(4).any(|x| x == line.to_le_bytes());

    // Before her quest, the plot says its own line at a use, never its planting line.
    let mut said = Vec::new();
    for _ in 0..12 {
        said.extend(
            use_person(&mut h, b, me, t, plot)
                .into_iter()
                .filter_map(|c| c.1),
        );
    }
    assert!(said.contains(&DIRT), "its own line: {said:08X?}");
    assert!(!said.contains(&PLANTED), "never its planting line");
    // Her offer at a use, which gives nothing.
    let mut said = Vec::new();
    for _ in 0..12 {
        said.extend(
            use_person(&mut h, b, me, t, elenura)
                .into_iter()
                .filter_map(|c| c.1),
        );
    }
    assert!(said.contains(&OFFER), "her offer: {said:08X?}");
    assert_eq!(state_of(&h, QUEST), None, "her use gives nothing");
    // Her price, from heroes of level 46 alone.
    let hero = |h: &mut Harness, on: bool| {
        for p in h.server.players.values_mut() {
            yalain_world::quals::set_bool(&mut p.qualities, yalain_world::focus::HERO, on);
        }
    };
    hero(&mut h, false);
    let (_, left) = offered(&mut h, b, me, t, (ELENURA, COINS), (1_000, 1_000));
    assert_eq!(
        (state_of(&h, QUEST), left),
        (None, Some(1_000)),
        "no hero's coins handed back"
    );
    hero(&mut h, true);
    set_level(&mut h, 45);
    let (_, left) = offered(&mut h, b, me, t, (ELENURA, COINS), (1_000, 1_000));
    assert_eq!(
        (state_of(&h, QUEST), left),
        (None, Some(1_000)),
        "a hero's under level 46 handed back"
    );
    set_level(&mut h, 46);
    let (told, left) = offered(&mut h, b, me, t, (ELENURA, COINS), (999, 999));
    assert_eq!(
        (state_of(&h, QUEST), left),
        (None, Some(999)),
        "another sum handed back"
    );
    assert!(told.contains(&PRICE), "her price: {told:08X?}");
    let (told, left) = offered(&mut h, b, me, t, (ELENURA, COINS), (1_500, 1_000));
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)), "given");
    assert_eq!(left, Some(500), "1,000 of the stack taken");
    assert!(
        told.contains(&BOUGHT),
        "her line for the purchase: {told:08X?}"
    );
    for x in [SEED, CAN, TROWEL] {
        assert_eq!(count(&h, x), 1, "{x:08X} given with it");
    }
    // The bean used where it is held plants nothing.
    let (seed, _) = held(&h, SEED).expect("the bean");
    use_it(&mut h, seed, 0);
    assert!(
        h.server.plants.by_id.is_empty(),
        "nothing planted by its use"
    );
    assert_eq!(count(&h, SEED), 1, "kept");
    // Given to the plot, beside it.
    {
        let p = h.server.players.get_mut(&world).expect("in");
        p.position = spot(
            its.cell,
            [its.origin[0] + 1.0, its.origin[1], its.origin[2]],
        );
    }
    let at_plot = yalain_world::presence::content_id(objects, plot);
    let said = give(&mut h, SEED, at_plot);
    assert!(said.contains(&PLANTED), "the planting line: {said:08X?}");
    assert_eq!(count(&h, SEED), 0, "the bean kept");
    let plant = *h.server.plants.by_id.keys().next().expect("planted");
    let p = &h.server.plants.by_id[&plant];
    assert_eq!(
        (p.owner, p.garden),
        (me, Some(plot)),
        "the player's, in the plot"
    );
    let at = h
        .server
        .things
        .get(plant)
        .and_then(|x| x.at)
        .expect("standing");
    assert_eq!(
        (at.cell, at.origin),
        (its.cell, its.origin),
        "where the plot stands"
    );
    h.server.catalog.insert(as_installed(&portal, SEED));
    yalain_world::inventory::give(&mut h.server, &mut h.net, world, SEED, 1);
    h.run(3);
    let said = give(&mut h, SEED, at_plot);
    assert!(said.contains(&BUSY), "the busy line: {said:08X?}");
    assert_eq!(count(&h, SEED), 1, "handed back");
    assert_eq!(h.server.plants.by_id.len(), 1, "one plant at a time");

    // Too early to harvest; a new plant, examined, is dry and hungry.
    assert!(use_it(&mut h, plant, 0).contains(&REFUSED), "not ripe");
    assert_eq!(count(&h, BEAN), 0);
    let seen = examined(&mut h, plant);
    for line in [STAGES[0], DRY, HUNGRY] {
        assert!(shows(&seen, line), "a new plant shows {line:08X}");
    }
    // Tended as it fares until ripe, its stages moving on.
    let (can, _) = held(&h, CAN).expect("the can");
    let (trowel, _) = held(&h, TROWEL).expect("the trowel");
    let (mut waters, mut feeds, mut stages) = (0, 0, vec![STAGES[0]]);
    let planted = h.server.plants.by_id[&plant].planted;
    while h.now.0 < planted + sp.ripe {
        let Some(p) = h.server.plants.by_id.get(&plant) else {
            panic!("withered at {} s", h.now.0 - planted);
        };
        let fares = plants::fares(&conditions, p.water, p.fertilizer);
        if fares.contains(&Some(DRY)) {
            use_it(&mut h, can, plant);
            waters += 1;
        } else if fares.contains(&Some(HUNGRY)) {
            use_it(&mut h, trowel, plant);
            feeds += 1;
        } else {
            h.step_by(0.5);
        }
        if h.server.plants.by_id.contains_key(&plant) && stages.len() < 3 {
            let next = STAGES[stages.len()];
            if h.now.0 - planted
                > plants::STAGE_SECONDS * f64::from(u8::try_from(stages.len()).unwrap_or(3)) + 1.0
                && shows(&examined(&mut h, plant), next)
            {
                stages.push(next);
            }
        }
    }
    assert!(waters >= 2 && feeds >= 2, "watered {waters}, fed {feeds}");
    assert_eq!(stages, STAGES, "each stage shown");
    h.run(4);
    assert!(h.server.plants.by_id.contains_key(&plant), "alive and ripe");
    assert!(shows(&examined(&mut h, plant), MATURE), "its ripe line");
    let said = use_it(&mut h, plant, 0);
    assert!(said.contains(&HARVESTED), "its harvest line: {said:08X?}");
    assert_eq!(count(&h, BEAN), 1, "its bean");
    assert!(h.server.plants.by_id.is_empty(), "gone");

    // Back to her.
    let coins = count(&h, COINS);
    {
        let p = h.server.players.get_mut(&world).expect("in");
        p.position = spot(
            her.cell,
            [her.origin[0] + 1.0, her.origin[1], her.origin[2]],
        );
    }
    let said = give(
        &mut h,
        BEAN,
        yalain_world::presence::content_id(objects, elenura),
    );
    assert!(said.contains(&THANKS), "her thanks: {said:08X?}");
    assert_eq!(count(&h, BEAN), 0, "taken");
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "done"
    );
    assert_eq!(count(&h, COINS), coins + 5000, "her coins");
}

/// **Uncover the Past's way in is walked from the fortress's plaza through the king's portal**: the
/// king is kept alone on the plaza, his death's row stands its portal at the fortress's platform
/// for several minutes, leading to the dungeon's landing; a body runs from where the dungeon's way
/// out lands to the king and up onto the platform. Killed, the king stands the portal on the
/// platform, named for the dungeon it leads to, a second king's death while it stands makes no
/// other, its use takes the player down into the dungeon, and it is gone once its minutes are over.
/// Behaviour: server.quests.linvak-undercrofts-way-in-walk-through
#[test]
fn the_kings_death_on_the_fortress_stands_the_portal_down_into_the_undercrofts_for_a_while() {
    use yalain_world::usable::maps::ground_distance;
    const KING: u32 = 0x4700_2663;
    const PORTAL: u32 = 0x4700_13E2;
    const FORTRESS: u32 = 0x4651;
    const LANDING: u32 = 0x03E6_0100;
    // The install's name for the dungeon, from the table that names portals by where they lead.
    const UNDERCROFTS_NAME: (u32, u32) = (0x1B6D_27C1, 0x2500_1B44);
    // Where the dungeon's way out lands on the plaza, as a list of the game's destinations gives it.
    const WAY_OUT: (u32, [f32; 3]) = (0x4651_0023, [84.0, 45.0, 330.5]);
    let t = &compiled().tables;
    let authored = yalain_testkit::authored::Portal::open();
    let spawn = t
        .death_spawns
        .get(&yalain_content::DeathSpawn::of_creature(KING))
        .expect("the king's own row")
        .clone();
    let (platform, landing) = (
        spawn.at.expect("on the platform"),
        spawn.to.expect("leads in"),
    );
    assert_eq!(spawn.template, PORTAL);
    assert_eq!(
        spawn.name,
        Some(yalain_content::Words::Ref(
            UNDERCROFTS_NAME.0,
            UNDERCROFTS_NAME.1
        )),
        "its own name"
    );
    assert_eq!(platform.cell >> 16, FORTRESS, "the fortress's platform");
    assert_eq!(landing.cell, LANDING, "the dungeon's landing");
    let lasts = spawn.lasts.expect("for a while");
    assert!((120.0..=600.0).contains(&lasts), "several minutes: {lasts}");
    let [camp] = camps_keeping(t, FORTRESS, KING)[..] else {
        panic!("the king kept once on the fortress");
    };
    assert_eq!(camp.population, 1, "alone");
    let camp = camp.clone();

    // On foot from where the way out lands, to the king and up onto the platform.
    let mut w = walled(t, &[FORTRESS]);
    for (goal, what) in [(camp.origin, "the king"), (platform.origin, "the platform")] {
        w.put(spot(WAY_OUT.0, WAY_OUT.1));
        let way = w
            .way(goal, 3.0)
            .unwrap_or_else(|| panic!("a way to {what}"));
        assert_eq!(w.run_along(&way), way.len(), "{what} reached on foot");
    }

    // The king killed: his portal on the platform, one at a time, leading down; gone in its time.
    w.h.server.death_spawns = t
        .death_spawns
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    for template in [KING, PORTAL] {
        w.h.server.catalog.insert(as_installed(&authored, template));
    }
    {
        let world = w.world;
        let p = w.h.server.players.get_mut(&world).expect("in");
        yalain_world::quals::set_int(&mut p.qualities, yalain_world::examine::LEVEL, 55);
    }
    let king = |w: &mut Walled| {
        w.h.server.spawns.camps.push(camp.clone());
        w.h.server
            .camps
            .push(yalain_world::spawn::CampState::default());
        w.h.run(40);
        let [id] = living_of(&w.h, KING)[..] else {
            panic!("the king stands");
        };
        let clock = w.h.clock();
        yalain_world::death::creature_dies(&mut w.h.server, &mut w.h.net, id, w.me, clock);
        w.h.run(10);
    };
    assert!(portals_of(&w.h, PORTAL).is_empty(), "none before");
    let from = w.h.bots[w.b].inbox.len();
    king(&mut w);
    let [portal] = portals_of(&w.h, PORTAL)[..] else {
        panic!("the king's portal");
    };
    let stands =
        w.h.server
            .things
            .get(portal)
            .and_then(|x| x.at)
            .expect("stands");
    assert!(
        ground_distance(&stands, &spot(platform.cell, platform.origin)) < 0.5,
        "on the platform"
    );
    // Named for the dungeon it leads to, over its stand-in template's name: told and examined so.
    assert_eq!(
        w.h.server.things.get(portal).and_then(|x| x.facts.name),
        Some(UNDERCROFTS_NAME),
        "named for the dungeon"
    );
    let told =
        w.h.world_messages(w.b, from)
            .into_iter()
            .find_map(|m| match m {
                auberean_protocol::ServerMessage::CreateObject(o)
                    if o.id == portal
                        && o.weenie.mask & auberean_protocol::types::WeenieDesc::NAME != 0 =>
                {
                    Some((o.weenie.name.string_id, o.weenie.name.table_id))
                }
                _ => None,
            });
    assert_eq!(told, Some(UNDERCROFTS_NAME), "told by that name");
    king(&mut w);
    assert_eq!(portals_of(&w.h, PORTAL), [portal], "one at a time");
    use_thing(&mut w.h, w.b, w.me, portal);
    w.h.run(60);
    w.h.bots[w.b].send(
        true,
        queue::WEENIE,
        &auberean_protocol::ClientMessage::SceneRenderingComplete(auberean_protocol::login::Empty),
    );
    w.h.run(5);
    assert_eq!(w.at().cell, LANDING, "down into the dungeon");
    w.wait(f64::from(lasts) + 5.0);
    assert!(portals_of(&w.h, PORTAL).is_empty(), "gone in its time");
}

/// **The light temple's island is walked from its way out, and its pillars set in their order by a
/// fellowship let it into the temple by day**: the middle pillar stands on the island with six
/// pillars about it, which an order of the row's own names each once, and the temple's portal
/// before it, standing only by the game's day, whose use's step leads to the temple's landing once
/// the order is made; a body runs from where the temple's way out lands to each of them. By the
/// world's calendar, at night the portal is gone and the middle pillar glows feebly; by day it
/// stands and the middle pillar glows with none lit. A fellowship at the quest's first phase is
/// refused by the portal; a pillar set in its turn whirs, the middle pillar then lit for each set;
/// one out of its turn changes nothing; a fellow's touch of one already set starts the order over
/// for both. Set in full, the middle pillar tells of the portal; a stranger is still refused, and
/// each fellow goes through into the temple, the quest moved on.
/// Behaviour: server.quests.linvak-temple-light-island-walk-through
#[test]
fn the_light_temples_pillars_set_in_their_order_by_a_fellowship_let_it_into_the_temple_by_day() {
    use yalain_world::quests::status;
    use yalain_world::usable::maps::ground_distance;
    const QUEST: u32 = 0x8000_0032;
    const MIDDLE: u32 = 0x4700_3361;
    const PILLAR: u32 = 0x4700_3362;
    const PORTAL: u32 = 0x4700_1A4F;
    const ISLAND: u32 = 0x605A;
    const LANDING: u32 = 0x07E7_0100;
    // The middle pillar's lines: none to five of its depressions lit, all of them, and at night.
    const LIT: [u32; 6] = [
        0xE26A_A57F,
        0xA19C_7596,
        0xA184_7596,
        0xA18C_7596,
        0xA1B4_7596,
        0xA1BC_7596,
    ];
    const ALL: u32 = 0xA1A4_7596;
    const FEEBLE: u32 = 0x49D5_9491;
    // A pillar set, and one not.
    const WHIRS: u32 = 0xEA52_FD5E;
    const NOTHING: u32 = 0xF226_9530;
    // Where the temple's way out lands on the island, as a list of the game's destinations gives it.
    const WAY_OUT: (u32, [f32; 3]) = (0x605A_0015, [45.0, 93.0, 72.6]);
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let middle = placed(t, MIDDLE);
    let at = |i: usize| spot(objects[i].cell, objects[i].origin);
    assert_eq!(objects[middle].cell >> 16, ISLAND, "on the island");
    let row = t
        .items
        .sequences
        .iter()
        .find(|q| q.key == "temple-pillars")
        .expect("the pillars' order");
    assert_eq!(row.quest, None, "a count of its own");
    assert!(row.forgets_after.is_some(), "forgotten in time");
    let order: Vec<usize> = row
        .objects
        .iter()
        .map(|o| o.expect("by placement"))
        .collect();
    assert_eq!(order.len(), 6, "six pillars");
    let mut each = order.clone();
    each.sort_unstable();
    each.dedup();
    assert_eq!(each.len(), 6, "each once");
    // The order authored (none is recorded): across the ring and about it, north first, by each
    // pillar's bearing from the middle one, clockwise from north.
    for (p, bearing) in order.iter().zip([0.0f32, 180.0, 60.0, 240.0, 120.0, 300.0]) {
        assert_eq!(objects[*p].template, PILLAR);
        let d = ground_distance(&at(*p), &at(middle));
        assert!((4.0..=15.0).contains(&d), "{d} m from the middle");
        let (dx, dy) = (
            objects[*p].origin[0] - objects[middle].origin[0],
            objects[*p].origin[1] - objects[middle].origin[1],
        );
        let b = dereth_primitives::num::math::atan2f(dx, dy)
            .to_degrees()
            .rem_euclid(360.0);
        let off = (b - bearing).abs().min(360.0 - (b - bearing).abs());
        assert!(off < 10.0, "the pillar at {bearing} degrees: {b}");
    }
    let portal = placed(t, PORTAL);
    assert!(
        ground_distance(&at(portal), &at(middle)) < 6.0,
        "before the middle pillar"
    );
    assert_eq!(objects[portal].destination, None, "no way in by itself");
    let way_in = t
        .quests
        .steps
        .iter()
        .find(|st| st.quest == QUEST && st.trigger == yalain_content::quests::Trigger::Use(PORTAL))
        .expect("its use's step");
    assert_eq!(way_in.to.map(|p| p.cell), Some(LANDING), "into the temple");

    // On foot from where the way out lands to each.
    let mut w = walled(t, &[ISLAND]);
    for i in order.iter().copied().chain([middle, portal]) {
        w.put(spot(WAY_OUT.0, WAY_OUT.1));
        let o = &objects[i];
        let way = w
            .way(o.origin, 3.0)
            .unwrap_or_else(|| panic!("a way to {:08X}", o.template));
        assert_eq!(
            w.run_along(&way),
            way.len(),
            "{:08X} reached on foot",
            o.template
        );
    }

    // Night and day by the world's calendar.
    let calendar = super::invariants::world_records()
        .region()
        .expect("the region")
        .calendar
        .expect("the world's calendar");
    let by_the_calendar = |h: &mut Harness| {
        h.server.day_parts = calendar
            .day_parts
            .iter()
            .map(|p| (p.begin, p.night != 0))
            .collect();
        h.server.calendar = Some(auberean_world::calendar::GameClock::new(calendar.clone()));
    };
    let until = |h: &mut Harness, dark: bool| {
        while h.server.is_night(h.server.game_now) != dark {
            h.step_by(30.0);
        }
        h.run(4);
    };
    let says = |h: &mut Harness, b: usize, me: u64, i: usize, line: u32| {
        let said = use_person(h, b, me, t, i);
        said.iter().any(|(_, s)| *s == Some(line))
    };
    by_the_calendar(&mut w.h);
    w.h.server.item_rows = t.items.clone();
    let portal_id = yalain_world::presence::content_id(objects, portal);
    until(&mut w.h, true);
    assert!(
        yalain_world::events::hides(&w.h.server, portal),
        "no portal at night"
    );
    assert!(
        says(&mut w.h, w.b, w.me, middle, FEEBLE),
        "glowing feebly at night"
    );
    assert!(!says(&mut w.h, w.b, w.me, middle, LIT[0]));
    until(&mut w.h, false);
    assert!(
        yalain_world::events::content_standing(&w.h.server, portal_id).is_some(),
        "the portal by day"
    );
    assert!(
        says(&mut w.h, w.b, w.me, middle, LIT[0]),
        "glowing, none lit, by day"
    );
    assert!(!says(&mut w.h, w.b, w.me, middle, FEEBLE));

    // A fellowship at the quest's first phase, and a stranger.
    let (mut h, [(ab, me, bearer), (fb, you, fellow), (sb, them, stranger)]) =
        a_bearer_its_fellow_and_a_stranger(t);
    by_the_calendar(&mut h);
    h.server.item_rows = t.items.clone();
    with_uses(&mut h, t, &[PORTAL]);
    until(&mut h, false);
    put_at_phase(&mut h, QUEST, 1);
    let through = |h: &mut Harness, b: usize, me: u64, world: yalain_net::ConnId| {
        use_person(h, b, me, t, portal);
        h.run(60);
        // Out of portal space once its client has drawn the place.
        h.bots[b].send(
            true,
            queue::WEENIE,
            &auberean_protocol::ClientMessage::SceneRenderingComplete(
                auberean_protocol::login::Empty,
            ),
        );
        h.run(5);
        h.server.players[&world].position.cell
    };
    assert_eq!(
        through(&mut h, fb, you, fellow) >> 16,
        ISLAND,
        "not before the pillars are set"
    );
    assert_eq!(state_for(&h, fellow, QUEST), Some((status::UNDERWAY, 1)));
    for (k, p) in order[..2].iter().enumerate() {
        assert!(says(&mut h, ab, me, *p, WHIRS), "pillar {k} set");
        assert!(says(&mut h, ab, me, middle, LIT[k + 1]), "{} lit", k + 1);
    }
    assert!(
        says(&mut h, ab, me, order[4], NOTHING),
        "one out of its turn changes nothing"
    );
    assert!(
        says(&mut h, fb, you, middle, LIT[2]),
        "the fellow's count too"
    );
    assert!(
        says(&mut h, fb, you, order[0], NOTHING),
        "one already set touched again"
    );
    assert!(
        says(&mut h, ab, me, middle, LIT[0]),
        "started over for both"
    );
    for (k, p) in order.iter().enumerate() {
        assert!(says(&mut h, ab, me, *p, WHIRS), "pillar {k} set again");
        let line = LIT.get(k + 1).copied().unwrap_or(ALL);
        assert!(says(&mut h, fb, you, middle, line), "{} set", k + 1);
    }
    assert!(
        says(&mut h, sb, them, middle, LIT[0]),
        "a stranger's own count"
    );
    assert_eq!(
        through(&mut h, sb, them, stranger) >> 16,
        ISLAND,
        "a stranger refused"
    );
    for (b, me, world, who) in [
        (fb, you, fellow, "the fellow"),
        (ab, me, bearer, "the setter"),
    ] {
        assert_eq!(
            through(&mut h, b, me, world),
            LANDING,
            "{who} into the temple"
        );
        assert_eq!(
            state_for(&h, world, QUEST),
            Some((status::UNDERWAY, 2)),
            "{who} inside"
        );
    }
}

/// **The light temple walks from its landing by its levers to the lattice and the well**: its
/// locked doors, each locked to every key, are opened by their levers, an outer one on the way in
/// and an inner one behind, for a while; a solo golem stands at each of the map's 48 places. From
/// the landing at the second phase: nothing lies past door A before lever A beside it is pulled;
/// the way down past door C is shut until lever B, up the stairs, opens door B and lever C behind
/// it opens C, a run from it down through C ending within its time; levers D, E and F each open
/// the next door on the lower level, nothing past it reached before, and the lattice in its room
/// gives the carried lattice and moves the quest on, a second use giving none. The inner levers
/// open the way back, and door C opens from behind to a plain use. Lever G opens door G; with a
/// fellow inside holding G open by its inner lever as the player pulls lever H in its far room, a
/// run from there through G and H ends within both their times, and the carried lattice used on the
/// well is taken for a light one, the quest moved on again. Back through the doors from behind, the
/// exit portal leads out to the island, and the scholar ends the quest.
/// Behaviour: server.quests.linvak-temple-light-inside-walk-through
#[test]
fn the_light_temple_walks_from_its_landing_by_its_levers_to_the_lattice_and_the_well() {
    use yalain_world::quests::status;
    const QUEST: u32 = 0x8000_0032;
    const TEMPLE: u32 = 0x07E7;
    const LEVER: u32 = 0x4700_0CDD;
    const LATTICE: u32 = 0x4700_1A4E;
    const CARRIED: u32 = 0x4700_1A4C;
    const WELL: u32 = 0x4700_1A4D;
    const EXIT: u32 = 0x4700_1A50;
    const LIGHT: [u32; 2] = [0x4700_1A4B, 0x4700_1A49];
    const SCHOLAR: u32 = 0x4700_335D;
    const GOLEMS: [u32; 3] = [0x4700_24D8, 0x4700_24F4, 0x4700_24F8];
    // The temple's landing, and where its way out lands, as a list of the game's destinations gives them.
    const LANDING: (u32, [f32; 3]) = (0x07E7_0100, [100.0, 0.0, 101.3]);
    const WAY_OUT: u32 = 0x605A_0015;
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let rows: Vec<_> = t
        .content
        .levers
        .rows
        .iter()
        .filter(|r| r.levers.iter().any(|&i| objects[i].cell >> 16 == TEMPLE))
        .collect();
    assert_eq!(
        rows.len(),
        17,
        "eight doors' outer and inner levers, and C's"
    );
    for r in &rows {
        assert_eq!((r.levers.len(), r.opens.len()), (1, 1), "{}", r.key);
        assert_eq!(objects[r.levers[0]].template, LEVER, "{}", r.key);
        assert!(
            locked_to_every_key(t, r.opens[0]),
            "{}: locked to every key",
            r.key
        );
        assert!(r.open_for.is_some(), "{}: closes again", r.key);
    }
    let row = |k: &str| {
        let key = format!("lever-{k}");
        rows.iter()
            .find(|r| r.key == key)
            .unwrap_or_else(|| panic!("the row {key}"))
    };
    let lever = |k: &str| row(k).levers[0];
    let door = |d: &str| {
        let k = if d == "c" {
            "c".to_string()
        } else {
            format!("{d}-outer")
        };
        row(&k).opens[0]
    };
    for d in ["a", "b", "d", "e", "i", "f", "g", "h"] {
        assert_eq!(
            row(&format!("{d}-inner")).opens,
            [door(d)],
            "{d}'s inner lever"
        );
    }
    let open_for = |k: &str| row(k).open_for.unwrap_or(0.0);
    let camps: Vec<_> = t
        .spawns
        .camps
        .iter()
        .filter(|c| c.cell >> 16 == TEMPLE)
        .collect();
    assert_eq!(camps.len(), 48, "the map's golems");
    for c in &camps {
        let mut kinds: Vec<u32> = c.templates.iter().map(|(k, _)| *k).collect();
        kinds.sort_unstable();
        assert_eq!(kinds, GOLEMS, "{}", c.id);
        assert_eq!(c.population, 1, "{}: solo", c.id);
    }
    let (lattice, well, exit, scholar) = (
        placed(t, LATTICE),
        placed(t, WELL),
        placed(t, EXIT),
        placed(t, SCHOLAR),
    );
    for i in [lattice, well, exit] {
        assert_eq!(objects[i].cell >> 16, TEMPLE);
    }
    assert_eq!(
        objects[exit].destination.map(|d| d.cell),
        Some(WAY_OUT),
        "the way out to the island"
    );
    let pos = |i: usize| objects[i].origin;
    // A point three meters behind a door, and two before it, by the way its front faces.
    let side = |i: usize, m: f32| {
        let o = &objects[i];
        let [w, _, _, z] = o.rotation;
        let h = 2.0 * dereth_primitives::num::math::atan2f(z, w);
        let (s, c) = (
            dereth_primitives::num::math::sinf(h),
            dereth_primitives::num::math::cosf(h),
        );
        [o.origin[0] - s * m, o.origin[1] + c * m, o.origin[2]]
    };
    let behind = |d: &str| side(door(d), -3.0);
    let before = |d: &str| side(door(d), 2.0);

    let mut w = walled(t, &[TEMPLE, 0x5F5B]);
    with_uses(
        &mut w.h,
        t,
        &[LATTICE, CARRIED, WELL, EXIT, LIGHT[0], LIGHT[1]],
    );
    w.h.server.item_rows = t.items.clone();
    put_at_phase(&mut w.h, QUEST, 2);
    w.put(spot(LANDING.0, LANDING.1));
    let pull = |w: &mut Walled, k: &str| {
        assert!(w.run_to(pos(lever(k)), 2.5), "lever {k} reached");
        w.use_placed(t, lever(k));
    };
    // Lever A, by its door, opens it.
    assert!(w.way(behind("a"), 1.5).is_none(), "nothing past door A");
    pull(&mut w, "a-outer");
    assert!(w.open(t, door("a")), "A opened");
    assert!(w.run_to(behind("a"), 1.5), "through A");
    // Up the stairs to lever B, which opens door B; lever C behind it opens C below.
    assert!(w.way(behind("c"), 1.5).is_none(), "the way down shut");
    assert!(w.way(behind("b"), 1.5).is_none(), "nothing past door B");
    pull(&mut w, "b-outer");
    assert!(w.open(t, door("b")), "B opened");
    pull(&mut w, "c");
    let pulled = w.h.now.0;
    assert!(w.open(t, door("c")), "C opened");
    assert!(w.run_to(behind("c"), 1.5), "down through C");
    assert!(
        w.h.now.0 - pulled < open_for("c"),
        "through C within its {} s",
        open_for("c")
    );
    // The lower level: D, E and F, each opening the way to the next.
    for (d, next) in [("d", "e-outer"), ("e", "f-outer"), ("f", "")] {
        assert!(w.way(behind(d), 1.5).is_none(), "nothing past door {d}");
        pull(&mut w, &format!("{d}-outer"));
        assert!(w.open(t, door(d)), "{d} opened");
        if next.is_empty() {
            assert!(w.run_to(pos(lattice), 2.5), "through F to the lattice");
        } else {
            assert!(w.run_to(pos(lever(next)), 2.5), "through {d} to {next}");
        }
    }
    w.use_placed(t, lattice);
    assert_eq!(
        state_for(&w.h, w.world, QUEST),
        Some((status::UNDERWAY, 3)),
        "the lattice taken"
    );
    assert_eq!(held_count(&w.h, CARRIED), 1, "a lattice carried");
    assert!(
        yalain_world::events::content_standing(
            &w.h.server,
            yalain_world::presence::content_id(objects, lattice)
        )
        .is_some(),
        "the lattice still stands for the next fellow"
    );
    w.use_placed(t, lattice);
    assert_eq!(held_count(&w.h, CARRIED), 1, "one each");
    assert_eq!(state_for(&w.h, w.world, QUEST), Some((status::UNDERWAY, 3)));
    // Back by the inner levers, and up through C from behind.
    for k in ["f-inner", "e-inner", "d-inner"] {
        pull(&mut w, k);
    }
    assert!(w.run_to(before("d"), 1.5), "back through F, E and D");
    assert!(w.run_to(behind("c"), 1.5), "back to C");
    assert!(!w.open(t, door("c")), "C closed again");
    w.use_placed(t, door("c"));
    assert!(w.open(t, door("c")), "from behind anyone opens C");
    assert!(w.run_to(before("c"), 1.0), "up through C");
    // G by its lever; then H, a fellow inside G holding it open.
    assert!(w.way(behind("g"), 1.5).is_none(), "nothing past door G");
    pull(&mut w, "g-outer");
    assert!(w.run_to(pos(lever("g-inner")), 2.5), "through G");
    assert!(w.way(pos(well), 5.0).is_none(), "the well's room shut");
    let (fb, you) = w.h.player_in_world("fellow", "Tamsin");
    let fellow =
        *w.h.server
            .players
            .iter()
            .find(|(_, p)| p.character == you)
            .expect("in the world")
            .0;
    w.h.bots[fb].send(
        true,
        queue::WEENIE,
        &auberean_protocol::ClientMessage::SceneRenderingComplete(auberean_protocol::login::Empty),
    );
    let inner_g = pos(lever("g-inner"));
    if let Some(p) = w.h.server.players.get_mut(&fellow) {
        p.position = spot(
            objects[lever("g-inner")].cell,
            [inner_g[0], inner_g[1] - 1.0, inner_g[2]],
        );
    }
    w.wait(open_for("g-outer") + 1.0);
    assert!(!w.open(t, door("g")), "G closed again");
    assert!(w.run_to(behind("g"), 1.0));
    w.use_placed(t, door("g"));
    assert!(w.run_to(before("g"), 1.0), "out through G from behind");
    pull(&mut w, "h-outer");
    let pulled = w.h.now.0;
    let g_inner = yalain_world::presence::content_id(objects, lever("g-inner"));
    w.h.bots[fb].send(
        true,
        queue::WEENIE,
        &server_call(0x8216_0016, &[use_of(g_inner, you)]),
    );
    w.h.run(40);
    assert!(
        w.open(t, door("g")) && w.open(t, door("h")),
        "G held open, H opened"
    );
    // To within five meters: the well's own body stands about its middle (its lattice is used on
    // it from up to eight).
    let way = w.way(pos(well), 5.0).expect("a way to the well");
    assert_eq!(w.run_along(&way), way.len(), "every step of the run taken");
    let took = w.h.now.0 - pulled;
    assert!(
        took < open_for("h-outer") && took < open_for("g-inner"),
        "the run through G and H in {took:.0} s"
    );
    let carried = w.h.server.players[&w.world]
        .play
        .items
        .iter()
        .find(|x| x.template == CARRIED)
        .expect("the lattice carried")
        .id;
    let well_id = yalain_world::presence::content_id(objects, well);
    w.h.bots[w.b].send(
        true,
        queue::WEENIE,
        &server_call(0x8216_0016, &[use_on(carried, w.me, well_id)]),
    );
    w.h.run(40);
    assert_eq!(
        state_for(&w.h, w.world, QUEST),
        Some((status::UNDERWAY, 4)),
        "the well's light drawn"
    );
    assert_eq!(held_count(&w.h, CARRIED), 0, "the dark lattice gone");
    assert_eq!(
        LIGHT.iter().map(|&l| held_count(&w.h, l)).sum::<u32>(),
        1,
        "a light lattice in its place"
    );
    // Out by the exit portal, the doors opened from behind, and back to the scholar.
    for d in ["h", "g", "a"] {
        assert!(w.run_to(behind(d), 1.0), "back to {d}");
        w.use_placed(t, door(d));
        assert!(w.run_to(before(d), 1.0), "out through {d}");
    }
    assert!(w.run_to(pos(exit), 2.5), "the exit portal reached");
    w.use_placed(t, exit);
    w.h.run(60);
    w.h.bots[w.b].send(
        true,
        queue::WEENIE,
        &auberean_protocol::ClientMessage::SceneRenderingComplete(auberean_protocol::login::Empty),
    );
    w.h.run(5);
    assert_eq!(w.at().cell, WAY_OUT, "out on the island");
    use_person(&mut w.h, w.b, w.me, t, scholar);
    assert_eq!(
        state_for(&w.h, w.world, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "done"
    );
}

/// **Linvak's soulbound Aura Stone walks through**: the Singularity Trove that holds Linvak's weapon
/// scrolls holds the Aura Stone's too, as often as each of the others. Malga gives the quest; the
/// activation crystal given to the golem moves it on; the scroll given to Malga before that is handed
/// back, and given after it is taken, moves the quest on and teaches the emblem's recipe. The emblem
/// made from six ebon pyreal moves it on again, and given to the golem ends it with the Soulbound
/// Aura Stone.
/// Behaviour: server.quests.linvak-soulbound-aura-stone-walk-through
#[test]
fn linvaks_aura_stone_scroll_from_the_trove_becomes_its_emblem_and_the_golems_weapon() {
    use yalain_world::quests::status;
    const QUEST: u32 = 0x4000_012F;
    const MALGA: u32 = 0x4700_3332;
    const GOLEM: u32 = 0x4700_3331;
    const CRYSTAL: u32 = 0x4700_194A;
    const TROVE: u32 = 0x4700_0F5E;
    const SCROLL: u32 = 0x4700_1958;
    const BOW_SCROLL: u32 = 0x4700_1959;
    const RECIPE: u32 = 0x6F00_0330;
    const EBON: u32 = 0x4700_0AFD;
    const EMBLEM: u32 = 0x4700_0BB0;
    const WEAPON: u32 = 0x4700_071C;
    let t = &compiled().tables;
    let portal = yalain_testkit::authored::Portal::open();
    placed(t, TROVE);
    let profile = as_installed(&portal, TROVE)
        .props
        .word("GeneratorProfile")
        .expect("the trove's profile");
    let row = t
        .loot
        .profile(&dat_install_profile(profile))
        .expect("the trove's row");
    let weight = |x: u32| row.items.iter().find(|(i, _)| *i == x).map(|(_, w)| *w);
    assert!(
        weight(BOW_SCROLL).is_some(),
        "the trove holds Linvak's scrolls"
    );
    assert_eq!(
        weight(SCROLL),
        weight(BOW_SCROLL),
        "the Aura Stone's scroll as often as the others"
    );

    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    set_level(&mut h, 45);
    let world = player_world(&h);
    let craft = portal.crafting(&[], &[RECIPE]);
    h.server.effect_table = {
        let mut e = h.server.effect_table.clone();
        let wanted: Vec<u32> = t
            .quests
            .effect_states()
            .chain(craft.outcome_effects())
            .collect();
        e.effects
            .extend(effects_read(&wanted, &t.effect_rules).effects);
        e
    };
    h.server.crafting = craft;
    for item in [CRYSTAL, SCROLL, EBON, EMBLEM, WEAPON] {
        h.server.catalog.insert(as_installed(&portal, item));
    }
    let knows = |h: &Harness| {
        h.server.players[&world]
            .play
            .recipes
            .iter()
            .any(|r| r.recipe == RECIPE)
    };
    use_person(&mut h, b, me, t, placed(t, MALGA));
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)), "given");
    hand_in(&mut h, &portal, SCROLL, MALGA);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 1)),
        "the scroll before the crystal moves nothing"
    );
    assert!(holds_item(&h, SCROLL), "and is handed back");
    hand_in(&mut h, &portal, CRYSTAL, GOLEM);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 2)),
        "the golem"
    );
    hand_in(&mut h, &portal, SCROLL, MALGA);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 3)),
        "the scroll"
    );
    assert!(!holds_item(&h, SCROLL), "the scroll taken");
    assert!(knows(&h), "the emblem's recipe taught");
    yalain_world::inventory::give(&mut h.server, &mut h.net, world, EBON, 6).expect("made");
    h.run(3);
    assert_eq!(
        made_with(&mut h, b, RECIPE, &[EBON]),
        Some(0),
        "the emblem made"
    );
    assert_eq!(held_count(&h, EBON), 0, "the pyreal used up");
    assert!(holds_item(&h, EMBLEM), "the emblem held");
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 4)),
        "its making moves it on"
    );
    hand_in(&mut h, &portal, EMBLEM, GOLEM);
    assert_eq!(state_of(&h, QUEST).map(|q| q.0), Some(status::COMPLETED));
    assert!(!holds_item(&h, EMBLEM), "the emblem taken");
    assert!(holds_item(&h, WEAPON), "the Soulbound Aura Stone");
}

/// **Osteth's soulbound Wasp Nest walks through**: the scowl drudges, whose camps stand outdoors
/// near the golem, leave the Wasp Nest's emblem as often as each of the other emblems they leave.
/// Tamar gives the quest; the emblem given to the golem before the activation crystal is handed
/// back; the crystal moves the quest on, and the emblem given then is taken and ends it with the
/// Soulbound Wasp Nest.
/// Behaviour: server.quests.osteth-soulbound-wasp-nest-walk-through
#[test]
fn osteths_wasp_nest_emblem_from_the_drudges_becomes_the_golems_weapon() {
    use yalain_world::quests::status;
    const QUEST: u32 = 0x4000_0131;
    const TAMAR: u32 = 0x4700_333F;
    const GOLEM: u32 = 0x4700_333D;
    const CRYSTAL: u32 = 0x4700_19AB;
    const DRUDGE: u32 = 0x4700_2346;
    const EMBLEM: u32 = 0x4700_19C9;
    const STAFF_EMBLEM: u32 = 0x4700_19C3;
    const WEAPON: u32 = 0x4700_19DF;
    let t = &compiled().tables;
    let portal = yalain_testkit::authored::Portal::open();
    let profile = as_installed(&portal, DRUDGE)
        .props
        .word("NPC_DeathLootProfile")
        .expect("the drudge's loot");
    let row = t
        .loot
        .profile(&dat_install_profile(profile))
        .expect("the drudge's row");
    let chance = |x: u32| row.extras.iter().find(|(i, _)| *i == x).map(|(_, c)| *c);
    assert!(chance(STAFF_EMBLEM).is_some(), "the drudge leaves emblems");
    assert_eq!(
        chance(EMBLEM),
        chance(STAFF_EMBLEM),
        "the Wasp Nest's as often as the others"
    );
    let golem = t.content.objects[placed(t, GOLEM)].cell >> 16;
    let near = |block: u32| {
        let d = |s: u32| ((block >> s) & 0xFF).abs_diff((golem >> s) & 0xFF);
        d(8) <= 8 && d(0) <= 8
    };
    assert!(
        t.spawns.camps.iter().any(|c| (c.cell & 0xFFFF) < 0x100
            && near(c.cell >> 16)
            && c.templates.iter().any(|(x, _)| *x == DRUDGE)),
        "scowl drudges outdoors near the golem"
    );

    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    set_level(&mut h, 20);
    for item in [CRYSTAL, EMBLEM, WEAPON] {
        h.server.catalog.insert(as_installed(&portal, item));
    }
    use_person(&mut h, b, me, t, placed(t, TAMAR));
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)), "given");
    hand_in(&mut h, &portal, EMBLEM, GOLEM);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 1)),
        "the emblem before the crystal moves nothing"
    );
    assert!(holds_item(&h, EMBLEM), "and is handed back");
    hand_in(&mut h, &portal, CRYSTAL, GOLEM);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 2)),
        "the crystal"
    );
    hand_in(&mut h, &portal, EMBLEM, GOLEM);
    assert_eq!(state_of(&h, QUEST).map(|q| q.0), Some(status::COMPLETED));
    assert!(!holds_item(&h, EMBLEM), "the emblem taken");
    assert!(holds_item(&h, WEAPON), "the Soulbound Wasp Nest");
}

/// The one step of a quest a give of `item` to `to` runs at phase `needs`.
fn give_step(
    t: &Tables,
    quest: u32,
    needs: u32,
    (item, to): (u32, u32),
) -> &yalain_content::quests::Step {
    use yalain_content::quests::Trigger;
    let found: Vec<_> = t
        .quests
        .steps
        .iter()
        .filter(|s| s.quest == quest && s.needs == needs && s.trigger == Trigger::Give(item, to))
        .collect();
    assert_eq!(
        found.len(),
        1,
        "{quest:08X}: one give of {item:08X} to {to:08X} at {needs}"
    );
    found[0]
}

/// **Every Linvak soulbound weapon has its way**: the Singularity Trove that holds Linvak's weapon
/// scrolls holds all sixteen, each as often as the others; each scroll given to Malga at the second
