/// **Every Omishan soulbound weapon has its way**: the rose crystal given at the second phase to the
/// magic, melee or missile emblem golem is taken, moves the quest on and teaches the emblem recipes of
/// every weapon of that class (the class each weapon's own equip effect names), and no other; each
/// emblem given to the weapons golem at the fourth phase is taken and ends the quest with the weapon
/// of its name.
/// Behaviour: server.quests.omishan-soulbound-weapons-every-type
#[test]
fn every_omishan_soulbound_weapon_is_taught_by_its_class_golem_and_has_its_hand_in() {
    use yalain_content::quests::Update;
    const QUEST: u32 = 0x4000_0130;
    const ROSE: u32 = 0x4700_1976;
    const WEAPONS_GOLEM: u32 = 0x4700_333A;
    const GOLEMS: [u32; 3] = [0x4700_3334, 0x4700_3336, 0x4700_3338];
    // Each type: the emblem golem of its class, the effect teaching its emblem's recipe, its
    // emblem, its weapon.
    const TYPES: [(u32, u32, u32, u32); 16] = [
        (0x4700_3336, 0x6F00_1F59, 0x4700_0BBD, 0x4700_1999),
        (0x4700_3338, 0x6F00_1F5A, 0x4700_0BC1, 0x4700_196E),
        (0x4700_3338, 0x6F00_1F5B, 0x4700_0BC2, 0x4700_1970),
        (0x4700_3338, 0x6F00_1F5C, 0x4700_0BC4, 0x4700_1972),
        (0x4700_3336, 0x6F00_1F5D, 0x4700_0BC0, 0x4700_1974),
        (0x4700_3334, 0x6F00_1F5E, 0x4700_0BC7, 0x4700_197A),
        (0x4700_3336, 0x6F00_1F5F, 0x4700_0BBF, 0x4700_198C),
        (0x4700_3338, 0x6F00_1F60, 0x4700_0BC8, 0x4700_198E),
        (0x4700_3334, 0x6F00_1F61, 0x4700_1984, 0x4700_1990),
        (0x4700_3338, 0x6F00_1F66, 0x4700_1985, 0x4700_1992),
        (0x4700_3338, 0x6F00_1F67, 0x4700_0BC5, 0x4700_1995),
        (0x4700_3334, 0x6F00_1F68, 0x4700_0BCA, 0x4700_1997),
        (0x4700_3336, 0x6F00_1F69, 0x4700_0BBE, 0x4700_199B),
        (0x4700_3338, 0x6F00_1F6A, 0x4700_0BC3, 0x4700_199D),
        (0x4700_3338, 0x6F00_1F6B, 0x4700_0BC6, 0x4700_199F),
        (0x4700_3338, 0x6F00_1F6C, 0x4700_0BC9, 0x4700_19A1),
    ];
    let t = &compiled().tables;
    for golem in GOLEMS {
        let s = give_step(t, QUEST, 2, (ROSE, golem));
        assert_eq!(s.update, Update::Advance(3), "{golem:08X} moves it on");
        assert_eq!(s.takes, [ROSE], "{golem:08X} takes the crystal");
        let mut taught = s.effects.clone();
        taught.sort_unstable();
        let mut class: Vec<u32> = TYPES.iter().filter(|x| x.0 == golem).map(|x| x.1).collect();
        class.sort_unstable();
        assert_eq!(taught, class, "{golem:08X} teaches its class");
    }
    for (_, _, emblem, weapon) in TYPES {
        let s = give_step(t, QUEST, 4, (emblem, WEAPONS_GOLEM));
        assert_eq!(s.update, Update::Complete, "{emblem:08X} ends it");
        assert_eq!(s.takes, [emblem], "{emblem:08X} taken");
        assert_eq!(s.gives, [weapon], "{emblem:08X} gives its weapon");
    }
}

/// **Omishan's soulbound Sword walks through**: Shi Sumakhe gives the quest; the turquoise crystal
/// given to the weapons golem moves it on and gives the rose crystal; the rose crystal given to the
/// melee emblem golem is taken, moves it on and teaches the melee emblems' recipes, the Sword's among
/// them and no missile one. The Sword's emblem made from six white pyreal moves it on again, and
/// given to the weapons golem ends it with the Soulbound Sword.
/// Behaviour: server.quests.omishan-soulbound-sword-walk-through
#[test]
fn omishans_melee_golem_teaches_the_sword_whose_emblem_becomes_the_weapons_golems_sword() {
    use yalain_world::quests::status;
    const QUEST: u32 = 0x4000_0130;
    const SHI: u32 = 0x4700_333C;
    const WEAPONS_GOLEM: u32 = 0x4700_333A;
    const MELEE_GOLEM: u32 = 0x4700_3336;
    const TURQUOISE: u32 = 0x4700_1978;
    const ROSE: u32 = 0x4700_1976;
    const RECIPE: u32 = 0x6F00_0347;
    const CLAW_RECIPE: u32 = 0x6F00_0341;
    const BOW_RECIPE: u32 = 0x6F00_033F;
    const PYREAL: u32 = 0x4700_0B10;
    const EMBLEM: u32 = 0x4700_0BBE;
    const WEAPON: u32 = 0x4700_199B;
    let t = &compiled().tables;
    let portal = yalain_testkit::authored::Portal::open();
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    set_level(&mut h, 35);
    let world = player_world(&h);
    let craft = portal.crafting(&[], &[RECIPE, CLAW_RECIPE, BOW_RECIPE]);
    h.server.effect_table = {
        let mut e = h.server.effect_table.clone();
        let wanted: Vec<u32> = t
            .quests
            .effect_states()
            .chain(craft.outcome_effects())
            .collect();
        e.effects
            .extend(effects_read(&wanted, &t.effect_rules).effects);
        e
    };
    h.server.crafting = craft;
    for item in [TURQUOISE, ROSE, PYREAL, EMBLEM, WEAPON] {
        h.server.catalog.insert(as_installed(&portal, item));
    }
    let knows = |h: &Harness, r: u32| {
        h.server.players[&world]
            .play
            .recipes
            .iter()
            .any(|x| x.recipe == r)
    };
    use_person(&mut h, b, me, t, placed(t, SHI));
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)), "given");
    hand_in(&mut h, &portal, TURQUOISE, WEAPONS_GOLEM);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 2)),
        "the turquoise"
    );
    assert!(holds_item(&h, ROSE), "the rose crystal given");
    hand_in(&mut h, &portal, ROSE, MELEE_GOLEM);
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 3)), "the rose");
    assert!(!holds_item(&h, ROSE), "the rose taken");
    assert!(knows(&h, RECIPE), "the Sword's recipe");
    assert!(knows(&h, CLAW_RECIPE), "another melee recipe");
    assert!(!knows(&h, BOW_RECIPE), "no missile recipe");
    yalain_world::inventory::give(&mut h.server, &mut h.net, world, PYREAL, 6).expect("made");
    h.run(3);
    assert_eq!(
        made_with(&mut h, b, RECIPE, &[PYREAL]),
        Some(0),
        "the emblem made"
    );
    assert_eq!(held_count(&h, PYREAL), 0, "the pyreal used up");
    assert!(holds_item(&h, EMBLEM), "the emblem held");
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 4)),
        "its making moves it on"
    );
    hand_in(&mut h, &portal, EMBLEM, WEAPONS_GOLEM);
    assert_eq!(state_of(&h, QUEST).map(|q| q.0), Some(status::COMPLETED));
    assert!(!holds_item(&h, EMBLEM), "the emblem taken");
    assert!(holds_item(&h, WEAPON), "the Soulbound Sword");
}

/// The string ids of the texts a player's client was told in its calls since `from`.
fn texts_told(h: &Harness, b: usize, from: usize) -> Vec<u32> {
    h.calls(b, from)
        .into_iter()
        .filter_map(|(_, v)| {
            v.iter().find_map(|x| match x.root() {
                Some(yalain_world::calls::Node::TextInfo(t)) => Some(t.string_id),
                _ => None,
            })
        })
        .collect()
}

/// **The eidolon's vortexes stand once it falls, and one touched ends its quest with the
/// crystal**: one row guards the ascended archon's dungeon's eight vortexes by the camp that keeps
/// the eidolon alone and back ten minutes after it dies, hiding them while it lives, and a vortex's use at the quest's phase ends it
/// and gives the attuned crystal, for one who fought the eidolon. From the landing the tower's way on leads to, the eidolon's place
/// and every vortex are reached on foot. While the eidolon lives none stands and a use of one finds
/// nothing; killed, all eight stand; one who did not fight it, beside the walker, touches one and
/// nothing moves, until it joins the walker's fellowship; one touched by the walker, who fought it,
/// ends the quest with the vortex's line and gives the crystal; a second touch gives nothing more;
/// the vortexes stand until the eidolon comes back, and go then.
/// Behaviour: server.quests.osteth-chaos-eidolon-vortex-walk-through
#[test]
fn the_eidolons_vortexes_stand_once_it_falls_and_one_touched_ends_its_quest_with_the_crystal() {
    use yalain_content::quests::{Trigger, Update};
    use yalain_world::quests::status;
    const QUEST: u32 = 0x4000_02A5;
    const EIDOLON: u32 = 0x4700_2C94;
    const VORTEX: u32 = 0x4700_2F60;
    const CRYSTAL: u32 = 0x4700_131C;
    const WAY_ON: u32 = 0x4700_131E;
    /// The vortex's line as its use ends the quest.
    const LINE: u32 = 0x2A6B_091E;
    const BLOCK: u32 = 0x04B4;
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let vortexes: Vec<usize> = (0..objects.len())
        .filter(|&i| objects[i].template == VORTEX)
        .collect();
    assert_eq!(vortexes.len(), 8, "2017's eight vortexes");
    assert!(vortexes.iter().all(|&i| objects[i].cell >> 16 == BLOCK));
    let row = t
        .content
        .guards
        .rows
        .iter()
        .find(|r| r.objects.contains(&vortexes[0]))
        .expect("the vortexes' row")
        .clone();
    let mut guarded = row.objects.clone();
    guarded.sort_unstable();
    assert_eq!(guarded, vortexes, "one row guards all eight");
    assert!(row.hidden, "they stand only while it lies dead");
    assert!(
        row.gone_for.is_none(),
        "a touch leaves one standing for the next"
    );
    let camp = t.spawns.camps[row.camp].clone();
    let kinds: Vec<u32> = camp.templates.iter().map(|(x, _)| *x).collect();
    assert_eq!(kinds, [EIDOLON], "the eidolon's camp guards them");
    assert_eq!((camp.population, camp.cell >> 16), (1, BLOCK));
    assert!(
        (camp.regen - 600.0).abs() < 1e-6,
        "dead ten minutes, long enough for a fellowship to touch a vortex"
    );
    let step = t
        .quests
        .steps
        .iter()
        .find(|s| s.quest == QUEST && s.trigger == Trigger::Use(VORTEX))
        .expect("the vortex's step");
    assert_eq!((step.needs, step.update), (1, Update::Complete));
    assert_eq!(step.gives, [CRYSTAL], "the attuned crystal");
    let fought = u32::try_from(row.camp).expect("a camp's row");
    assert_eq!(
        t.content.fought_gates.of_step(step),
        Some([fought].as_slice()),
        "for those who fought the eidolon"
    );
    let landing = objects[placed(t, WAY_ON)]
        .destination
        .expect("the way on's landing");
    assert_eq!(
        landing.cell >> 16,
        BLOCK,
        "the way on leads into the dungeon"
    );

    // On foot from the landing: the eidolon's place and every vortex.
    let mut w = walled(t, &[BLOCK]);
    w.put(spot(landing.cell, landing.origin));
    assert!(
        w.run_far(camp.cell, camp.origin, 4.0),
        "the eidolon's place on foot"
    );
    for &i in &vortexes {
        assert!(
            w.run_far(objects[i].cell, objects[i].origin, 3.0),
            "the vortex at {:?} on foot",
            objects[i].origin
        );
    }

    // Played: the eidolon's camp alone keeps it, and guards the vortexes.
    let portal = yalain_testkit::authored::Portal::open();
    for item in [EIDOLON, CRYSTAL] {
        w.h.server.catalog.insert(as_installed(&portal, item));
    }
    w.h.server.spawns.camps = vec![camp.clone()];
    w.h.server.camps = vec![yalain_world::spawn::CampState::default()];
    let mut mine = row.clone();
    mine.camp = 0;
    w.h.server.content.guards = yalain_content::guards::GuardTable { rows: vec![mine] };
    w.h.server.content.fought_gates = yalain_content::fought::FoughtGates {
        steps: vec![(step.clone(), vec![0])],
        gives: Vec::new(),
    };
    // A second player beside the walker, at the quest's phase too: it does not fight.
    let (b2, other) = w.h.player_in_world("bystander", "Tomas");
    let other_world =
        *w.h.server
            .players
            .iter()
            .find(|(_, p)| p.character == other)
            .map(|(c, _)| c)
            .expect("in the world");
    w.h.bots[b2].send(
        true,
        queue::WEENIE,
        &auberean_protocol::ClientMessage::SceneRenderingComplete(auberean_protocol::login::Empty),
    );
    let here = w.at();
    if let Some(p) = w.h.server.players.get_mut(&other_world) {
        p.position = here;
    }
    put_at_phase(&mut w.h, QUEST, 1);
    w.wait(5.0);
    let state_for = |w: &Walled, who: yalain_net::ConnId| {
        w.h.server.players[&who]
            .play
            .quests
            .iter()
            .find(|q| q.quest == QUEST)
            .map(|q| (q.status, q.phase))
    };
    let crystals_of = |w: &Walled, who: yalain_net::ConnId| {
        w.h.server.players[&who]
            .play
            .items
            .iter()
            .filter(|x| x.template == CRYSTAL)
            .count()
    };
    let walker = (w.b, w.me, w.world);
    let bystander = (b2, other, other_world);
    let standing = |w: &Walled| {
        vortexes
            .iter()
            .filter(|&&i| !yalain_world::guards::hides(&w.h.server, i))
            .count()
    };
    let eidolon = living_of(&w.h, EIDOLON);
    assert_eq!(eidolon.len(), 1, "the eidolon stands");
    assert_eq!(standing(&w), 0, "no vortex while it lives");
    // It fights no one here: the walk is about its death, not its fight.
    if let Some(c) =
        w.h.server
            .things
            .get_mut(eidolon[0])
            .and_then(|x| x.creature.as_mut())
    {
        c.stats.attacks_first = false;
    }
    // The walker stands at the last vortex it ran to.
    let near = vortexes[7];
    w.use_placed(t, near);
    assert_eq!(
        state_for(&w, w.world),
        Some((status::UNDERWAY, 1)),
        "a vortex not standing moves nothing"
    );
    let clock = w.h.clock();
    yalain_world::combat::hurt_creature(
        &mut w.h.server,
        &mut w.h.net,
        eidolon[0],
        w.me,
        100_000_000,
        clock,
    );
    w.wait(2.0);
    assert!(living_of(&w.h, EIDOLON).is_empty(), "the eidolon falls");
    assert_eq!(standing(&w), 8, "every vortex stands");
    let fell = w.h.now.0;
    // The bystander did not fight it: its touch moves nothing, until it is the walker's fellow.
    (w.b, w.me, w.world) = bystander;
    w.use_placed(t, near);
    assert_eq!(
        state_for(&w, other_world),
        Some((status::UNDERWAY, 1)),
        "not for one who did not fight it"
    );
    assert_eq!(crystals_of(&w, other_world), 0);
    w.h.server
        .fellowships
        .list
        .push(yalain_world::fellowship::Fellowship {
            name: "Ascended".into(),
            leader: walker.1,
            flags: 0,
            room: 1,
            fellows: [walker.1, other]
                .iter()
                .map(|&id| yalain_world::fellowship::Fellow {
                    id,
                    joined: 0.0,
                    sent: yalain_world::fellowship::Vitals::default(),
                    next_check: f64::INFINITY,
                })
                .collect(),
            last_claimant: 0,
        });
    w.use_placed(t, near);
    assert_eq!(
        state_for(&w, other_world).map(|q| q.0),
        Some(status::COMPLETED),
        "for a fellow of one who fought it"
    );
    assert_eq!(crystals_of(&w, other_world), 1);
    (w.b, w.me, w.world) = walker;
    let from = w.h.bots[w.b].inbox.len();
    w.use_placed(t, near);
    assert_eq!(
        state_for(&w, w.world).map(|q| q.0),
        Some(status::COMPLETED),
        "a vortex touched by one who fought it ends the quest"
    );
    assert!(texts_told(&w.h, w.b, from).contains(&LINE), "with its line");
    assert_eq!(crystals_of(&w, w.world), 1, "the attuned crystal");
    let other = vortexes[6];
    assert!(w.run_far(objects[other].cell, objects[other].origin, 3.0));
    w.use_placed(t, other);
    assert_eq!(
        crystals_of(&w, w.world),
        1,
        "a second touch gives nothing more"
    );
    assert_eq!(standing(&w), 8, "they stand for the rest");
    w.wait(camp.regen - (w.h.now.0 - fell) - 10.0);
    assert_eq!(standing(&w), 8, "until the eidolon comes back");
    w.wait(20.0);
    assert_eq!(living_of(&w.h, EIDOLON).len(), 1, "the eidolon back");
    assert_eq!(standing(&w), 0, "and the vortexes gone");
}

/// **The cleansed forge turns a chaos crystal into the star, and Arramora's beacon takes it**: the
/// forge stands in the forge room, reached on foot from the hammer and given a crystal from there; a row has it take the attuned
/// crystal and another the crystal of the tree's chain, each for one who has cleansed it, giving the
/// star; the beacon stands in Arramora; the first star's quest pays fifty million once, the lesser
/// one ten million each time, kept from the journal. The attuned crystal given before the forge is cleansed is
/// handed back with its line for an item it does not take; once cleansed it is kept with its line
/// for the star's making, the star given in its place, and the tree's crystal makes a star too. The
/// first star given to the beacon is kept with its first line and ends the great reward's quest, its
/// lesser reward's quest untouched; each star after is kept with its second line and ends the
/// lesser one, again and again, the great one staying done.
/// Behaviour: server.quests.star-of-heroes-walk-through
#[test]
fn a_chaos_crystal_given_to_the_cleansed_forge_becomes_the_star_which_arramoras_beacon_takes() {
    use yalain_content::quests::{Trigger, Update};
    use yalain_world::quests::status;
    const FORGE: u32 = 0x4700_2F63;
    const HAMMER: u32 = 0x4700_2F66;
    const BEACON: u32 = 0x4700_326A;
    const CRYSTAL: u32 = 0x4700_131C;
    const TREE_CRYSTAL: u32 = 0x4700_0612;
    const STAR: u32 = 0x4700_184B;
    const CLEANSE: u32 = 0x4000_0303;
    const GREAT: u32 = 0x4000_0266;
    const LESSER: u32 = 0x4000_0267;
    /// The forge's lines: the star's making, an item handed back.
    const MAKING: u32 = 0x9CD3_AEDF;
    const UNTOUCHED: u32 = 0xF1EB_BC45;
    /// The beacon's lines: the first star, each after.
    const FIRST: u32 = 0x2930_2F94;
    const AGAIN: u32 = 0x2933_0F94;
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let forge = placed(t, FORGE);
    let hammer = placed(t, HAMMER);
    assert_eq!(
        objects[forge].cell >> 16,
        objects[hammer].cell >> 16,
        "the forge in the hammer's room"
    );
    assert_eq!(
        objects[placed(t, BEACON)].cell >> 16,
        0x408E,
        "the beacon in Arramora"
    );
    for item in [CRYSTAL, TREE_CRYSTAL] {
        let row = t
            .quests
            .gives
            .iter()
            .find(|g| g.to == FORGE && g.item == Some(item))
            .unwrap_or_else(|| panic!("{item:08X} given to the forge"));
        assert_eq!(row.gives, [STAR], "{item:08X} makes the star");
        assert_eq!(row.wants, Some(1));
    }
    for (quest, needs_done) in [(GREAT, None), (LESSER, Some(GREAT))] {
        let step = t
            .quests
            .steps
            .iter()
            .find(|s| s.quest == quest && s.trigger == Trigger::Give(STAR, BEACON))
            .unwrap_or_else(|| panic!("the star given to the beacon moves {quest:08X}"));
        assert_eq!((step.needs, step.update), (0, Update::Complete));
        assert_eq!(step.takes, [STAR], "the beacon keeps it");
        assert_eq!(
            needs_done.is_some(),
            !step.requires.is_empty(),
            "{quest:08X}'s requirement"
        );
    }

    let great = t.quests.quest(GREAT).expect("the great reward's quest");
    let lesser = t.quests.quest(LESSER).expect("the lesser reward's quest");
    assert_eq!(
        (great.xp, great.once),
        (50_000_000, true),
        "the great reward, once"
    );
    assert_eq!(
        (lesser.xp, lesser.once),
        (10_000_000, false),
        "the lesser, each time"
    );
    assert!(lesser.hidden, "the lesser kept from the journal");

    // On foot: the forge from the hammer, and a crystal given it from there.
    let portal = yalain_testkit::authored::Portal::open();
    let mut w = walled(t, &[objects[forge].cell >> 16]);
    let h = &objects[hammer];
    w.put(spot(h.cell, [h.origin[0] - 1.5, h.origin[1], h.origin[2]]));
    assert!(w.run_to(objects[forge].origin, 10.0), "the forge on foot");
    w.h.server.catalog.insert(as_installed(&portal, STAR));
    // The forge's body, as the server reads it: how near a give must come.
    let body = portal.body(FORGE).expect("the forge's body");
    w.h.server.catalog.bodies.insert(FORGE, body);
    put_done(&mut w.h, CLEANSE);
    assert!(w.give_to(t, forge, CRYSTAL), "given from there, kept");
    assert!(holds_item(&w.h, STAR), "the star");

    // Played.
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    set_level(&mut h, 60);
    for item in [CRYSTAL, TREE_CRYSTAL, STAR] {
        h.server.catalog.insert(as_installed(&portal, item));
    }
    let (told, left) = offered(&mut h, b, me, t, (FORGE, CRYSTAL), (1, 1));
    assert_eq!(left, Some(1), "handed back before the forge is cleansed");
    assert!(told.contains(&UNTOUCHED), "untouched: {told:08X?}");
    assert!(!holds_item(&h, STAR));
    put_done(&mut h, CLEANSE);
    let (told, left) = offered(&mut h, b, me, t, (FORGE, CRYSTAL), (1, 1));
    assert_eq!(left, None, "the crystal kept");
    assert!(told.contains(&MAKING), "the star's making: {told:08X?}");
    assert!(holds_item(&h, STAR), "the star given");
    let (_, left) = offered(&mut h, b, me, t, (FORGE, TREE_CRYSTAL), (1, 1));
    assert_eq!(left, None, "the tree's crystal kept");
    let stars = |h: &Harness| {
        h.server
            .players
            .values()
            .flat_map(|p| p.play.items.iter())
            .filter(|x| x.template == STAR)
            .count()
    };
    assert_eq!(stars(&h), 2, "a second star");

    // The beacon: the great reward first, then the lesser each time.
    let (told, left) = offered(&mut h, b, me, t, (BEACON, STAR), (1, 1));
    assert_eq!(left, None, "the first star kept");
    assert!(told.contains(&FIRST), "its first line: {told:08X?}");
    assert_eq!(state_of(&h, GREAT).map(|q| q.0), Some(status::COMPLETED));
    assert_eq!(state_of(&h, LESSER), None, "the lesser untouched");
    for n in 0..2 {
        let (told, left) = offered(&mut h, b, me, t, (BEACON, STAR), (1, 1));
        assert_eq!(left, None, "star {} kept", n + 2);
        assert!(told.contains(&AGAIN), "its second line: {told:08X?}");
        assert_eq!(state_of(&h, LESSER).map(|q| q.0), Some(status::COMPLETED));
        assert_eq!(state_of(&h, GREAT).map(|q| q.0), Some(status::COMPLETED));
    }
}

/// **The first star given to Arramora's beacon trains the Arramora recall, whose landing reaches the
/// beacon on foot**: the great reward's two steps and the lesser reward's two train skill 1045; the
/// recall's landing stands in the beacon's block, and from it a walker reaches the foot of the
/// beacon's base and gives it a star from there, completing the great reward's quest and trained.
/// Played: a player who gave its first star before the recall was trained, holding none, gives
/// another and completes the lesser reward's quest, trained; a star after that leaves it as it was.
/// Behaviour: server.quests.arramora-recall-walk-through
#[test]
fn the_first_star_given_to_arramoras_beacon_trains_the_arramora_recall() {
    use yalain_content::quests::Trigger;
    use yalain_world::quests::status;
    const BEACON: u32 = 0x4700_326A;
    const STAR: u32 = 0x4700_184B;
    const GREAT: u32 = 0x4000_0266;
    const LESSER: u32 = 0x4000_0267;
    const RECALL: u32 = yalain_world::skill_use::ARRAMORA_RECALL;
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let trained = |h: &Harness| {
        h.server
            .players
            .values()
            .flat_map(|p| p.play.skills.iter())
            .filter(|s| s.skill == RECALL)
            .count()
    };
    for quest in [GREAT, LESSER] {
        let steps: Vec<_> = t
            .quests
            .steps
            .iter()
            .filter(|s| s.quest == quest && matches!(s.trigger, Trigger::Give(_, BEACON)))
            .collect();
        assert_eq!(steps.len(), 2, "{quest:08X}: a step for each star");
        for s in steps {
            assert_eq!(s.skills, [RECALL], "{quest:08X} {}", s.key);
        }
    }

    // On foot: from the recall's landing to the foot of the beacon's base, three and a half meters
    // below it, and the star given from there.
    let i = placed(t, BEACON);
    let beacon = &objects[i];
    let landing = t.places_by_name[yalain_testkit::ARRAMORA_PLACE];
    assert_eq!(landing.cell >> 16, beacon.cell >> 16, "the beacon's block");
    let mut w = walled(t, &[beacon.cell >> 16]);
    w.put(spot(landing.cell, landing.origin));
    let below = [beacon.origin[0], beacon.origin[1], beacon.origin[2] - 3.0];
    assert!(w.run_to(below, 6.0), "to the beacon on foot");
    let portal = yalain_testkit::authored::Portal::open();
    w.h.server.quest_ids = quest_ids();
    w.h.server.catalog.insert(as_installed(&portal, STAR));
    let body = portal.body(BEACON).expect("the beacon's body");
    w.h.server.catalog.bodies.insert(BEACON, body);
    assert!(w.give_to(t, i, STAR), "given from there, kept");
    assert_eq!(state_of(&w.h, GREAT).map(|q| q.0), Some(status::COMPLETED));
    assert_eq!(trained(&w.h), 1, "trained there");

    // Played.
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    set_level(&mut h, 60);
    h.server.catalog.insert(as_installed(&portal, STAR));
    put_done(&mut h, GREAT);
    assert_eq!(trained(&h), 0, "its first star given, the recall not held");
    let (_, left) = offered(&mut h, b, me, t, (BEACON, STAR), (1, 1));
    assert_eq!(left, None, "a later star kept");
    assert_eq!(state_of(&h, LESSER).map(|q| q.0), Some(status::COMPLETED));
    assert_eq!(trained(&h), 1, "the recall trained");
    let (_, left) = offered(&mut h, b, me, t, (BEACON, STAR), (1, 1));
    assert_eq!(left, None, "another star kept");
    assert_eq!(trained(&h), 1, "held once");
}

/// **The island beyond the tunnels walks down through its heart to the beast and back to the
/// sage**: the portal into the heart stands inside the opening atop the island's mountain, its
/// arrival the quest's second phase; the heart's way out leads back to the opening, and the portal
/// past its bridge into the beast's lair; one camp keeps the beast alone in the lair, holding its
/// five heals from its first moment; five seals lie in the heart's side rooms, each at one of its
/// two places at a time, and five stones stand on the rim of the lair's platform, each seal's
/// row stripping the beast of the heal of its number and barring it; its death stands the second
/// rupture at the lair's middle for five minutes, leading to the scholars' camp; the sage ends the
/// quest with the robe of each race the install holds and a key to his chests, and the reward's
/// mark the robe asks for is set with it. On foot: from the island's landing, where the tunnels'
/// rupture leads, up the mountain to the portal into the heart; from the heart's landing to its way
/// out, to every place a seal lies and down to the portal into the lair; from the lair's landing to
/// the beast, to every stone and to where its portal stands. Played: the sage reminds a player at
/// the first phase; the portal into the heart moves the quest to its second, and out and in again
/// moves nothing more; the sage reminds a player at the second; a seal on the ground gives nothing
/// to one who is no hero, and to a hero the seal of its name for the pack, the one on the ground
/// gone; in the lair the beast made by its camp holds its five heals; each seal pressed against its
/// stone takes the heal of its number off and bars it, the stone glowing; the beast, holding the
/// five bars and no heal, killed stands the rupture, which takes the player to the scholars' camp
/// at the third phase, and goes at its time; the sage ends the quest with his thanks, the robe's
/// line, the robe of the player's race and his chest's key, setting the reward's mark; each other
/// race is given its own robe.
/// Behaviour: server.quests.osteth-cacophos-walk-through
#[test]
fn the_island_beyond_the_tunnels_walks_down_through_its_heart_to_the_beast_and_back_to_the_sage() {
    use yalain_content::quests::{Trigger, Update};
    use yalain_world::quests::status;
    const QUEST: u32 = 0x4000_0337;
    const MARK: u32 = 0x4000_033A;
    const PORTAL: u32 = 0x4700_1154;
    const TUNNELS_RUPTURE: u32 = 0x4700_1307;
    const RUPTURE: u32 = 0x4700_1305;
    const BEAST: u32 = 0x4700_0A20;
    const SAGE: u32 = 0x4700_2F55;
    const KEY: u32 = 0x4700_10D0;
    /// Each race the install holds a robe for, and that robe.
    const ROBES: [(u32, u32); 4] = [
        (1, 0x4700_12F8),
        (2, 0x4700_12F9),
        (4, 0x4700_12FA),
        (16, 0x4700_12FB),
    ];
    /// The sage's lines: at the first phase, at the second, his thanks, the robe.
    const REMIND_1: u32 = 0x147E_1CED;
    const REMIND_2: u32 = 0x147E_2CED;
    const THANKS: u32 = 0x7E1B_EEB1;
    const ROBE_LINE: u32 = 0xBE1B_EEB1;
    const OPENING: u32 = 0x6888_0101;
    const HEART: u32 = 0x07EF;
    const LAIR: u32 = 0x07EE;
    const CAMP: u32 = 0x677B;
    let t = &compiled().tables;
    let beast_row = cacophos_rows(t);
    let objects = &t.content.objects;
    let portal_in = |cell: u32, to: u32| {
        (0..objects.len())
            .find(|&i| {
                objects[i].template == PORTAL
                    && objects[i].cell == cell
                    && objects[i].destination.is_some_and(|d| d.cell >> 16 == to)
            })
            .unwrap_or_else(|| panic!("a portal in {cell:08X} to {to:04X}"))
    };
    let into = portal_in(OPENING, HEART);
    let heart = objects[into].destination.expect("the heart's landing");
    let way_out = (0..objects.len())
        .find(|&i| {
            objects[i].template == PORTAL
                && objects[i].cell >> 16 == HEART
                && objects[i].destination.is_some_and(|d| d.cell == OPENING)
        })
        .expect("the heart's way out to the opening");
    let to_lair = (0..objects.len())
        .find(|&i| {
            objects[i].template == PORTAL
                && objects[i].cell >> 16 == HEART
                && objects[i].destination.is_some_and(|d| d.cell >> 16 == LAIR)
        })
        .expect("the portal into the lair");
    let lair = objects[to_lair].destination.expect("the lair's landing");
    let id = objects[into]
        .object
        .expect("the portal into the heart's own id");
    let step = t
        .quests
        .steps
        .iter()
        .find(|s| s.quest == QUEST && s.trigger == Trigger::ArriveFrom(PORTAL, id))
        .expect("its arrival's step");
    assert_eq!((step.needs, step.update), (1, Update::Advance(2)));
    let beast: Vec<&yalain_content::spawns::Camp> = t
        .spawns
        .camps
        .iter()
        .filter(|c| c.templates.iter().any(|(x, _)| *x == BEAST))
        .collect();
    assert_eq!(beast.len(), 1, "one camp keeps the beast");
    let beast = beast[0].clone();
    assert_eq!(
        (beast.population, beast.templates.len(), beast.cell >> 16),
        (1, 1, LAIR)
    );
    let spawn = t
        .death_spawns
        .get(&yalain_content::DeathSpawn::of_creature(BEAST))
        .expect("the beast's death row")
        .clone();
    assert_eq!(spawn.template, RUPTURE, "the second rupture");
    let at = spawn.at.expect("where it stands");
    assert_eq!(at.cell >> 16, LAIR, "in the lair");
    let back = spawn.to.expect("where it leads");
    assert_eq!(back.cell >> 16, CAMP, "to the scholars' camp");
    assert_eq!(spawn.lasts, Some(300.0), "five minutes");
    for (race, robe) in ROBES {
        assert!(
            t.quests.steps.iter().any(|s| s.quest == QUEST
                && s.needs == 3
                && s.trigger == Trigger::Use(SAGE)
                && s.update == Update::Complete
                && s.races == [race]
                && s.gives == [robe, KEY]),
            "race {race}'s robe and the key"
        );
    }
    assert!(
        t.quests.steps.iter().any(|s| s.quest == MARK
            && s.needs == 0
            && s.trigger == Trigger::Done(QUEST)
            && s.update == Update::Complete),
        "the reward's mark with the quest's end"
    );

    // On foot: the island's landing up the mountain to the portal into the heart.
    let island = objects[placed(t, TUNNELS_RUPTURE)]
        .destination
        .expect("the tunnels' rupture's landing");
    let mut w = walled(t, &[island.cell >> 16, OPENING >> 16]);
    w.put(spot(island.cell, island.origin));
    let o = &objects[into];
    assert!(
        w.run_far(o.cell, o.origin, 2.0),
        "up the mountain to the portal into the heart"
    );
    // The heart: its way out beside the landing, the portal into the lair down past the bridge.
    let mut w = walled(t, &[HEART]);
    w.put(spot(heart.cell, heart.origin));
    let o = &objects[way_out];
    assert!(w.run_far(o.cell, o.origin, 2.0), "the heart's way out");
    // The hall in the heart's middle, and from it every place a seal lies in the upper rooms; then
    // down to the portal into the lair, and from beside it every place in the lower rooms.
    assert!(
        w.run_far(0x07EF_010C, [-0.59, -86.16, 149.89], 2.0),
        "the heart's middle hall"
    );
    let hall = w.at();
    for (key, ..) in &CACOPHOS_SEALS[..3] {
        for i in seal_places(t, key) {
            w.put(hall);
            let o = &objects[i];
            assert!(run_far_again(&mut w, o.cell, o.origin), "{key}: {i}");
        }
    }
    w.put(hall);
    let o = &objects[to_lair];
    assert!(
        w.run_far(o.cell, o.origin, 2.0),
        "down through the heart to the portal into the lair"
    );
    let by_the_lair = w.at();
    for (key, ..) in &CACOPHOS_SEALS[3..] {
        for i in seal_places(t, key) {
            w.put(by_the_lair);
            let o = &objects[i];
            assert!(run_far_again(&mut w, o.cell, o.origin), "{key}: {i}");
        }
    }
    // The lair: the beast's place, every stone and its portal's place.
    let mut w = walled(t, &[LAIR]);
    w.put(spot(lair.cell, lair.origin));
    assert!(w.run_to(beast.origin, 3.0), "the beast's place");
    for (key, _, _, stone, ..) in CACOPHOS_SEALS {
        assert!(
            w.run_to(objects[placed(t, stone)].origin, 3.0),
            "{key}'s stone"
        );
    }
    assert!(w.run_to(at.origin, 2.0), "where its portal stands");

    // Played.
    let mut w = walled(t, &[OPENING >> 16, HEART, LAIR, CAMP, 0x5EB0]);
    w.h.server.quest_ids = quest_ids();
    set_level(&mut w.h, 60);
    with_uses(&mut w.h, t, &[RUPTURE]);
    w.h.server.death_spawns = t
        .death_spawns
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    let portal = yalain_testkit::authored::Portal::open();
    for item in [BEAST, KEY].into_iter().chain(ROBES.map(|r| r.1)) {
        w.h.server.catalog.insert(as_installed(&portal, item));
    }
    seals_served(&mut w, t, beast_row);
    let sage = placed(t, SAGE);
    let said = |w: &mut Walled| -> Vec<u32> {
        use_person(&mut w.h, w.b, w.me, t, sage)
            .into_iter()
            .filter_map(|(_, s)| s)
            .collect()
    };
    put_at_phase(&mut w.h, QUEST, 1);
    assert!(
        said(&mut w).contains(&REMIND_1),
        "the sage's first reminder"
    );
    w.put(spot(objects[into].cell, [7.0, 29.9, 318.3]));
    w.use_placed(t, into);
    assert_eq!(w.at().cell >> 16, HEART, "into the heart");
    assert_eq!(
        state_of(&w.h, QUEST),
        Some((status::UNDERWAY, 2)),
        "passed in"
    );
    through(&mut w, t, way_out);
    assert_eq!(w.at().cell, OPENING, "out to the opening");
    through(&mut w, t, into);
    assert_eq!(
        state_of(&w.h, QUEST),
        Some((status::UNDERWAY, 2)),
        "in again moves nothing more"
    );
    assert!(
        said(&mut w).contains(&REMIND_2),
        "the sage's second reminder"
    );
    // The seals in the heart: nothing for one who is no hero; to a hero, each the seal of its name.
    let (first, ..) = CACOPHOS_SEALS[0];
    let lying = seal_lying(&w, t, first);
    w.put(beside(&objects[lying]));
    w.use_placed(t, lying);
    assert!(!holds_item(&w.h, CACOPHOS_SEALS[0].2), "no hero's seal");
    for p in w.h.server.players.values_mut() {
        yalain_world::quals::set_bool(&mut p.qualities, yalain_world::focus::HERO, true);
    }
    for (key, _, pack, ..) in CACOPHOS_SEALS {
        let lying = seal_lying(&w, t, key);
        w.put(beside(&objects[lying]));
        w.use_placed(t, lying);
        assert!(holds_item(&w.h, pack), "{key}: the seal for the pack");
        assert!(
            !w.h.server
                .shifts
                .standing
                .contains_key(&format!("{key}-seal")),
            "{key}: the one on the ground gone"
        );
    }
    through(&mut w, t, to_lair);
    assert_eq!(w.at().cell >> 16, LAIR, "into the lair");
    for p in w.h.server.players.values_mut() {
        p.scene_drawn = true;
    }
    let id = w.h.server.camps[beast_row].alive[0];
    assert_eq!(
        beast_holds(&w, id),
        CACOPHOS_SEALS.map(|s| s.4),
        "its five heals"
    );
    for (n, (key, _, pack, _, heal, bar, _)) in CACOPHOS_SEALS.into_iter().enumerate() {
        press_seal(&mut w, t, n);
        assert!(!holds_item(&w.h, pack), "{key}: pressed and used up");
        let holds = beast_holds(&w, id);
        assert!(
            !holds.contains(&heal) && holds.contains(&bar),
            "{key}: {holds:08X?}"
        );
    }
    let mut bars = CACOPHOS_SEALS.map(|s| s.5);
    bars.sort_unstable();
    assert_eq!(
        beast_holds(&w, id),
        bars,
        "barred of all five, no heal left"
    );
    let health = w.h.server.things.get(id).map_or(0, |x| x.health);
    let clock = w.h.clock();
    yalain_world::combat::hurt_creature(&mut w.h.server, &mut w.h.net, id, w.me, health, clock);
    world_step(&mut w.h);
    let ruptures = portals_of(&w.h, RUPTURE);
    assert_eq!(ruptures.len(), 1, "the beast's death stands the rupture");
    let stood =
        w.h.server
            .things
            .get(ruptures[0])
            .and_then(|x| x.at)
            .expect("placed");
    assert_eq!(stood.cell, at.cell, "where its row stands it");
    let opened = w.h.now.0;
    use_thing(&mut w.h, w.b, w.me, ruptures[0]);
    w.h.run(100);
    assert_eq!(w.at().cell >> 16, CAMP, "to the scholars' camp");
    assert_eq!(
        state_of(&w.h, QUEST),
        Some((status::UNDERWAY, 3)),
        "the beast fallen"
    );
    w.wait(300.0 - (w.h.now.0 - opened) + 2.0);
    world_step(&mut w.h);
    assert!(portals_of(&w.h, RUPTURE).is_empty(), "gone at its time");

    // The sage's reward: a Lugian's robe; then each other race's own.
    for (race, robe) in [ROBES[1], ROBES[0], ROBES[2], ROBES[3]] {
        let world = w.world;
        w.h.server.players.get_mut(&world).expect("the player").race = race;
        put_at_phase(&mut w.h, QUEST, 3);
        let told = said(&mut w);
        assert_eq!(
            state_of(&w.h, QUEST).map(|q| q.0),
            Some(status::COMPLETED),
            "race {race}: ended"
        );
        assert!(holds_item(&w.h, robe), "race {race}: its robe");
        assert!(holds_item(&w.h, KEY), "race {race}: the chest's key");
        if race == 2 {
            assert!(
                told.contains(&THANKS) && told.contains(&ROBE_LINE),
                "his thanks and the robe's line: {told:08X?}"
            );
            assert_eq!(
                state_of(&w.h, MARK).map(|q| q.0),
                Some(status::COMPLETED),
                "the reward's mark set"
            );
        }
        let world = w.world;
        w.h.server
            .players
            .get_mut(&world)
            .expect("the player")
            .play
            .items
            .retain(|x| x.template != robe && x.template != KEY);
    }
}

/// The Cacophos seals: each one's key, its seal lying on the ground, its seal for the pack, its
/// stone, and the beast's heal, bar and dispel of its number.
const CACOPHOS_SEALS: [(&str, u32, u32, u32, u32, u32, u32); 5] = [
    (
        "renseloi",
        0x4700_130B,
        0x4700_1308,
        0x4700_130A,
        0x6F00_01E5,
        0x6F00_01F2,
        0x6F00_2369,
    ),
    (
        "stelseloi",
        0x4700_130E,
        0x4700_130C,
        0x4700_130D,
        0x6F00_01E6,
        0x6F00_01EA,
        0x6F00_236A,
    ),
    (
        "anuseloi",
        0x4700_1311,
        0x4700_130F,
        0x4700_1310,
        0x6F00_01E7,
        0x6F00_01EB,
        0x6F00_236B,
    ),
    (
        "dethseloi",
        0x4700_1314,
        0x4700_1312,
        0x4700_1313,
        0x6F00_01E8,
        0x6F00_01EC,
        0x6F00_236C,
    ),
    (
        "censeloi",
        0x4700_1317,
        0x4700_1315,
        0x4700_1316,
        0x6F00_01E9,
        0x6F00_01ED,
        0x6F00_236D,
    ),
];

/// The Beast of the Cacophos, and the glow a stone holds once a seal is pressed against it.
const CACOPHOS_BEAST: u32 = 0x4700_0A20;
const CACOPHOS_GLOW: u32 = 0x6F00_1A7C;

/// The world's rows for the Cacophos seals, held to their design: the beast holds each heal from
/// its first moment; each dispel takes its heal off and each bar keeps it off; each seal for the
/// pack, used on its own stone, puts its dispel and bar on the beast's camp's creature, leaves the
/// stone glowing and says the stone's line; each seal on the ground lies at one of two places in
/// the heart's side rooms at a time, its use giving a hero the seal for the pack at the quest's
/// second phase, moving the quest nowhere; each seal for the pack lasts four hours; each stone
/// stands on the lair platform's rim. Returns the beast's camp's row.
fn cacophos_rows(t: &Tables) -> usize {
    use yalain_content::item_rows::On;
    use yalain_content::quests::{Trigger, Update};
    const PRESSED: (u32, u32) = (0xBF64_A8DB, 0x2500_1F0D);
    let camps: Vec<usize> = (0..t.spawns.camps.len())
        .filter(|&i| {
            t.spawns.camps[i]
                .templates
                .iter()
                .any(|(x, _)| *x == CACOPHOS_BEAST)
        })
        .collect();
    assert_eq!(camps.len(), 1, "one camp keeps the beast");
    let row = camps[0];
    let middle = t.spawns.camps[row].origin;
    for (key, lying, pack, stone, heal, bar, dispel) in CACOPHOS_SEALS {
        assert!(
            t.creatures
                .effects
                .iter()
                .any(|e| e.templates == [CACOPHOS_BEAST] && e.effect == heal),
            "{key}: the beast holds its heal"
        );
        assert_eq!(
            t.effect_rules.dispels.get(&dispel),
            Some(&vec![heal]),
            "{key}"
        );
        let ward = t.effect_rules.wards.get(&bar).expect("its bar wards");
        assert_eq!(
            (
                ward.effects.as_slice(),
                ward.classes.is_empty(),
                ward.chance
            ),
            (&[heal][..], true, 1.0),
            "{key}: its bar keeps its heal off"
        );
        let r = t
            .items
            .interactions
            .iter()
            .find(|r| r.item == pack)
            .unwrap_or_else(|| panic!("{key}: its row"));
        assert_eq!(r.on, On::Template(stone), "{key}: on its own stone");
        let on = r.effects_on.as_ref().expect("on the beast");
        assert_eq!((on.camp, on.effects.as_slice()), (row, &[dispel, bar][..]));
        assert_eq!(r.effects_here, [CACOPHOS_GLOW], "{key}: the stone glows");
        assert_eq!(r.tell, Some(PRESSED), "{key}: the stone's line");
        assert_eq!(t.items.lives.get(&pack), Some(&14_400), "{key}: four hours");
        assert!(
            r.gives.is_empty() && r.places.is_empty(),
            "{key}: nothing made"
        );
        let places = seal_places(t, key);
        assert_eq!(places.len(), 2, "{key}: two places");
        for i in places {
            let o = &t.content.objects[i];
            assert_eq!((o.template, o.cell >> 16), (lying, 0x07EF), "{key}");
        }
        let steps: Vec<&yalain_content::quests::Step> = t
            .quests
            .steps
            .iter()
            .filter(|s| s.trigger == Trigger::Use(lying))
            .collect();
        assert_eq!(steps.len(), 1, "{key}: one step");
        let st = steps[0];
        assert_eq!(
            (st.quest, st.needs, st.update, st.gives.as_slice()),
            (0x4000_0337, 2, Update::Nothing, &[pack][..]),
            "{key}"
        );
        assert!(
            t.content.hero_gates.steps.iter().any(|g| g == st),
            "{key}: for heroes alone"
        );
        let o = &t.content.objects[placed(t, stone)];
        let far =
            dereth_primitives::num::math::hypotf(o.origin[0] - middle[0], o.origin[1] - middle[1]);
        assert!(
            o.cell >> 16 == 0x07EE
                && (20.0..26.0).contains(&far)
                && (o.origin[2] - middle[2]).abs() < 1.0,
            "{key}'s stone on the platform's rim: {far} m"
        );
    }
    row
}

/// The places in the world's list where a seal may lie: its shifting row's.
fn seal_places(t: &Tables, key: &str) -> Vec<usize> {
    t.content
        .shifting
        .rows
        .iter()
        .find(|r| r.key == format!("{key}-seal"))
        .map(|r| r.objects.clone())
        .unwrap_or_default()
}

/// The walker runs by `way_far`'s way to within two meters of a place, and, where the server's
/// following of its body holds it short (a report on a slope it does not follow), searches again
/// from where it stands, three times more at most: whether it got there.
fn run_far_again(w: &mut Walled, cell: u32, goal: [f32; 3]) -> bool {
    (0..4).any(|_| w.run_far(cell, goal, 2.0))
}

/// Where a seal lies now.
fn seal_lying(w: &Walled, t: &Tables, key: &str) -> usize {
    let (i, _) = w.h.server.shifts.standing[&format!("{key}-seal")];
    assert!(seal_places(t, key).contains(&i));
    i
}

/// A place a meter beside a placed object.
fn beside(o: &yalain_content::ContentObject) -> yalain_store::StoredPosition {
    spot(o.cell, [o.origin[0] + 1.0, o.origin[1], o.origin[2]])
}

/// The walled world given what the seals need, as a start reads it: the world's camps, of which
/// only the beast's makes anything, its creature and item rows, the seals' interaction tables, the
/// effects the beast and the seals name read with the world's rules, the seals and stones as the
/// install describes them; the walker sturdy.
fn seals_served(w: &mut Walled, t: &Tables, beast_row: usize) {
    let portal = yalain_testkit::authored::Portal::open();
    let mut camps = t.spawns.camps.clone();
    for (i, c) in camps.iter_mut().enumerate() {
        if i != beast_row {
            c.population = 0;
        }
    }
    w.h.server.camps = vec![yalain_world::spawn::CampState::default(); camps.len()];
    w.h.server.spawns.camps = camps;
    w.h.server.creature_rows = t.creatures.clone();
    w.h.server.item_rows = t.items.clone();
    let stones: Vec<(u32, u32)> = CACOPHOS_SEALS
        .iter()
        .map(|s| (s.3, portal.template(s.3).description.package))
        .collect();
    let packs: Vec<u32> = CACOPHOS_SEALS.iter().map(|s| s.2).collect();
    for item in packs.iter().chain([CACOPHOS_BEAST].iter()) {
        w.h.server.catalog.insert(as_installed(&portal, *item));
    }
    w.h.server.interactions = portal.interactions(&packs, &stones);
    let states: Vec<u32> = t
        .creatures
        .effects
        .iter()
        .map(|e| e.effect)
        .chain(t.items.interaction_states())
        .collect();
    let read = effects_read(&states, &t.effect_rules);
    w.h.server.effect_table.effects.extend(read.effects);
    w.h.server.effect_table.chances.extend(read.chances);
    let me = w.me;
    sturdy(&mut w.h, me);
    world_step(&mut w.h);
}

/// The effects the beast holds, by their saved states, in order.
fn beast_holds(w: &Walled, id: u64) -> Vec<u32> {
    let mut v: Vec<u32> =
        yalain_world::effects::records_of(&w.h.server, yalain_world::effects::On::Creature(id))
            .iter()
            .map(|e| e.state)
            .collect();
    v.sort_unstable();
    v
}

/// The walker, two meters from a seal's stone toward the platform's middle, presses that seal (one
/// held, else given) against it: the use's answers, (status, flags).
fn press_seal(w: &mut Walled, t: &Tables, n: usize) {
    let (_, _, pack, stone, ..) = CACOPHOS_SEALS[n];
    let world = w.world;
    if !holds_item(&w.h, pack) {
        yalain_world::inventory::give(&mut w.h.server, &mut w.h.net, world, pack, 1);
        w.h.run(3);
    }
    let held = w.h.server.players[&world]
        .play
        .items
        .iter()
        .find(|x| x.template == pack)
        .expect("held")
        .id;
    let i = placed(t, stone);
    let o = &t.content.objects[i];
    let (dx, dy) = (-29.0 - o.origin[0], -7.8 - o.origin[1]);
    let d = dereth_primitives::num::math::hypotf(dx, dy);
    w.put(spot(
        o.cell,
        [
            o.origin[0] + 2.0 * dx / d,
            o.origin[1] + 2.0 * dy / d,
            o.origin[2],
        ],
    ));
    let target = yalain_world::presence::content_id(&t.content.objects, i);
    let me = w.me;
    w.h.bots[w.b].send(
        true,
        queue::WEENIE,
        &server_call(0x8216_0016, &[use_on(held, me, target)]),
    );
    w.h.run(5);
}

/// The beast's health a while after it is set well below its greatest: how much it rose (or fell,
/// below 0), hurt `harm` a second by the walker meanwhile.
fn beast_rise(w: &mut Walled, id: u64, seconds: u32, harm: i32) -> i32 {
    let from = {
        let x = w.h.server.things.get_mut(id).expect("the beast");
        x.health = x.max_health - 200_000;
        x.health
    };
    for _ in 0..seconds {
        if harm > 0 {
            let clock = w.h.clock();
            let me = w.me;
            yalain_world::combat::hurt_creature(&mut w.h.server, &mut w.h.net, id, me, harm, clock);
        }
        w.wait(1.0);
    }
    w.h.server.things.get(id).map_or(0, |x| x.health) - from
}

/// The lair walled with what the seals need, the walker in it and the beast made by its camp: the
/// walled world and the beast's id.
fn cacophos_lair(t: &Tables) -> (Walled, u64) {
    let row = cacophos_rows(t);
    let mut w = walled(t, &[0x07EE]);
    let lair = t
        .content
        .objects
        .iter()
        .find(|o| {
            o.template == 0x4700_1154 && o.destination.is_some_and(|d| d.cell >> 16 == 0x07EE)
        })
        .and_then(|o| o.destination)
        .expect("the lair's landing");
    w.put(spot(lair.cell, lair.origin));
    seals_served(&mut w, t, row);
    let id = w.h.server.camps[row].alive[0];
    (w, id)
}

/// **An unsealed beast out-heals a modest harm, and a sealed one does not**: the beast made by its
/// camp holds its five heals, a thousand health a second between them; hurt five hundred a second
/// for a minute it ends higher than it began. Its own skill that would cast the heals again is
/// held, but never used: it is neither a help nor an attack. Every seal pressed against its stone,
/// the same harm for a minute takes tens of thousands of health off it.
/// Behaviour: server.quests.osteth-cacophos-seals-weaken-the-beast
#[test]
fn an_unsealed_beast_out_heals_a_modest_harm_and_a_sealed_one_does_not() {
    use yalain_world_db::compile::Install;
    const HEALS_AGAIN: u32 = 1301;
    let t = &compiled().tables;
    let (mut w, id) = cacophos_lair(t);
    assert_eq!(beast_holds(&w, id).len(), 5);
    let install = dat_install();
    let props = yalain_content::Props::of(CACOPHOS_BEAST, &|e| install.entity(e), &|p| {
        install.property_name(p)
    });
    let stats = yalain_content::CreatureStats::from_props(&props).expect("a creature");
    let rating = stats
        .skills
        .iter()
        .find(|(s, _)| *s == HEALS_AGAIN)
        .map(|(_, r)| *r)
        .expect("it holds the skill");
    let skills = yalain_testkit::authored::Portal::open().skills();
    assert!(yalain_world::missiles::attack_skill(&skills, HEALS_AGAIN, rating).is_none());
    assert!(
        yalain_world::missiles::helps_of(&skills, &w.h.server.effect_table, &stats)
            .iter()
            .all(|h| h.skill != HEALS_AGAIN),
        "never cast on itself"
    );
    let unsealed = beast_rise(&mut w, id, 60, 500);
    assert!(unsealed > 20_000, "it out-heals the harm: {unsealed}");
    for n in 0..CACOPHOS_SEALS.len() {
        press_seal(&mut w, t, n);
    }
    assert_eq!(beast_holds(&w, id).len(), 5, "five bars, no heal");
    let sealed = beast_rise(&mut w, id, 60, 500);
    assert!(sealed < -20_000, "the harm tells: {sealed}");
    assert!(
        unsealed - sealed > 55_000,
        "the heals were a thousand a second: {unsealed} against {sealed}"
    );
}

/// **The same seal twice adds nothing**: one seal pressed takes its heal off the beast, four left;
/// a second of the same name against the glowing stone is refused, kept, and leaves the beast as
/// it was; pressed once the glow has gone, it puts its bar on again but takes nothing more, and the
/// beast heals as fast as before it (four heals' worth, hurt a little to keep it fighting).
/// Behaviour: server.quests.osteth-cacophos-same-seal-twice
#[test]
fn the_same_seal_pressed_twice_takes_no_more_off_the_beast() {
    let t = &compiled().tables;
    let (mut w, id) = cacophos_lair(t);
    let (key, _, pack, _, heal, bar, _) = CACOPHOS_SEALS[0];
    let world = w.world;
    for _ in 0..2 {
        yalain_world::inventory::give(&mut w.h.server, &mut w.h.net, world, pack, 1);
    }
    w.h.run(3);
    let held = |w: &Walled| {
        w.h.server.players[&world]
            .play
            .items
            .iter()
            .filter(|x| x.template == pack)
            .count()
    };
    press_seal(&mut w, t, 0);
    assert_eq!(held(&w), 1, "{key}: one used up");
    let once = beast_holds(&w, id);
    assert_eq!(once.len(), 5, "four heals and the bar");
    assert!(!once.contains(&heal) && once.contains(&bar));
    let after_one = beast_rise(&mut w, id, 30, 100);
    assert!(
        (18_000..24_000).contains(&after_one),
        "four heals of 200 a second against 100: {after_one}"
    );
    press_seal(&mut w, t, 0);
    assert_eq!(
        held(&w),
        1,
        "{key}: refused against the glowing stone, kept"
    );
    assert_eq!(beast_holds(&w, id), once, "nothing more done");
    w.wait(1201.0);
    press_seal(&mut w, t, 0);
    assert_eq!(held(&w), 0, "{key}: once the glow has gone, used");
    let twice = beast_holds(&w, id);
    assert!(
        !twice.contains(&heal) && twice.contains(&bar),
        "{twice:08X?}"
    );
    assert_eq!(twice.len(), 5, "still four heals and one bar");
    let after_two = beast_rise(&mut w, id, 30, 100);
    assert!(
        (after_one - after_two).abs() < 3_000,
        "heals as fast: {after_one} and {after_two}"
    );
}

/// **A seal picked up in the heart lasts four hours in the pack**: a hero at the quest's second
/// phase takes the first seal from where it lies in the heart; the seal for the pack ends the four
/// hours of the effect that makes it after it was taken, is held until then, and at the world's
/// step after it is gone from the pack. The seal on the ground, lying again in a side room since its
/// time away, gives another for four hours more.
/// Behaviour: server.quests.osteth-cacophos-seal-lasts-four-hours
#[test]
fn a_seal_picked_up_in_the_heart_lasts_four_hours_in_the_pack() {
    const FOUR_HOURS: f64 = 14_400.0;
    let t = &compiled().tables;
    let row = cacophos_rows(t);
    let mut w = walled(t, &[0x07EF]);
    w.h.server.quest_ids = quest_ids();
    set_level(&mut w.h, 60);
    seals_served(&mut w, t, row);
    put_at_phase(&mut w.h, 0x4000_0337, 2);
    for p in w.h.server.players.values_mut() {
        yalain_world::quals::set_bool(&mut p.qualities, yalain_world::focus::HERO, true);
    }
    let (key, _, pack, ..) = CACOPHOS_SEALS[0];
    let world = w.world;
    let held = |w: &Walled| -> Option<u64> {
        w.h.server.players[&world]
            .play
            .items
            .iter()
            .find(|x| x.template == pack)
            .map(|x| x.id)
    };
    let take = |w: &mut Walled| -> (u64, f64) {
        let lying = seal_lying(w, t, key);
        w.put(beside(&t.content.objects[lying]));
        let taken = w.h.server.game_now;
        w.use_placed(t, lying);
        let id = held(w).unwrap_or_else(|| panic!("{key}: the seal for the pack"));
        let ends = w.h.server.things.get(id).and_then(|x| x.own.ends);
        let ends = ends.expect("an end");
        assert!(
            (ends - taken - FOUR_HOURS).abs() < 5.0,
            "{key}: four hours after it was taken: {}",
            ends - taken
        );
        (id, ends)
    };
    let (seal, ends) = take(&mut w);
    let until =
        |w: &Walled, game: f64| yalain_net::LocalTime(w.h.now.0 + (game - w.h.server.game_now));
    let before = until(&w, ends - 2.0);
    w.h.run_to(before);
    assert_eq!(held(&w), Some(seal), "{key}: held until its end");
    let after = until(&w, ends + 2.0);
    w.h.run_to(after);
    assert_eq!(held(&w), None, "{key}: gone after it");
    assert!(w.h.server.things.get(seal).is_none());
    let (again, _) = take(&mut w);
    assert_ne!(again, seal, "{key}: another seal");
}

/// **Uncover the Past walks through, from the watchtower's Gurog to the dungeon's five debris piles
/// and back**: Lodrog stands once, reached on foot from where Ondekodo's portal lets players out; he
/// gives the lore quest with its satchel from its least level, and his other quest, the bones, only
/// to those under it or to those who have done or failed the lore quest. Five piles, a template
/// each, each stand at one of six places in the dungeon at a time and move on in time; a body runs
/// from the dungeon's landing to every place. Played: under the quest's level he refuses; at it he
/// gives the quest, his line and the satchel, its five pieces given with it; the satchel handed
/// back early is refused; used on each pile standing it completes that pile's piece and shows its
/// lore, and again on one done moves nothing; with all five he asks for the satchel, which he
/// takes with his speech, ending the quest and giving the vial; then he gives the bones. A pile
/// left standing past its time stands elsewhere.
/// Behaviour: server.quests.linvak-uncover-the-past-walk-through
#[test]
fn lodrogs_satchel_searches_the_undercrofts_five_debris_piles_and_goes_back_to_him() {
    use yalain_content::quests::{Need, Trigger, Update};
    use yalain_world::quests::status;
    use yalain_world::usable::maps::ground_distance;
    const QUEST: u32 = 0x4000_02C6;
    const BONES: u32 = 0x4000_0075;
    const PIECES: [u32; 5] = [
        0x4000_02C7,
        0x4000_02C8,
        0x4000_02C9,
        0x4000_02CA,
        0x4000_02CB,
    ];
    const PILES: [u32; 5] = [
        0x4700_1B35,
        0x4700_1B37,
        0x4700_1B39,
        0x4700_1B3B,
        0x4700_1B3D,
    ];
    // The five lore texts, a pile each, and the table they are in.
    const LORE: [u32; 5] = [
        0x0724_4E1A,
        0xF8A6_A29A,
        0x1CF4_9ED3,
        0xA023_4F05,
        0x7ECF_3784,
    ];
    const LORE_TABLE: u32 = 0x2500_2C99;
    const LODROG: u32 = 0x4700_319C;
    const SATCHEL: u32 = 0x4700_1B41;
    const VIAL: u32 = 0x4700_1B3F;
    const DUNGEON: u32 = 0x03E6;
    // His lines: the task, too weak, the satchel loaded down, and his speech as he takes it.
    const TASK: u32 = 0x4B81_BD16;
    const TOO_WEAK: u32 = 0xC4F9_188E;
    const LOADED: u32 = 0xEF02_365D;
    const SPEECH: [u32; 4] = [0x7D7F_04C6, 0x34CC_0A92, 0x34CD_0A92, 0x34CA_0A92];
    // The dungeon's landing, as a list of the game's destinations gives it.
    const LANDING: (u32, [f32; 3]) = (0x03E6_0100, [15.0, 20.0, 101.2]);
    // Where 2017's players came out of Ondekodo's portal, north of his tower, and the way from there
    // to the tower's foot across the land, as a flood of the land from there runs.
    const WAY_IN: (u32, [f32; 3]) = (0x5767_0019, [70.17, 16.9, 183.86]);
    const WAY: [(u32, [f32; 3]); 16] = [
        (0x5766_000F, [32.23, 134.96, 181.80]),
        (0x5666_003D, [155.95, 98.67, 180.40]),
        (0x5666_002C, [115.17, 61.90, 187.30]),
        (0x5666_0022, [81.23, 23.96, 189.80]),
        (0x5665_0018, [44.95, 147.68, 190.50]),
        (0x5665_0006, [9.84, 112.57, 189.70]),
        (0x5565_003C, [145.55, 72.28, 181.70]),
        (0x5565_002A, [109.27, 36.00, 179.50]),
        (0x5564_0020, [72.50, 159.23, 188.00]),
        (0x5564_0027, [97.84, 124.51, 181.40]),
        (0x5564_0035, [133.75, 84.48, 172.30]),
        (0x5664_0003, [9.62, 49.66, 173.80]),
        (0x5664_0009, [36.67, 11.39, 180.00]),
        (0x5663_0017, [45.15, 127.88, 201.40]),
        (0x5663_0025, [81.92, 92.65, 201.50]),
        (0x5663_0032, [138.49, 29.90, 205.70]),
    ];
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let lodrog = placed(t, LODROG);
    assert_eq!(
        objects.iter().filter(|o| o.template == LODROG).count(),
        1,
        "he stands once"
    );

    // His steps: the quest and the satchel from its least level; the loaded satchel given back at
    // its second phase ends it with the vial.
    let def = t.quests.quest(QUEST).expect("the quest's row");
    assert_eq!(def.min_level, 51, "the satchel's own least level");
    let step = |quest: u32, trigger: Trigger| -> Vec<&yalain_content::quests::Step> {
        t.quests
            .steps
            .iter()
            .filter(|s| s.quest == quest && s.trigger == trigger)
            .collect()
    };
    let [giving] = step(QUEST, Trigger::Use(LODROG))[..] else {
        panic!("one giving step");
    };
    assert_eq!(
        giving.levels.map(|l| l.0),
        Some(def.min_level),
        "given from its least level, as his other quest stops under it"
    );
    assert_eq!(
        (giving.needs, giving.update, &giving.gives[..]),
        (0, Update::Bestow, &[SATCHEL][..]),
        "given with the satchel"
    );
    let [back] = step(QUEST, Trigger::Give(SATCHEL, LODROG))[..] else {
        panic!("one return");
    };
    assert_eq!(
        (back.needs, back.update),
        (2, Update::Complete),
        "the satchel given back ends it"
    );
    assert_eq!(
        (&back.takes[..], &back.gives[..]),
        (&[SATCHEL][..], &[VIAL][..]),
        "kept, the vial given"
    );
    // The bones: under the lore quest's level; at it, only after the lore quest done or failed.
    let bones: Vec<_> = step(BONES, Trigger::Use(LODROG))
        .into_iter()
        .filter(|s| s.update == Update::Bestow)
        .collect();
    assert_eq!(bones.len(), 3, "the bones' three givings");
    for b in &bones {
        let (low, high) = b.levels.expect("by level");
        match &b.requires[..] {
            [] => assert!(high < def.min_level, "under it: {low}..{high}"),
            [(q, Need::Done | Need::Failed)] => {
                assert_eq!(*q, QUEST, "after the lore quest");
                assert!(low >= def.min_level, "at its level");
            }
            other => panic!("the bones' giving needs {other:?}"),
        }
    }

    // The piles: each template's own row of six places in the dungeon, one standing at a time and
    // moving on in time; its piece completed by the satchel used on it, with its lore.
    let rows = &t.content.shifting.rows;
    let mut places = Vec::new();
    for (k, pile) in PILES.iter().enumerate() {
        let [row] = rows
            .iter()
            .filter(|r| r.objects.iter().any(|&i| objects[i].template == *pile))
            .collect::<Vec<_>>()[..]
        else {
            panic!("{pile:08X}: one row");
        };
        assert_eq!(row.objects.len(), 6, "{pile:08X}: six places");
        for &i in &row.objects {
            assert_eq!(objects[i].template, *pile, "{pile:08X}: its own row");
            assert_eq!(objects[i].cell >> 16, DUNGEON, "{pile:08X}: in the dungeon");
        }
        assert!(
            row.moves_after
                .is_some_and(|s| (600.0..=21_600.0).contains(&s)),
            "{pile:08X}: moves on in time"
        );
        assert!(row.gone_for.is_none(), "{pile:08X}: never gone");
        places.extend(row.objects.iter().copied());
        let [search] = step(PIECES[k], Trigger::UseOn(SATCHEL, *pile))[..] else {
            panic!("{pile:08X}: one search");
        };
        assert_eq!(
            (search.needs, search.update, search.text),
            (1, Update::Complete, Some((LORE[k], LORE_TABLE))),
            "{pile:08X}: its piece and its lore"
        );
    }
    let mut each = places.clone();
    each.sort_unstable();
    each.dedup();
    assert_eq!(each.len(), 30, "thirty places");
    for (n, &a) in places.iter().enumerate() {
        for &b in &places[n + 1..] {
            let d = ground_distance(
                &spot(objects[a].cell, objects[a].origin),
                &spot(objects[b].cell, objects[b].origin),
            );
            assert!(
                d >= 3.0 || (objects[a].origin[2] - objects[b].origin[2]).abs() > 3.0,
                "{a} and {b} apart: {d}"
            );
        }
    }

    // On foot: every place from the dungeon's landing, one after another, nearest first (a change
    // of level counted ten times over, as the way between levels goes the long way round).
    let mut w = walled(t, &[DUNGEON]);
    w.put(spot(LANDING.0, LANDING.1));
    let mut left = places.clone();
    while !left.is_empty() {
        let here = w.at();
        let (n, _) = left
            .iter()
            .enumerate()
            .map(|(n, &i)| {
                let o = &objects[i];
                let rise = (o.origin[2] - here.origin[2]).abs();
                (
                    n,
                    ground_distance(&here, &spot(o.cell, o.origin)) + 10.0 * rise,
                )
            })
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .expect("one left");
        let i = left.swap_remove(n);
        let (pile, goal) = (objects[i].template, objects[i].origin);
        // A body held up at a pillar's corner (where the way's search stepped round it closer than a
        // run's body goes) takes a new way from where it stands, else goes from the landing again.
        let tries = |w: &mut Walled| {
            (0..3).any(|_| {
                w.way(goal, 4.0)
                    .is_some_and(|way| w.run_along(&way) == way.len())
            })
        };
        let reached = tries(&mut w) || {
            w.put(spot(LANDING.0, LANDING.1));
            tries(&mut w)
        };
        assert!(
            reached,
            "{pile:08X} at {goal:?} reached on foot from {:?}",
            here.origin
        );
    }
    // His tower from the portal's landing.
    let mut w = walled(
        t,
        &[
            0x5767, 0x5766, 0x5666, 0x5665, 0x5565, 0x5564, 0x5664, 0x5663,
        ],
    );
    w.put(spot(WAY_IN.0, WAY_IN.1));
    for (cell, at) in WAY {
        assert!(
            w.run_to_at(spot(cell, at), 3.0),
            "{cell:08X} {at:?} on the way"
        );
    }
    assert!(
        w.run_to_at(spot(objects[lodrog].cell, objects[lodrog].origin), 3.0),
        "up to him"
    );

    // Played.
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    let world = player_world(&h);
    let said =
        |calls: &[(u32, Option<u32>)]| -> Vec<u32> { calls.iter().filter_map(|c| c.1).collect() };
    // His bones done a while ago, so he has only the lore quest to give.
    put_done(&mut h, BONES);
    set_level(&mut h, 50);
    let to = said(&use_person(&mut h, b, me, t, lodrog));
    assert!(to.contains(&TOO_WEAK), "too weak: {to:08X?}");
    assert_eq!(state_of(&h, QUEST), None);
    set_level(&mut h, 55);
    let to = said(&use_person(&mut h, b, me, t, lodrog));
    assert!(to.contains(&TASK), "his task: {to:08X?}");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)), "given");
    assert!(holds_item(&h, SATCHEL), "the satchel");
    for piece in PIECES {
        assert_eq!(
            state_of(&h, piece),
            Some((status::UNDERWAY, 1)),
            "{piece:08X} given with it"
        );
    }
    let (_, left) = offered(&mut h, b, me, t, (LODROG, SATCHEL), (1, 1));
    assert_eq!(left, Some(1), "handed back early, refused");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)));

    // Each pile standing, searched.
    world_step(&mut h);
    let satchel = h.server.players[&world]
        .play
        .items
        .iter()
        .find(|i| i.template == SATCHEL)
        .expect("held")
        .id;
    let standing = |h: &Harness, pile: u32| -> Vec<usize> {
        places
            .iter()
            .copied()
            .filter(|&i| {
                objects[i].template == pile && !yalain_world::shifting::hides(&h.server, i)
            })
            .collect()
    };
    let search = |h: &mut Harness, i: usize| -> Vec<u32> {
        let o = &objects[i];
        for p in h.server.players.values_mut() {
            p.position.cell = o.cell;
            p.position.origin = [o.origin[0] + 1.0, o.origin[1], o.origin[2]];
        }
        let from = h.bots[b].inbox.len();
        let id = yalain_world::presence::content_id(objects, i);
        h.bots[b].send(
            true,
            queue::WEENIE,
            &server_call(0x8216_0016, &[use_on(satchel, me, id)]),
        );
        let until = h.now.0 + 4.0;
        while h.now.0 < until {
            h.step();
        }
        h.calls(b, from)
            .into_iter()
            .filter_map(|(_, v)| {
                v.iter().find_map(|x| match x.root() {
                    Some(yalain_world::calls::Node::TextInfo(t)) => Some(t.string_id),
                    _ => None,
                })
            })
            .collect()
    };
    let mut first = Vec::new();
    for (k, pile) in PILES.iter().enumerate() {
        let [i] = standing(&h, *pile)[..] else {
            panic!("{pile:08X}: one standing");
        };
        first.push(i);
        let told = search(&mut h, i);
        assert!(told.contains(&LORE[k]), "{pile:08X}: its lore: {told:08X?}");
        assert_eq!(
            state_of(&h, PIECES[k]).map(|q| q.0),
            Some(status::COMPLETED),
            "{pile:08X}: its piece"
        );
        if k == 0 {
            search(&mut h, i);
            assert_eq!(
                state_of(&h, QUEST),
                Some((status::UNDERWAY, 1)),
                "searched again, nothing more"
            );
        }
        assert_eq!(standing(&h, *pile), [i], "{pile:08X}: searched, it stays");
    }
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 2)),
        "all five found"
    );
    let to = said(&use_person(&mut h, b, me, t, lodrog));
    assert!(to.contains(&LOADED), "the satchel loaded down: {to:08X?}");
    let (to, left) = offered(&mut h, b, me, t, (LODROG, SATCHEL), (1, 1));
    assert!(left.is_none(), "the satchel kept");
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "ended"
    );
    assert!(holds_item(&h, VIAL), "the vial");
    let heard: Vec<u32> = to.iter().copied().filter(|s| SPEECH.contains(s)).collect();
    assert_eq!(heard, SPEECH, "his speech, in its order");
    // The lore quest waiting to be given again: the bones.
    for p in h.server.players.values_mut() {
        p.play.quests.retain(|q| q.quest != BONES);
    }
    use_person(&mut h, b, me, t, lodrog);
    assert_eq!(
        state_of(&h, BONES),
        Some((status::UNDERWAY, 1)),
        "the bones while the lore quest waits"
    );

    // Left standing past its time, a pile stands elsewhere.
    let moves = rows
        .iter()
        .find(|r| r.objects.contains(&first[0]))
        .and_then(|r| r.moves_after)
        .expect("in time");
    h.advance(moves + 10.0);
    world_step(&mut h);
    let [now] = standing(&h, PILES[0])[..] else {
        panic!("one standing");
    };
    assert_ne!(now, first[0], "moved on");
}

/// **The mine boon permission walks through, from the Dominion's overseer to an enemy kingdom's
/// mote and back**: the overseer stands in the Dominion's headquarters, reached on foot from its
/// way in, and gives her task to the Dominion's players alone from its least level; the Order's and
/// the Shadow's granules and motes given back complete it, her own kingdom's are refused. The
/// mines' guardians leave their kingdom's granules and motes, now and then: the Order's golems
/// about the Order's mine, the Dominion's clusters and rifts about the Dominion's. Played: a player
/// of the Order is given nothing; one of the Dominion under its level is refused; at it given the
/// task with her line; her own kingdom's granule handed back with her line for it; the Order's
/// granule kept, her line for the Order's and her permission, the task done and never given again;
/// another given the task again ends it with the Shadow's mote and her line for the Shadow's.
/// Behaviour: server.quests.mine-boon-permission-walk-through
#[test]
fn the_dominions_overseer_gives_her_boon_task_and_takes_an_enemy_kingdoms_mote_for_it() {
    use yalain_content::quests::{Trigger, Update};
    use yalain_world::quests::status;
    use yalain_world::usable::maps::ground_distance;
    const QUEST: u32 = 0x4000_0351;
    const SUTHANNA: u32 = 0x4700_2FBE;
    const HQ: u32 = 0x0BF4;
    // Each kingdom's granule and mote: the Dominion's, the Order's, the Shadow's.
    const DOMINION: [u32; 2] = [0x4700_147A, 0x4700_147B];
    const ORDER: [u32; 2] = [0x4700_147C, 0x4700_147D];
    const SHADOW: [u32; 2] = [0x4700_147E, 0x4700_147F];
    // Her lines: the task, too weak, a material of the Dominion's, the Order's, the Shadow's, and
    // her permission.
    const TASK: u32 = 0x4E0C_13F6;
    const TOO_WEAK: u32 = 0xC4F9_188E;
    const OF_DOMINION: u32 = 0x1AA0_38A2;
    const OF_ORDER: u32 = 0x3D8F_1398;
    const OF_SHADOW: u32 = 0x2980_2FAC;
    const PERMITTED: u32 = 0x2FB7_FE28;
    // The guardians: the Order's golems and the Dominion's clusters and rifts, of the hoards the
    // install made for the mines.
    const GOLEMS: [u32; 8] = [
        0x4700_24C4,
        0x4700_24D4,
        0x4700_24DA,
        0x4700_24EA,
        0x4700_24EC,
        0x4700_24F1,
        0x4700_24FF,
        0x4700_2501,
    ];
    const CLUSTERS: [u32; 7] = [
        0x4700_2A08,
        0x4700_2A0C,
        0x4700_2A0D,
        0x4700_2A0F,
        0x4700_2A11,
        0x4700_2A13,
        0x4700_2A14,
    ];
    // Where the Omishan mines' crystals call their bores: the Order's and the Dominion's.
    const ORDER_MINE: (u32, [f32; 3]) = (0xD896_0025, [83.0, 88.0, 113.5]);
    const DOMINION_MINE: (u32, [f32; 3]) = (0xED9C_0014, [59.8, 79.3, 73.3]);
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let at = placed(t, SUTHANNA);
    assert_eq!(objects[at].cell >> 16, HQ, "in the headquarters");
    let def = t.quests.quest(QUEST).expect("its row");
    assert_eq!(def.min_level, 25, "its setup's least level");
    let steps: Vec<&yalain_content::quests::Step> =
        t.quests.steps.iter().filter(|s| s.quest == QUEST).collect();
    let [giving] = steps
        .iter()
        .filter(|s| s.trigger == Trigger::Use(SUTHANNA))
        .collect::<Vec<_>>()[..]
    else {
        panic!("one giving step");
    };
    assert_eq!((giving.needs, giving.update), (0, Update::Bestow));
    assert!(
        t.kingdoms.step_for(giving, 4) && !t.kingdoms.step_for(giving, 2),
        "for the Dominion alone"
    );
    for item in ORDER.iter().chain(&SHADOW) {
        let [give] = steps
            .iter()
            .filter(|s| s.trigger == Trigger::Give(*item, SUTHANNA))
            .collect::<Vec<_>>()[..]
        else {
            panic!("{item:08X}: one give");
        };
        assert_eq!(
            (give.needs, give.update, &give.takes[..]),
            (1, Update::Complete, &[*item][..]),
            "{item:08X} taken for it"
        );
    }
    for item in DOMINION {
        assert!(
            !steps
                .iter()
                .any(|s| s.trigger == Trigger::Give(item, SUTHANNA)),
            "{item:08X}: her own kingdom's takes nothing"
        );
    }
    // The guardians' granules and motes, each kingdom's on its own, now and then.
    for (kinds, items) in [(&GOLEMS[..], ORDER), (&CLUSTERS[..], DOMINION)] {
        for kind in kinds {
            for item in items {
                assert!(
                    t.loot.treasures.iter().any(|d| d.item == item
                        && d.from == yalain_content::loot::Dropper::Template(*kind)
                        && d.chance > 0.0
                        && d.chance <= 0.1),
                    "{kind:08X} leaves {item:08X} now and then"
                );
            }
        }
    }
    for (kinds, mine, within) in [
        (&GOLEMS[..], ORDER_MINE, 200.0),
        (&CLUSTERS[..], DOMINION_MINE, 300.0),
    ] {
        let near = t.spawns.camps.iter().any(|c| {
            c.templates.iter().any(|(k, _)| kinds.contains(k))
                && ground_distance(&spot(c.cell, c.origin), &spot(mine.0, mine.1)) <= within
        });
        assert!(near, "guardians about the mine at {:08X}", mine.0);
    }

    // On foot from the headquarters' way in.
    let way_in = way_to(t, 0xD08B, 0x0BF4_010F);
    let arrival = objects[way_in].destination.expect("a landing");
    let mut w = walled(t, &[HQ]);
    w.put(spot(arrival.cell, arrival.origin));
    assert!(w.run_to(objects[at].origin, 3.0), "reached on foot");

    // Played.
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    h.server.kingdom_rows = t.kingdoms.clone();
    let world = player_world(&h);
    let kingdom = |h: &mut Harness, k: u32| {
        let p = h.server.players.get_mut(&world).expect("in");
        yalain_world::kingdoms::set_kingdom(&mut p.qualities, k);
    };
    let said =
        |calls: &[(u32, Option<u32>)]| -> Vec<u32> { calls.iter().filter_map(|c| c.1).collect() };
    set_level(&mut h, 30);
    kingdom(&mut h, 2);
    use_person(&mut h, b, me, t, at);
    assert_eq!(state_of(&h, QUEST), None, "the Order's given nothing");
    kingdom(&mut h, 4);
    set_level(&mut h, 20);
    let to = said(&use_person(&mut h, b, me, t, at));
    assert!(to.contains(&TOO_WEAK), "too weak: {to:08X?}");
    assert_eq!(state_of(&h, QUEST), None);
    set_level(&mut h, 30);
    let to = said(&use_person(&mut h, b, me, t, at));
    assert!(to.contains(&TASK), "her task: {to:08X?}");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)), "given");
    let (to, left) = offered(&mut h, b, me, t, (SUTHANNA, DOMINION[0]), (1, 1));
    assert_eq!(left, Some(1), "her own kingdom's handed back");
    assert!(to.contains(&OF_DOMINION), "her line for it: {to:08X?}");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)));
    let (to, left) = offered(&mut h, b, me, t, (SUTHANNA, ORDER[0]), (1, 1));
    assert!(left.is_none(), "the Order's kept");
    let heard: Vec<u32> = to
        .iter()
        .copied()
        .filter(|s| [OF_ORDER, PERMITTED].contains(s))
        .collect();
    assert_eq!(heard, [OF_ORDER, PERMITTED], "her lines, in their order");
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "done"
    );
    h.advance(86_400.0);
    use_person(&mut h, b, me, t, at);
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "never given again"
    );
    // Another of the Dominion.
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    h.server.kingdom_rows = t.kingdoms.clone();
    let world = player_world(&h);
    set_level(&mut h, 30);
    {
        let p = h.server.players.get_mut(&world).expect("in");
        yalain_world::kingdoms::set_kingdom(&mut p.qualities, 4);
    }
    use_person(&mut h, b, me, t, at);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 1)),
        "another given it"
    );
    let (to, left) = offered(&mut h, b, me, t, (SUTHANNA, SHADOW[1]), (1, 1));
    assert!(left.is_none(), "the Shadow's mote kept");
    assert!(
        to.contains(&OF_SHADOW),
        "her line for the Shadow's: {to:08X?}"
    );
    assert_eq!(state_of(&h, QUEST).map(|q| q.0), Some(status::COMPLETED));
}

/// **The temple's priestess gives the star's quest, whose recipe's making ends it**: she stands in
/// the Radiant Temple where January 2017 found her, where a guide of the time puts the star's giver,
/// reached on foot from the temple's smith; her use gives the quest with her line for a task and
/// teaches the recipe that assembles the star from six radiant stars, whose making ends the quest.
/// Given, a second use rouses nothing but her line for it. A chaos crystal given to the cleansed
/// forge makes a star, and that star given to Arramora's beacon is its reward's, the quest still under
/// way; six radiant stars (made here: no row of the world gives one) through her recipe make the star
/// and end the quest, and she does not give it again.
/// Behaviour: server.quests.star-of-heroes-giver-walk-through
#[test]
fn the_temples_priestess_gives_the_stars_quest_whose_recipes_making_ends_it() {
    use yalain_content::quests::{Trigger, Update};
    use yalain_world::craft::Action;
    use yalain_world::quests::status;
    const QUEST: u32 = 0x4000_01CF;
    const PRIESTESS: u32 = 0x4700_3264;
    const SMITH: u32 = 0x4700_3267;
    const RECIPE: u32 = 0x6F00_0329;
    const RADIANT: u32 = 0x4700_0B42;
    const RECIPE_STAR: u32 = 0x4700_0BAC;
    const FORGE: u32 = 0x4700_2F63;
    const BEACON: u32 = 0x4700_326A;
    const CRYSTAL: u32 = 0x4700_131C;
    const FORGE_STAR: u32 = 0x4700_184B;
    const CLEANSE: u32 = 0x4000_0303;
    const GREAT: u32 = 0x4000_0266;
    /// Her lines: a task given, and no rousing her.
    const TASK: u32 = 0x2FE8_93C2;
    const IGNORES: u32 = 0x68A5_0E56;
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let priestess = placed(t, PRIESTESS);
    let o = &objects[priestess];
    assert_eq!(o.cell >> 16, 0xB079, "in the Radiant Temple");
    // A guide's place for her, 4.9S 38.6E, as the map counts it.
    let block = |shift: u32| f32::from(u8::try_from((o.cell >> shift) & 0xFF).unwrap_or(0));
    let ns = (block(16) * 160.0 + o.origin[1] - 20408.0) / 204.0;
    let ew = (block(24) * 160.0 + o.origin[0] - 20408.0) / 204.04;
    assert!(
        (ns + 4.9).abs() < 0.3 && (ew - 38.6).abs() < 0.3,
        "where the guide puts her: {ns} {ew}"
    );
    let step = t
        .quests
        .steps
        .iter()
        .find(|s| s.quest == QUEST && s.trigger == Trigger::Use(PRIESTESS))
        .expect("her step");
    assert_eq!((step.needs, step.update), (0, Update::Bestow));
    assert_eq!(step.recipes, [RECIPE], "the star's recipe");
    let portal = yalain_testkit::authored::Portal::open();
    let craft = portal.crafting(&[], &[RECIPE]);
    let actions: Vec<&Action> = craft.recipes[&RECIPE]
        .checks
        .iter()
        .flat_map(|c| &c.outcomes)
        .flat_map(|o| &o.actions)
        .collect();
    assert!(
        actions
            .iter()
            .any(|a| matches!(a, Action::Produce { template, .. } if *template == RECIPE_STAR)),
        "the recipe makes the star"
    );

    // On foot: her place from the smith's.
    let mut w = walled(t, &[0xB079]);
    let s = &objects[placed(t, SMITH)];
    w.put(spot(s.cell, [s.origin[0] + 1.0, s.origin[1], s.origin[2]]));
    assert!(w.run_to(o.origin, 3.0), "the priestess from the smith");

    // Played.
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    set_level(&mut h, 60);
    let world = player_world(&h);
    h.server.effect_table = {
        let mut e = h.server.effect_table.clone();
        let wanted: Vec<u32> = t
            .quests
            .effect_states()
            .chain(craft.outcome_effects())
            .collect();
        e.effects
            .extend(effects_read(&wanted, &t.effect_rules).effects);
        e
    };
    h.server.crafting = craft;
    for item in [RADIANT, RECIPE_STAR, CRYSTAL, FORGE_STAR] {
        h.server.catalog.insert(as_installed(&portal, item));
    }
    let said = |h: &mut Harness| -> Vec<u32> {
        use_person(h, b, me, t, priestess)
            .into_iter()
            .filter_map(|(_, s)| s)
            .collect()
    };
    let told = said(&mut h);
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)), "given");
    assert!(told.contains(&TASK), "her line for a task: {told:08X?}");
    let knows = h.server.players[&world]
        .play
        .recipes
        .iter()
        .any(|r| r.recipe == RECIPE);
    assert!(knows, "the star's recipe taught");
    let told = said(&mut h);
    assert!(told.contains(&IGNORES), "not roused again: {told:08X?}");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)));

    // The forge's star is the beacon's, and assembles nothing.
    put_done(&mut h, CLEANSE);
    let (_, left) = offered(&mut h, b, me, t, (FORGE, CRYSTAL), (1, 1));
    assert_eq!(left, None, "the crystal kept");
    assert!(holds_item(&h, FORGE_STAR), "the forge's star");
    let (_, left) = offered(&mut h, b, me, t, (BEACON, FORGE_STAR), (1, 1));
    assert_eq!(left, None, "the beacon takes it");
    assert_eq!(state_of(&h, GREAT).map(|q| q.0), Some(status::COMPLETED));
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 1)),
        "the forge's star assembles nothing"
    );

    // Six radiant stars through her recipe: the star assembled, the quest ended.
    let stars: Vec<u64> = (0..6)
        .map(|_| {
            yalain_world::inventory::give(&mut h.server, &mut h.net, world, RADIANT, 1)
                .expect("made")
        })
        .collect();
    h.run(3);
    let made = {
        use auberean_script::args::Arg;
        use auberean_script::library::Elem;
        use auberean_script::native_object::Item;
        use yalain_world::craft::function;
        let slots: Vec<(Item, Item)> = (1..)
            .zip(&stars)
            .map(|(slot, id)| (Item::Word(slot), Item::Long(*id)))
            .collect();
        let mut g = yalain_world::graph::Builder::new();
        g.native(
            8,
            yalain_world::graph::hash(Elem::Word, Elem::Long, 0, &slots),
        );
        let from = h.bots[b].inbox.len();
        h.bots[b].send(
            true,
            queue::WEENIE,
            &server_call(
                function::EXECUTE,
                &[
                    Arg::LongInt(0),
                    Arg::Object(g.graph()),
                    Arg::Int(0),
                    Arg::Int(RECIPE),
                ],
            ),
        );
        let cycles = h.server.crafting.recipes[&RECIPE].cycles;
        let until = h.now.0 + yalain_world::craft::timing(cycles).1 + 1.0;
        let answered = |h: &Harness| {
            h.calls(b, from)
                .into_iter()
                .find(|(f, _)| *f == function::EXECUTED)
                .and_then(|(_, v)| match v.get(1) {
                    Some(yalain_world::calls::Value::Int(e)) => Some(*e),
                    _ => None,
                })
        };
        while h.now.0 < until && answered(&h).is_none() {
            h.step();
        }
        h.run(2);
        answered(&h)
    };
    assert_eq!(made, Some(0), "the star made");
    assert_eq!(held_count(&h, RADIANT), 0, "the radiant stars used up");
    assert!(holds_item(&h, RECIPE_STAR), "the assembled star");
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "its making ends the quest"
    );
    said(&mut h);
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "not given again"
    );
}

/// The templates of the pieces a player holds that its race and kingdom wear from the forge's new suit: armor asking
/// for a race, a kingdom and 92 arcane lore, as the install's own templates say.
fn forge_suit_held(h: &Harness) -> Vec<(u32, u32, u32, u32)> {
    let portal = yalain_testkit::authored::Portal::open();
    let mut out: Vec<(u32, u32, u32, u32)> = h
        .server
        .players
        .values()
        .flat_map(|p| p.play.items.iter())
        .filter_map(|x| {
            let p = as_installed(&portal, x.template).props;
            (p.int("Usage_RequiredArcaneLore") == Some(92)).then(|| {
                let w = |n: &str| p.word(n).unwrap_or(0);
                (
                    x.template,
                    w("Usage_RequiredRace"),
                    w("Usage_RequiredFaction"),
                    w("Item_ValidInventoryLocations"),
                )
            })
        })
        .collect();
    out.sort_unstable();
    out
}

/// **A huge pyreum begins the cleansed forge's new suit, and the player's blood ends it with the armor of its race and
/// kingdom**: the quest is its setup's (challenge 55, a day long, given again a second after it is done, from level
/// 50); the forge stands in the forge room, reached on foot from the hammer, and given the pyreum from there by one of
/// a kingdom who has cleansed it, it begins the quest. Played: before the forge is cleansed the pyreum is handed back
/// with its line for an item it does not take, and a use says nothing of a suit; once cleansed a use says its
/// instructions for a new suit; the pyreum is handed back to one of no kingdom and to one under level 50, and kept from
/// one of a kingdom with its line as the gem bursts, the quest at its first phase. Each of the five other essences is
/// kept with its line as it boils away, the quest unmoved; the essence that heals moves it to its second phase with its
/// line asking for five of the ebon metal; two of them at once are handed back, and five given one at a time move it a
/// phase each, the first four with the smelting line and the fifth with the spheres'; 99,999 coins are handed back and
/// 100,000 kept with their line, moving it on; the attuned crystal moves it to the last phase with its line, making no
/// star; a use then ends it with the attuning line and the five pieces of the player's race and kingdom, one for each
/// place worn. A second suit is begun a moment later, and the crystal of the tree's chain serves too. Each race of each
/// kingdom is given its own five pieces; one of no kingdom at the last phase is given nothing.
/// Behaviour: server.quests.osteth-chaos-forge-new-suit-walk-through
#[test]
fn a_huge_pyreum_begins_the_cleansed_forges_new_suit_and_the_players_blood_ends_it_with_its_race_and_kingdoms_armor(
) {
    use yalain_content::quests::{Trigger, Update};
    use yalain_world::quests::status;
    const QUEST: u32 = 0x4000_0305;
    const CLEANSE: u32 = 0x4000_0303;
    const FORGE: u32 = 0x4700_2F63;
    const HAMMER: u32 = 0x4700_2F66;
    const PYREUM: u32 = 0x4700_106B;
    const HEALS: u32 = 0x4700_1324;
    const OTHER_ESSENCES: [u32; 5] = [
        0x4700_1326,
        0x4700_1327,
        0x4700_1328,
        0x4700_1329,
        0x4700_132A,
    ];
    const EBON: u32 = 0x4700_0AFD;
    const COIN: u32 = 0x4700_0538;
    const ATTUNED_CRYSTAL: u32 = 0x4700_131C;
    const TREE_CRYSTAL: u32 = 0x4700_0612;
    const STAR: u32 = 0x4700_184B;
    /// The forge's lines: the gem bursting, the essence hissing, another essence boiling away, the metal smelted, the
    /// fifth's spheres, the coins, the crystal, the blood, its instructions, and an item handed back.
    const BEGUN: u32 = 0xE026_5634;
    const HISSES: u32 = 0x01ED_2C80;
    const BOILS: u32 = 0x728C_DEF5;
    const SMELTED: u32 = 0xA93F_106A;
    const SPHERES: u32 = 0xA53F_106A;
    const COINS_LINE: u32 = 0xFEDD_AFDC;
    const CRYSTAL_LINE: u32 = 0xBFF4_0440;
    const ATTUNED: u32 = 0x41AE_4C35;
    const INSTRUCTIONS: u32 = 0x4C63_015E;
    const UNTOUCHED: u32 = 0xF1EB_BC45;
    /// The races by number, and the kingdoms: shadow, order, dominion.
    const RACES: [u32; 5] = [1, 2, 4, 8, 16];
    const KINGDOMS: [u32; 3] = [1, 2, 4];
    let t = &compiled().tables;
    let objects = &t.content.objects;
    let forge = placed(t, FORGE);
    let hammer = placed(t, HAMMER);
    let quest = t.quests.quest(QUEST).expect("the new suit's quest");
    assert_eq!(
        (
            quest.challenge,
            quest.min_level,
            quest.duration,
            quest.retry
        ),
        (55, 50, 86_400.0, 1.0),
        "its setup's values"
    );
    assert_eq!(quest.xp, 0, "no experience for it");
    let blood: Vec<_> = t
        .quests
        .steps
        .iter()
        .filter(|s| {
            s.quest == QUEST && s.trigger == Trigger::Use(FORGE) && s.update == Update::Complete
        })
        .collect();
    assert_eq!(blood.len(), 15, "one ending for each race of each kingdom");
    assert!(blood
        .iter()
        .all(|s| s.needs == 9 && s.races.len() == 1 && s.gives.len() == 5));

    // On foot: the forge from the hammer, and the pyreum given it from there.
    let portal = yalain_testkit::authored::Portal::open();
    let mut w = walled(t, &[objects[forge].cell >> 16]);
    let o = &objects[hammer];
    w.put(spot(o.cell, [o.origin[0] - 1.5, o.origin[1], o.origin[2]]));
    assert!(w.run_to(objects[forge].origin, 10.0), "the forge on foot");
    let body = portal.body(FORGE).expect("the forge's body");
    w.h.server.catalog.bodies.insert(FORGE, body);
    w.h.server.quest_ids = quest_ids();
    w.h.server.kingdom_rows = t.kingdoms.clone();
    set_level(&mut w.h, 60);
    let walker = w.world;
    if let Some(p) = w.h.server.players.get_mut(&walker) {
        yalain_world::kingdoms::set_kingdom(&mut p.qualities, 2);
    }
    put_done(&mut w.h, CLEANSE);
    assert!(w.give_to(t, forge, PYREUM), "given from there, kept");
    assert_eq!(state_of(&w.h, QUEST), Some((status::UNDERWAY, 1)), "begun");

    // Played.
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    h.server.kingdom_rows = t.kingdoms.clone();
    let world = player_world(&h);
    let kingdom = |h: &mut Harness, k: u32| {
        let p = h.server.players.get_mut(&world).expect("in");
        yalain_world::kingdoms::set_kingdom(&mut p.qualities, k);
    };
    let race = |h: &mut Harness, r: u32| {
        h.server.players.get_mut(&world).expect("in").race = r;
    };
    let said = |h: &mut Harness| -> Vec<u32> {
        use_person(h, b, me, t, forge)
            .into_iter()
            .filter_map(|(_, s)| s)
            .collect()
    };
    let unsuited = |h: &mut Harness| {
        let suit: Vec<u32> = forge_suit_held(h).into_iter().map(|x| x.0).collect();
        let p = h.server.players.get_mut(&world).expect("in");
        p.play.items.retain(|x| !suit.contains(&x.template));
    };
    for item in [
        PYREUM,
        HEALS,
        EBON,
        COIN,
        ATTUNED_CRYSTAL,
        TREE_CRYSTAL,
        STAR,
    ]
    .into_iter()
    .chain(OTHER_ESSENCES)
    {
        h.server.catalog.insert(as_installed(&portal, item));
    }
    set_level(&mut h, 60);
    race(&mut h, 1);
    kingdom(&mut h, 2);
    let told = said(&mut h);
    assert!(
        !told.contains(&INSTRUCTIONS),
        "no suit before the forge is cleansed: {told:08X?}"
    );
    let (told, left) = offered(&mut h, b, me, t, (FORGE, PYREUM), (1, 1));
    assert_eq!(
        left,
        Some(1),
        "the pyreum handed back before the forge is cleansed"
    );
    assert!(told.contains(&UNTOUCHED), "untouched: {told:08X?}");
    assert_eq!(state_of(&h, QUEST), None);
    put_done(&mut h, CLEANSE);
    let told = said(&mut h);
    assert!(
        told.contains(&INSTRUCTIONS),
        "its instructions: {told:08X?}"
    );
    assert_eq!(state_of(&h, QUEST), None, "a use begins nothing");
    kingdom(&mut h, 0);
    let (_, left) = offered(&mut h, b, me, t, (FORGE, PYREUM), (1, 1));
    assert_eq!(left, Some(1), "handed back to one of no kingdom");
    assert_eq!(state_of(&h, QUEST), None);
    kingdom(&mut h, 2);
    set_level(&mut h, 49);
    let (_, left) = offered(&mut h, b, me, t, (FORGE, PYREUM), (1, 1));
    assert_eq!(left, Some(1), "handed back under level 50");
    assert_eq!(state_of(&h, QUEST), None);
    set_level(&mut h, 60);
    let (told, left) = offered(&mut h, b, me, t, (FORGE, PYREUM), (1, 1));
    assert_eq!(left, None, "the pyreum kept");
    assert!(told.contains(&BEGUN), "the gem bursts: {told:08X?}");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 1)), "begun");
    let (_, left) = offered(&mut h, b, me, t, (FORGE, EBON), (1, 1));
    assert_eq!(left, Some(1), "the metal is not yet wanted");
    for essence in OTHER_ESSENCES {
        let (told, left) = offered(&mut h, b, me, t, (FORGE, essence), (1, 1));
        assert_eq!(left, None, "{essence:08X} kept");
        assert!(
            told.contains(&BOILS),
            "{essence:08X} boils away: {told:08X?}"
        );
        assert_eq!(
            state_of(&h, QUEST),
            Some((status::UNDERWAY, 1)),
            "{essence:08X} moves nothing"
        );
    }
    let (told, left) = offered(&mut h, b, me, t, (FORGE, HEALS), (1, 1));
    assert_eq!(left, None, "the essence that heals kept");
    assert!(told.contains(&HISSES), "it hisses: {told:08X?}");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 2)));
    let (_, left) = offered(&mut h, b, me, t, (FORGE, EBON), (2, 2));
    assert_eq!(left, Some(2), "two at once handed back");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 2)));
    for n in 0..5_u32 {
        let (told, left) = offered(&mut h, b, me, t, (FORGE, EBON), (1, 1));
        assert_eq!(left, None, "the metal {} kept", n + 1);
        let (line, not) = if n == 4 {
            (SPHERES, SMELTED)
        } else {
            (SMELTED, SPHERES)
        };
        assert!(
            told.contains(&line) && !told.contains(&not),
            "the metal {}: {told:08X?}",
            n + 1
        );
        assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, n + 3)));
    }
    let (_, left) = offered(&mut h, b, me, t, (FORGE, COIN), (99_999, 99_999));
    assert_eq!(left, Some(99_999), "too few coins handed back");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 7)));
    let (told, left) = offered(&mut h, b, me, t, (FORGE, COIN), (100_000, 100_000));
    assert_eq!(left, None, "a hundred thousand kept");
    assert!(told.contains(&COINS_LINE), "the coins' line: {told:08X?}");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 8)));
    let (told, left) = offered(&mut h, b, me, t, (FORGE, ATTUNED_CRYSTAL), (1, 1));
    assert_eq!(left, None, "the crystal kept");
    assert!(
        told.contains(&CRYSTAL_LINE),
        "the crystal's line: {told:08X?}"
    );
    assert!(!holds_item(&h, STAR), "no star made of it");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 9)));
    let told = said(&mut h);
    assert!(told.contains(&ATTUNED), "the blood's line: {told:08X?}");
    assert_eq!(
        state_of(&h, QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "ended"
    );
    let suit = forge_suit_held(&h);
    assert_eq!(suit.len(), 5, "five pieces: {suit:08X?}");
    assert!(
        suit.iter().all(|x| (x.1, x.2) == (1, 2)),
        "the human order's: {suit:08X?}"
    );
    let mut worn: Vec<u32> = suit.iter().map(|x| x.3).collect();
    worn.sort_unstable();
    worn.dedup();
    assert_eq!(worn.len(), 5, "one for each place worn: {suit:08X?}");

    // A second suit, a moment later, with the tree's crystal.
    h.advance(2.0);
    let (_, left) = offered(&mut h, b, me, t, (FORGE, PYREUM), (1, 1));
    assert_eq!(left, None, "a second pyreum kept");
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 1)),
        "begun again"
    );
    put_at_phase(&mut h, QUEST, 8);
    let (_, left) = offered(&mut h, b, me, t, (FORGE, TREE_CRYSTAL), (1, 1));
    assert_eq!(left, None, "the tree's crystal kept");
    assert_eq!(state_of(&h, QUEST), Some((status::UNDERWAY, 9)));

    // Each race of each kingdom, its own five.
    for r in RACES {
        for k in KINGDOMS {
            unsuited(&mut h);
            put_at_phase(&mut h, QUEST, 9);
            race(&mut h, r);
            kingdom(&mut h, k);
            said(&mut h);
            assert_eq!(
                state_of(&h, QUEST).map(|q| q.0),
                Some(status::COMPLETED),
                "race {r} of kingdom {k}"
            );
            let suit = forge_suit_held(&h);
            assert_eq!(suit.len(), 5, "race {r} of kingdom {k}: {suit:08X?}");
            assert!(
                suit.iter().all(|x| (x.1, x.2) == (r, k)),
                "race {r} of kingdom {k}: {suit:08X?}"
            );
        }
    }
    unsuited(&mut h);
    put_at_phase(&mut h, QUEST, 9);
    kingdom(&mut h, 0);
    said(&mut h);
    assert_eq!(
        state_of(&h, QUEST),
        Some((status::UNDERWAY, 9)),
        "one of no kingdom"
    );
    assert!(forge_suit_held(&h).is_empty(), "given nothing");
}

/// **The plane of chaos's six bosses now and then leave the huge pyreum the forge's new suit begins with**: no source
/// drops it, so the world has each of them leave one at a rare chance of its own (above 0, at most one in twenty),
/// and no other creature; one camp keeps each boss alone. On foot, the eidolon is reached from its dungeon's landing
/// and each platform's golem from where the hammer's quest lands a player on that platform. Played: the eidolon its
/// camp makes, killed again and again, leaves a corpse holding the pyreum.
/// Behaviour: server.quests.osteth-chaos-forge-huge-pyreum-drop
#[test]
fn the_chaos_planes_six_bosses_now_and_then_leave_the_huge_pyreum_the_forges_new_suit_begins_with()
{
    const PYREUM: u32 = 0x4700_106B;
    const EIDOLON: u32 = 0x4700_2C94;
    const WAY_ON: u32 = 0x4700_131E;
    const CLEANSE: u32 = 0x4000_0303;
    /// Each boss and its block: the eidolon, then the forge's five platforms' golems.
    const BOSSES: [(u32, u32); 6] = [
        (EIDOLON, 0x04B4),
        (0x4700_250B, 0x04BD),
        (0x4700_2507, 0x04BE),
        (0x4700_2509, 0x04BF),
        (0x4700_2508, 0x04C0),
        (0x4700_250A, 0x04C1),
    ];
    let t = &compiled().tables;
    let objects = &t.content.objects;
    for (boss, block) in BOSSES {
        let camps: Vec<_> = t
            .spawns
            .camps
            .iter()
            .filter(|c| c.templates.iter().any(|(x, _)| *x == boss))
            .collect();
        assert_eq!(camps.len(), 1, "{boss:08X}: one camp keeps it");
        let camp = camps[0];
        assert_eq!(
            (camp.cell >> 16, camp.population),
            (block, 1),
            "{boss:08X} alone"
        );
        assert!(
            camp.templates.iter().all(|(x, _)| *x == boss),
            "{boss:08X} alone"
        );
        let chances: Vec<f32> = t
            .loot
            .treasures_of(boss, Some(&camp.id))
            .filter(|d| d.item == PYREUM)
            .map(|d| d.chance)
            .collect();
        assert_eq!(chances.len(), 1, "{boss:08X} leaves the pyreum");
        assert!(
            chances[0] > 0.0 && chances[0] <= 0.05,
            "{boss:08X}: rarely, {}",
            chances[0]
        );
    }
    let droppers = t.loot.treasures.iter().filter(|d| d.item == PYREUM).count();
    assert_eq!(droppers, BOSSES.len(), "no other creature leaves it");

    // On foot: the eidolon from its dungeon's landing, each golem from its platform's landing.
    let landing = objects[placed(t, WAY_ON)]
        .destination
        .expect("the way on's landing");
    for (boss, block) in BOSSES {
        let from = if boss == EIDOLON {
            (landing.cell, landing.origin)
        } else {
            t.quests
                .steps
                .iter()
                .filter(|s| s.quest == CLEANSE)
                .filter_map(|s| s.to.as_ref())
                .find(|p| p.cell >> 16 == block)
                .map(|p| (p.cell, p.origin))
                .unwrap_or_else(|| panic!("a landing on {block:04X}"))
        };
        assert_eq!(from.0 >> 16, block, "{boss:08X}'s landing in its block");
        let camp = camps_keeping(t, block, boss)[0];
        let mut w = walled(t, &[block]);
        w.put(spot(from.0, from.1));
        assert!(
            w.run_far(camp.cell, camp.origin, 4.0),
            "{boss:08X} on foot from its landing"
        );
    }

    // Played: the eidolon killed again and again, until its corpse holds the pyreum.
    let camp = camps_keeping(t, 0x04B4, EIDOLON)[0].clone();
    let portal = yalain_testkit::authored::Portal::open();
    let (mut h, _b, me) = served(t);
    h.server.loot = t.loot.clone();
    for kind in [EIDOLON, PYREUM] {
        h.server.catalog.insert(as_installed(&portal, kind));
    }
    h.server.content.guards = yalain_content::guards::GuardTable { rows: Vec::new() };
    h.server.spawns.camps = vec![camp.clone()];
    h.server.camps = vec![yalain_world::spawn::CampState::default()];
    for p in h.server.players.values_mut() {
        p.position.cell = camp.cell;
        p.position.origin = camp.origin;
    }
    let corpses = |h: &Harness| -> Vec<u64> {
        let mut v: Vec<u64> = h
            .server
            .things
            .by_id
            .values()
            .filter(|x| x.corpse.as_ref().is_some_and(|c| c.creature == EIDOLON))
            .map(|x| x.id)
            .collect();
        v.sort_unstable();
        v
    };
    let holds_pyreum = |h: &Harness, corpse: u64| {
        h.server
            .things
            .get(corpse)
            .and_then(|x| x.corpse.as_ref())
            .is_some_and(|c| {
                c.contents.iter().any(|i| {
                    h.server
                        .things
                        .get(*i)
                        .is_some_and(|x| x.template == PYREUM)
                })
            })
    };
    let mut kills = 0;
    let mut found = false;
    while !found && kills < 2_000 {
        assert!(
            h.run_until(800, |h| !living_of(h, EIDOLON).is_empty()),
            "its camp makes it again ({kills} kills)"
        );
        let id = living_of(&h, EIDOLON)[0];
        if let Some(c) = h
            .server
            .things
            .get_mut(id)
            .and_then(|x| x.creature.as_mut())
        {
            c.stats.attacks_first = false;
        }
        let before = corpses(&h).last().copied().unwrap_or(0);
        let clock = h.clock();
        yalain_world::combat::hurt_creature(&mut h.server, &mut h.net, id, me, 100_000_000, clock);
        assert!(
            h.run_until(800, |h| corpses(h).last().copied().unwrap_or(0) > before),
            "its corpse ({kills} kills)"
        );
        kills += 1;
        let corpse = corpses(&h).last().copied().unwrap_or(0);
        found = holds_pyreum(&h, corpse);
        h.advance(camp.regen);
    }
    assert!(found, "a corpse holds the pyreum within {kills} kills");
}

/// **The kingdom shrines walk through**: the round's guardian stands at the red shrine as the world
/// starts, the five shrines its stops in their order; killed by a player of the Order, it brings the
/// Order's radiant to the shrine and the monsters of the Shadow and the Dominion beside it, none of
/// the Order's, and the next guardian, at the yellow shrine, is the Order's, which no player of the
/// Order may harm; the radiant used empowers the player and gives the Order's red ray, once; a
/// Dominion monster killed leaves the Dominion's lens for the empowered, and the lens handed to the
/// radiant becomes the Dominion's red ray.
/// Behaviour: server.quests.kingdom-shrines-walk-through
#[test]
fn the_shrines_guardian_goes_round_and_its_death_brings_the_killers_radiant_whose_rays_come_of_talk_and_lenses(
) {
    use yalain_world::kingdoms::{kingdom, refusal, set_kingdom};
    use yalain_world::quests::status;
    use yalain_world::things::Mode;
    const EMPOWERMENT: u32 = 0x4000_01CD;
    // Each stop: the neutral guardian, the Order's, and the shrine's landblock.
    const STOPS: [(u32, u32, u32); 5] = [
        (0x4700_2600, 0x4700_2601, 0x5CB1),
        (0x4700_2608, 0x4700_2609, 0xA08A),
        (0x4700_25FC, 0x4700_25FD, 0x5558),
        (0x4700_25F8, 0x4700_25F9, 0x4748),
        (0x4700_2604, 0x4700_2605, 0xB470),
    ];
    const RED_ORDER_RADIANT: u32 = 0x4700_3253;
    const RED_ORDER_RAY: u32 = 0x4700_0B9E;
    const RED_DOMINION_RAY: u32 = 0x4700_0B98;
    const DOMINION_LENS: u32 = 0x4700_1832;
    const SHADOWS: [u32; 2] = [0x4700_2AC3, 0x4700_2AC4];
    const VIRINDI: [u32; 2] = [0x4700_2D54, 0x4700_2D5A];
    const GOLEMS: [u32; 2] = [0x4700_24E1, 0x4700_24DD];
    let t = &compiled().tables;
    let round = t
        .content
        .rounds
        .rows
        .iter()
        .find(|r| r.key == "shrine-guardian")
        .expect("the shrines' round");
    let stops: Vec<(u32, u32, u32)> = round
        .stops
        .iter()
        .map(|s| {
            (
                s.template,
                s.template_for(Some(kingdom::ORDER)),
                s.at.cell >> 16,
            )
        })
        .collect();
    assert_eq!(stops, STOPS, "red to violet, each neutral and the Order's");

    let portal = yalain_testkit::authored::Portal::open();
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    h.server.creature_rows = t.creatures.clone();
    h.server.kingdom_rows = t.kingdoms.clone();
    h.server.death_spawns = t
        .death_spawns
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    h.server.loot.treasures = t.loot.treasures.clone();
    // The catalog a real start reads: the round's creatures and what the deaths make among it.
    h.server.catalog = portal.catalog(t);
    set_level(&mut h, 50);
    let world = player_world(&h);
    if let Some(p) = h.server.players.get_mut(&world) {
        set_kingdom(&mut p.qualities, kingdom::ORDER);
    }
    h.run(5);
    let standing = |h: &Harness, template: u32| -> Vec<u64> {
        let mut v: Vec<u64> = h
            .server
            .things
            .by_id
            .values()
            .filter(|t| t.template == template)
            .filter(|t| t.creature.as_ref().is_some_and(|c| c.mode != Mode::Dead))
            .map(|t| t.id)
            .collect();
        v.sort_unstable();
        v
    };
    // The killer beside the creature, as one fighting it stands.
    let kill = |h: &mut Harness, id: u64| {
        let at = h.server.things.get(id).and_then(|t| t.at).expect("placed");
        for p in h.server.players.values_mut() {
            p.position.cell = at.cell;
            p.position.origin = [at.origin[0] + 1.0, at.origin[1], at.origin[2]];
        }
        if let Some(t) = h.server.things.get_mut(id) {
            t.health = 1;
        }
        let clock = h.clock();
        yalain_world::combat::hurt_creature(&mut h.server, &mut h.net, id, me, 50, clock);
        h.run(5);
    };
    let red = standing(&h, STOPS[0].0);
    assert_eq!(
        red.len(),
        1,
        "the red shrine's guardian as the world starts"
    );
    let at = h
        .server
        .things
        .get(red[0])
        .and_then(|t| t.at)
        .expect("placed");
    assert_eq!(at.cell >> 16, 0x5CB1, "at the red shrine");

    let radiant = placed(t, RED_ORDER_RADIANT);
    assert_eq!(
        t.content.objects[radiant].cell >> 16,
        0x5CB1,
        "in the red shrine"
    );
    let stands = |h: &Harness, template: u32| {
        let id = yalain_world::presence::content_id(&t.content.objects, placed(t, template));
        yalain_world::events::content_standing(&h.server, id).is_some()
    };
    assert!(
        !stands(&h, RED_ORDER_RADIANT),
        "no radiant before the guardian's death"
    );
    kill(&mut h, red[0]);
    assert!(
        stands(&h, RED_ORDER_RADIANT),
        "the Order's radiant in the red shrine"
    );
    assert_eq!(
        [0x4700_3251, 0x4700_3254].map(|r| stands(&h, r)),
        [false, false],
        "not the other kingdoms'"
    );
    let made = |h: &Harness, kinds: [u32; 2]| kinds.map(|k| standing(h, k).len());
    assert_eq!(
        made(&h, SHADOWS),
        [3, 1],
        "the Shadow's monsters, solo and group"
    );
    assert_eq!(made(&h, VIRINDI), [3, 1], "the Dominion's");
    assert_eq!(made(&h, GOLEMS), [0, 0], "none of the killer's own kingdom");
    let yellow = standing(&h, STOPS[1].1);
    assert_eq!(yellow.len(), 1, "the yellow shrine's guardian, the Order's");
    assert_eq!(
        yalain_world::combat::may_attack_thing(&h.server, world, yellow[0]),
        Err(refusal::SAME_KINGDOM),
        "no player of the Order may harm it for a while"
    );

    use_person(&mut h, b, me, t, radiant);
    assert_eq!(
        state_of(&h, EMPOWERMENT).map(|s| s.0),
        Some(status::UNDERWAY),
        "empowered"
    );
    assert_eq!(held_count(&h, RED_ORDER_RAY), 1, "the Order's red ray");
    use_person(&mut h, b, me, t, radiant);
    assert_eq!(held_count(&h, RED_ORDER_RAY), 1, "one a visit");

    let virindi = standing(&h, VIRINDI[1]);
    kill(&mut h, virindi[0]);
    // Its corpse lies once it has fallen.
    let fallen = h.now.0 + 2.5;
    while h.now.0 < fallen {
        h.step_by(0.25);
    }
    let lens_left = h.server.things.by_id.values().any(|t| {
        t.corpse.as_ref().is_some_and(|c| {
            c.originator == virindi[0]
                && c.contents
                    .iter()
                    .filter_map(|i| h.server.things.get(*i))
                    .any(|i| i.template == DOMINION_LENS)
        })
    });
    assert!(lens_left, "the Dominion's lens, for the empowered");
    yalain_world::inventory::give(&mut h.server, &mut h.net, world, DOMINION_LENS, 1)
        .expect("given");
    h.run(3);
    let lens = h.server.players[&world]
        .play
        .items
        .iter()
        .find(|i| i.template == DOMINION_LENS)
        .map(|i| i.id)
        .expect("a lens held");
    gave_held(&mut h, (b, me, world), t, RED_ORDER_RADIANT, lens);
    assert_eq!(
        held_count(&h, RED_DOMINION_RAY),
        1,
        "the Dominion's red ray for its lens"
    );
    assert_eq!(held_count(&h, DOMINION_LENS), 0, "the lens taken");
}

/// **An outpost's guards go with its beacon**: the world's rows give each of the eighteen placed
/// beacons its guards, the camps of its race beside it. For each beacon, with its camp and its
/// guards' camps alone in the world: the guards stand with the beacon; as the beacon dies they
/// leave the world, leaving no corpse, and none stands while the beacon is down; the beacon's camp
/// makes the next after its period, and every guard camp fills again with it.
/// Behaviour: server.quests.beacon-guards-walk
#[test]
fn each_outposts_guards_leave_the_world_with_its_beacon_and_come_back_with_the_next() {
    use yalain_world::things::Mode;
    let t = &compiled().tables;
    let beacons: std::collections::BTreeSet<&str> =
        t.spawns.masters.iter().map(|(_, m)| m.as_str()).collect();
    assert_eq!((t.spawns.masters.len(), beacons.len()), (49, 18));
    let portal = yalain_testkit::authored::Portal::open();
    for beacon in beacons {
        let camp = |id: &str| {
            t.spawns
                .camps
                .iter()
                .find(|c| c.id == id)
                .cloned()
                .unwrap_or_else(|| panic!("camp {id}"))
        };
        let master = camp(beacon);
        let npc_table = as_installed(&portal, master.templates[0].0)
            .props
            .text("AI_NPCTable")
            .map(str::to_string);
        assert_eq!(
            npc_table.as_deref(),
            Some("NPCTable_PortalBeacon"),
            "{beacon}"
        );
        let guards: Vec<String> = t.spawns.serving(beacon).map(str::to_string).collect();
        let (mut h, _, me) = served(t);
        h.server.catalog = portal.catalog(t);
        h.server.spawns = yalain_content::SpawnTable {
            camps: std::iter::once(master)
                .chain(guards.iter().map(|g| camp(g)))
                .collect(),
            masters: guards
                .iter()
                .map(|g| (g.clone(), beacon.to_string()))
                .collect(),
        };
        h.server.camps = vec![yalain_world::spawn::CampState::default(); guards.len() + 1];
        h.run(5);
        let kept = |h: &Harness, i: usize| -> Vec<u64> {
            h.server.camps[i]
                .alive
                .iter()
                .copied()
                .filter(|id| {
                    h.server
                        .things
                        .get(*id)
                        .and_then(|t| t.creature.as_ref())
                        .is_some_and(|c| c.mode != Mode::Dead)
                })
                .collect()
        };
        let full = |h: &Harness| {
            (1..=guards.len())
                .map(|i| kept(h, i).len() == h.server.spawns.camps[i].population as usize)
                .collect::<Vec<_>>()
        };
        assert_eq!(kept(&h, 0).len(), 1, "{beacon} stands");
        assert!(
            full(&h).iter().all(|f| *f),
            "{beacon}'s guards stand with it"
        );
        let standing: Vec<u64> = (1..=guards.len()).flat_map(|i| kept(&h, i)).collect();
        let id = kept(&h, 0)[0];
        if let Some(b) = h.server.things.get_mut(id) {
            b.health = 1;
        }
        let clock = h.clock();
        yalain_world::combat::hurt_creature(&mut h.server, &mut h.net, id, me, 50, clock);
        h.run(2);
        assert!(
            standing.iter().all(|g| h.server.things.get(*g).is_none()),
            "{beacon}'s guards leave the world as it dies, no corpse left"
        );
        let regen = h.server.spawns.camps[0].regen;
        let down = h.now.0 + regen * 0.9;
        while h.now.0 < down {
            h.step_by(0.25);
        }
        assert!(
            (1..=guards.len()).all(|i| kept(&h, i).is_empty()),
            "{beacon}'s guards stay gone while it is down"
        );
        let back = h.now.0 + regen * 0.2;
        while h.now.0 < back {
            h.step_by(0.25);
        }
        assert_eq!(kept(&h, 0).len(), 1, "{beacon}'s next");
        assert!(
            full(&h).iter().all(|f| *f),
            "{beacon}'s guards stand again with it"
        );
    }
}

/// **The Order's and the Shadow's headquarters walk through**: each kingdom's way in, the placed
/// portal in Ikeras named for its headquarters, takes a player of its kingdom to the landing the
/// raids' portals home lead to, and none of another kingdom; from the landing its mine overseer, its
/// four mine beacons and its way out are reached on foot; its Omishan beacon gives the raid, the
/// crystal and the beacons' hour; its overseer gives the boon's task, refuses its own kingdom's
/// material and takes an enemy kingdom's, completing it; and its way out leads back out beside the
/// way in.
/// Behaviour: server.quests.kingdom-headquarters-walk-through
#[test]
fn the_orders_and_the_shadows_headquarters_are_entered_by_their_kingdom_and_hold_their_overseer_and_beacons(
) {
    use yalain_world::quests::status;
    use yalain_world::usable::maps::ground_distance;
    const OMI_RAID: u32 = 0x4000_0355;
    const PERMISSION: u32 = 0x4000_0359;
    const BOON: u32 = 0x4000_0351;
    struct Hq {
        kingdom: u32,
        outside: u32,
        landing: u32,
        destination: &'static str,
        exit: u32,
        overseer: u32,
        beacons: [u32; 4],
        omishan: (u32, u32),
        own: u32,
        enemy: u32,
    }
    let hqs = [
        Hq {
            kingdom: 2,
            outside: 0xCE8C,
            landing: 0x0BF5_0100,
            destination: "dng_orderhq",
            exit: 0xCE8C_0034,
            overseer: 0x4700_2FC0,
            beacons: [0x4700_1482, 0x4700_1483, 0x4700_1488, 0x4700_1489],
            omishan: (0x4700_1488, 0x4700_1476),
            own: 0x4700_147C,
            enemy: 0x4700_147E,
        },
        Hq {
            kingdom: 1,
            outside: 0xCE8D,
            landing: 0x0BF6_010C,
            destination: "dng_shadowhq",
            exit: 0xCE8D_003C,
            overseer: 0x4700_2FC2,
            beacons: [0x4700_1484, 0x4700_1485, 0x4700_148A, 0x4700_148B],
            omishan: (0x4700_148A, 0x4700_1478),
            own: 0x4700_147E,
            enemy: 0x4700_147C,
        },
    ];
    let t = &compiled().tables;
    for hq in &hqs {
        let block = hq.landing >> 16;
        let way_in = way_to(t, hq.outside, hq.landing);
        let arrival = t.content.objects[way_in].destination.expect("a landing");
        let place = t.places_by_name.get(hq.destination).expect("its place");
        assert!(
            ground_distance(
                &spot(place.cell, place.origin),
                &spot(arrival.cell, arrival.origin)
            ) < 1.0,
            "{:04X}: the portals home lead where the way in does",
            block
        );
        let way_out = way_to(t, block, hq.exit);
        let in_hq = |template: u32| {
            let i = placed(t, template);
            assert_eq!(
                t.content.objects[i].cell >> 16,
                block,
                "{template:08X} in {block:04X}"
            );
            i
        };

        let mut w = walled(t, &[hq.outside, block]);
        let world = w.world;
        let at = |w: &Walled| w.h.server.players[&world].position;
        let beside = |w: &mut Walled, i: usize| {
            let o = &t.content.objects[i];
            w.put(spot(o.cell, [o.origin[0] + 1.0, o.origin[1], o.origin[2]]));
        };
        {
            let p = w.h.server.players.get_mut(&world).expect("in");
            yalain_world::quals::set_int(&mut p.qualities, yalain_world::examine::LEVEL, 50);
            yalain_world::kingdoms::set_kingdom(&mut p.qualities, 4);
        }
        beside(&mut w, way_in);
        w.use_placed(t, way_in);
        assert_eq!(
            at(&w).cell >> 16,
            hq.outside,
            "{block:04X}: not for the Dominion"
        );
        yalain_world::kingdoms::set_kingdom(
            &mut w.h.server.players.get_mut(&world).expect("in").qualities,
            hq.kingdom,
        );
        w.use_placed(t, way_in);
        assert_eq!(at(&w).cell, hq.landing, "{block:04X}: in, at its landing");

        // On foot from the landing, each at least a meter off (a body stands where it is placed).
        let mut reached = vec![in_hq(hq.overseer), way_out];
        reached.extend(hq.beacons.map(in_hq));
        for i in reached {
            w.put(spot(arrival.cell, arrival.origin));
            let o = t.content.objects[i].clone();
            assert!(
                w.run_to(o.origin, 2.0),
                "{:08X} reached on foot in {block:04X}",
                o.template
            );
        }

        // The raid, its crystal and the hour.
        with_uses(&mut w.h, t, &[hq.omishan.0, hq.omishan.1, hq.own, hq.enemy]);
        w.h.server.quest_ids = quest_ids();
        w.h.server.kingdom_rows = t.kingdoms.clone();
        let beacon = in_hq(hq.omishan.0);
        beside(&mut w, beacon);
        w.use_placed(t, beacon);
        assert_eq!(
            state_of(&w.h, OMI_RAID),
            Some((status::UNDERWAY, 1)),
            "{block:04X}: the raid"
        );
        assert_eq!(
            state_of(&w.h, PERMISSION).map(|q| q.0),
            Some(status::UNDERWAY),
            "the hour"
        );
        assert!(holds_item(&w.h, hq.omishan.1), "{block:04X}: its crystal");

        // The overseer's task.
        let overseer = in_hq(hq.overseer);
        beside(&mut w, overseer);
        w.use_placed(t, overseer);
        assert_eq!(
            state_of(&w.h, BOON).map(|q| q.0),
            Some(status::UNDERWAY),
            "{block:04X}: the task"
        );
        for item in [hq.own, hq.enemy] {
            yalain_world::inventory::give(&mut w.h.server, &mut w.h.net, world, item, 1)
                .expect("given");
        }
        w.h.run(3);
        let held = |w: &Walled, template: u32| {
            w.h.server.players[&world]
                .play
                .items
                .iter()
                .find(|i| i.template == template)
                .map(|i| i.id)
        };
        let own = held(&w, hq.own).expect("its own kingdom's");
        gave_held(&mut w.h, (w.b, w.me, world), t, hq.overseer, own);
        assert!(
            holds_item(&w.h, hq.own),
            "{block:04X}: its own kingdom's handed back"
        );
        assert_eq!(state_of(&w.h, BOON).map(|q| q.0), Some(status::UNDERWAY));
        let enemy = held(&w, hq.enemy).expect("an enemy's");
        gave_held(&mut w.h, (w.b, w.me, world), t, hq.overseer, enemy);
        assert!(!holds_item(&w.h, hq.enemy), "{block:04X}: an enemy's taken");
        assert_eq!(
            state_of(&w.h, BOON).map(|q| q.0),
            Some(status::COMPLETED),
            "{block:04X}: done"
        );

        // Out again.
        beside(&mut w, way_out);
        w.use_placed(t, way_out);
        assert_eq!(at(&w).cell, hq.exit, "{block:04X}: out beside its way in");
    }
}

/// **The Radiant rays to the Star of Heroes walk through**: the temple's lasher gives Radiant
/// Enlightenment and its magister the rays' recipes; each kingdom's five rays, as the shrines give
/// them, make its beam, the three beams a Radiant Star, and each star made moves the quest on, the
/// third ending it; the temple's priestess gives the Star of Heroes with its recipe, and six Radiant
/// Stars assembled into the Star end it.
/// Behaviour: server.quests.radiant-stars-walk-through
#[test]
fn the_shrines_rays_make_beams_radiant_stars_and_the_star_of_heroes_ending_both_quests() {
    use yalain_world::quests::status;
    const ENLIGHTENMENT: u32 = 0x4000_01CC;
    const HEROES: u32 = 0x4000_01CF;
    const LASHER: u32 = 0x4700_325F;
    const MAGISTER: u32 = 0x4700_3261;
    const PRIESTESS: u32 = 0x4700_3264;
    const RADIANT_STAR: u32 = 0x4700_0B42;
    const STAR_OF_HEROES: u32 = 0x4700_0BAC;
    const STAR_RECIPE: u32 = 0x6F00_0320;
    const HEROES_RECIPE: u32 = 0x6F00_0329;
    // Each kingdom's beam recipe, its five rays (red to violet) and its beam.
    const BEAMS: [(u32, u32, u32); 3] = [
        (0x6F00_0318, 0x4700_0B98, 0x4700_0B9D),
        (0x6F00_0319, 0x4700_0B9E, 0x4700_0BA3),
        (0x6F00_031A, 0x4700_0BA4, 0x4700_0BA9),
    ];
    let t = &compiled().tables;
    let portal = yalain_testkit::authored::Portal::open();
    let recipes: Vec<u32> = (0x6F00_0318..=0x6F00_0320).chain([HEROES_RECIPE]).collect();
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    h.server.kingdom_rows = t.kingdoms.clone();
    set_level(&mut h, 50);
    let world = player_world(&h);
    yalain_world::kingdoms::set_kingdom(
        &mut h.server.players.get_mut(&world).expect("in").qualities,
        2,
    );
    let craft = portal.crafting(&[], &recipes);
    let wanted: Vec<u32> = t
        .quests
        .effect_states()
        .chain(craft.outcome_effects())
        .collect();
    h.server
        .effect_table
        .effects
        .extend(effects_read(&wanted, &t.effect_rules).effects);
    h.server.crafting = craft;
    let rays = BEAMS.iter().flat_map(|(_, first, _)| *first..*first + 5);
    let made = BEAMS
        .iter()
        .map(|b| b.2)
        .chain([RADIANT_STAR, STAR_OF_HEROES]);
    for item in rays.clone().chain(made) {
        h.server.catalog.insert(as_installed(&portal, item));
    }
    let knows = |h: &Harness, recipe: u32| {
        h.server.players[&world]
            .play
            .recipes
            .iter()
            .any(|r| r.recipe == recipe)
    };

    use_person(&mut h, b, me, t, placed(t, LASHER));
    assert_eq!(
        state_of(&h, ENLIGHTENMENT),
        Some((status::UNDERWAY, 1)),
        "given"
    );
    use_person(&mut h, b, me, t, placed(t, MAGISTER));
    assert!(
        recipes[..9].iter().all(|r| knows(&h, *r)),
        "the magister's recipes"
    );
    let mut phases = Vec::new();
    for _ in 0..3 {
        for ray in rays.clone() {
            yalain_world::inventory::give(&mut h.server, &mut h.net, world, ray, 1).expect("given");
        }
        h.run(3);
        for (recipe, first, beam) in BEAMS {
            let five: Vec<u32> = (first..first + 5).collect();
            assert_eq!(
                made_with(&mut h, b, recipe, &five),
                Some(0),
                "{recipe:08X} made"
            );
            assert!(holds_item(&h, beam), "{beam:08X}");
        }
        // The star's slots take the Shadow's beam, the Order's, then the Dominion's.
        let beams: Vec<u32> = BEAMS.iter().rev().map(|b| b.2).collect();
        assert_eq!(
            made_with(&mut h, b, STAR_RECIPE, &beams),
            Some(0),
            "a Radiant Star"
        );
        phases.push(state_of(&h, ENLIGHTENMENT));
    }
    assert_eq!(held_count(&h, RADIANT_STAR), 3, "three stars");
    assert_eq!(
        phases.last().copied().flatten().map(|q| q.0),
        Some(status::COMPLETED),
        "the third star ends it: {phases:?}"
    );
    assert_ne!(phases[0], phases[1], "each star moves it on: {phases:?}");

    use_person(&mut h, b, me, t, placed(t, PRIESTESS));
    assert_eq!(
        state_of(&h, HEROES).map(|q| q.0),
        Some(status::UNDERWAY),
        "the Star of Heroes given"
    );
    assert!(knows(&h, HEROES_RECIPE), "with its recipe");
    for _ in 0..3 {
        yalain_world::inventory::give(&mut h.server, &mut h.net, world, RADIANT_STAR, 1)
            .expect("given");
    }
    h.run(3);
    let stars: Vec<u64> = h.server.players[&world]
        .play
        .items
        .iter()
        .filter(|i| i.template == RADIANT_STAR)
        .map(|i| i.id)
        .collect();
    assert_eq!(stars.len(), 6, "six stars");
    assert_eq!(
        made_with_ids(&mut h, b, HEROES_RECIPE, &stars),
        Some(0),
        "the Star assembled"
    );
    assert!(holds_item(&h, STAR_OF_HEROES));
    assert_eq!(
        state_of(&h, HEROES).map(|q| q.0),
        Some(status::COMPLETED),
        "its making ends it"
    );
}

/// **Kingdom Armor walk through**: once Radiant Enlightenment is done the temple's smith teaches an
/// Order player the Order's Kingdom Armor recipes and none of another kingdom's, with the Drudges'
/// and Empyreans' Unfinished Ancient recipes; an Unfinished Ancient
/// piece and three Radiant Stars make its Order piece for 50,000 coins; the Chaos Forge hands it
/// back to one who has not cleansed it, and, cleansed, takes it and gives the Augmented piece of
/// the same race and slot, as it does another kingdom's piece, in the player's own kingdom.
/// Behaviour: server.quests.kingdom-armor-walk-through
#[test]
fn the_smith_teaches_kingdom_armor_once_the_stars_are_done_and_the_forge_augments_it_for_your_kingdom(
) {
    const ENLIGHTENMENT: u32 = 0x4000_01CC;
    const CLEANSED: u32 = 0x4000_0303;
    const SMITH: u32 = 0x4700_3267;
    const FORGE: u32 = 0x4700_2F63;
    const STAR: u32 = 0x4700_0B42;
    const UNFINISHED_BOOTS: u32 = 0x4700_0B41;
    const ORDER_BOOTS_RECIPE: u32 = 0x6F00_02E0;
    const SHADOW_BOOTS_RECIPE: u32 = 0x6F00_02E1;
    const DRUDGE_UNFINISHED_RECIPE: u32 = 0x6F00_1E3F;
    const ORDER_BOOTS: u32 = 0x4700_0B44;
    const SHADOW_BOOTS: u32 = 0x4700_0B45;
    const AUGMENTED_ORDER_BOOTS: u32 = 0x4700_06CF;
    let t = &compiled().tables;
    let portal = yalain_testkit::authored::Portal::open();
    let (mut h, b, me) = served(t);
    h.server.quest_ids = quest_ids();
    h.server.kingdom_rows = t.kingdoms.clone();
    set_level(&mut h, 50);
    let world = player_world(&h);
    {
        let p = h.server.players.get_mut(&world).expect("in");
        yalain_world::kingdoms::set_kingdom(&mut p.qualities, 2);
        yalain_world::quals::set_int(&mut p.qualities, yalain_world::store::MONEY, 60_000);
    }
    let recipes = [
        ORDER_BOOTS_RECIPE,
        SHADOW_BOOTS_RECIPE,
        DRUDGE_UNFINISHED_RECIPE,
    ];
    let craft = portal.crafting(&[], &recipes);
    h.server
        .effect_table
        .effects
        .extend(effects_read(&craft.outcome_effects(), &t.effect_rules).effects);
    h.server.crafting = craft;
    for item in [
        STAR,
        UNFINISHED_BOOTS,
        ORDER_BOOTS,
        SHADOW_BOOTS,
        AUGMENTED_ORDER_BOOTS,
    ] {
        h.server.catalog.insert(as_installed(&portal, item));
    }
    let knows = |h: &Harness, recipe: u32| {
        h.server.players[&world]
            .play
            .recipes
            .iter()
            .any(|r| r.recipe == recipe)
    };
    let smith = placed(t, SMITH);
    use_person(&mut h, b, me, t, smith);
    assert!(
        !knows(&h, ORDER_BOOTS_RECIPE),
        "nothing before the quest is done"
    );
    done_already(&mut h, ENLIGHTENMENT);
    use_person(&mut h, b, me, t, smith);
    assert!(
        knows(&h, ORDER_BOOTS_RECIPE),
        "the Order's Kingdom Armor recipes"
    );
    assert!(!knows(&h, SHADOW_BOOTS_RECIPE), "none of another kingdom's");
    assert!(
        knows(&h, DRUDGE_UNFINISHED_RECIPE),
        "the later races' unfinished pieces"
    );

    for item in [UNFINISHED_BOOTS, STAR, STAR, STAR] {
        yalain_world::inventory::give(&mut h.server, &mut h.net, world, item, 1).expect("given");
    }
    h.run(3);
    let held = |h: &Harness, template: u32| -> Vec<u64> {
        h.server.players[&world]
            .play
            .items
            .iter()
            .filter(|i| i.template == template)
            .map(|i| i.id)
            .collect()
    };
    let mut slots = held(&h, UNFINISHED_BOOTS);
    slots.extend(held(&h, STAR));
    assert_eq!(
        made_with_ids(&mut h, b, ORDER_BOOTS_RECIPE, &slots),
        Some(0),
        "made"
    );
    assert!(holds_item(&h, ORDER_BOOTS), "the Order's boots");
    assert_eq!(held_count(&h, STAR), 0, "the stars spent");
    assert_eq!(
        yalain_world::store::money(&h.server.players[&world].qualities),
        10_000,
        "for 50,000 coins"
    );

    let boots = held(&h, ORDER_BOOTS)[0];
    assert!(
        gave_held(&mut h, (b, me, world), t, FORGE, boots),
        "handed back uncleansed"
    );
    done_already(&mut h, CLEANSED);
    gave_held(&mut h, (b, me, world), t, FORGE, boots);
    assert!(!holds_item(&h, ORDER_BOOTS), "taken");
    assert_eq!(
        held(&h, AUGMENTED_ORDER_BOOTS).len(),
        1,
        "augmented, of the same race and slot"
    );
    yalain_world::inventory::give(&mut h.server, &mut h.net, world, SHADOW_BOOTS, 1)
        .expect("given");
    h.run(3);
    let shadow = held(&h, SHADOW_BOOTS)[0];
    gave_held(&mut h, (b, me, world), t, FORGE, shadow);
    assert!(!holds_item(&h, SHADOW_BOOTS), "another kingdom's taken");
    assert_eq!(
        held(&h, AUGMENTED_ORDER_BOOTS).len(),
        2,
        "and augmented in the player's own kingdom"
    );
}

/// **The allegiance halls walk through**: the Ondekodo hall is entered by its town's portal; from its
/// landing a monarch reaches the hall's sign on foot and reading it gives the hidden permission;
/// reaching the stone, the monarch pays 20,000 and binds the allegiance, the permission done; the
/// sign gives no permission again within three days; Allegiance Recall from town then takes the
/// monarch to the hall's spot, from which the stone and the way out are reached on foot. Every
/// hall's stone is reached on foot from its recall spot, and Ikeras's town portal leads into its
/// hall, its stone reached from there.
/// Behaviour: server.quests.allegiance-halls-walk-through
#[test]
fn a_monarch_reads_a_halls_sign_binds_at_its_stone_and_the_allegiance_recalls_to_the_hall() {
    use yalain_world::allegiance::Node;
    use yalain_world::quests::status;
    use yalain_world::skill_use::{function as skill, ALLEGIANCE_RECALL};
    const HALL_QUEST: u32 = 0x4000_01D1;
    const SIGNS: [u32; 3] = [0x4700_11C3, 0x4700_11C4, 0x4700_11C5];
    const STONES: [u32; 3] = [0x4700_11BD, 0x4700_11BF, 0x4700_11C1];
    const VASSAL: u64 = 0x2130_0000_0000_0FFF;
    const SWORD: u32 = 0x4700_051C;
    let t = &compiled().tables;
    let halls = &t.content.halls.rows;
    assert_eq!(halls.len(), 6, "every hall 2017 saw a stone in");
    for h in halls {
        let stone = &t.content.objects[h.stone];
        assert!(
            STONES.contains(&stone.template),
            "{}: a binding stone",
            h.key
        );
        assert_eq!(h.cost, 20_000, "{}: the signs' cost", h.key);
        assert_eq!(
            stone.cell >> 16,
            h.place.cell >> 16,
            "{}: in its hall",
            h.key
        );
    }
    let authored = yalain_testkit::authored::Portal::open();
    let ondekodo = halls
        .iter()
        .find(|h| h.place.cell == 0x0DFA_0107)
        .expect("Ondekodo's hall, where 2017's recalls came out");
    let stone = t.content.objects[ondekodo.stone].clone();
    let sign = placed_in(t, SIGNS[1], 0x0DFA_0109);
    let way_in = way_to(t, 0x5766, 0x0DFA_0100);
    let way_out = way_to(t, 0x0DFA, 0x5766_0025);
    let arrival = t.content.objects[way_in].destination.expect("a landing");

    let mut w = walled(t, &[0x5766, 0x0DFA]);
    let world = w.world;
    for id in SIGNS.into_iter().chain(STONES) {
        w.h.server.catalog.insert(as_installed(&authored, id));
    }
    w.h.server.quest_ids = quest_ids();
    {
        let p = w.h.server.players.get_mut(&world).expect("in");
        yalain_world::quals::set_int(&mut p.qualities, yalain_world::examine::LEVEL, 20);
        yalain_world::quals::set_int(&mut p.qualities, yalain_world::store::MONEY, 25_000);
    }
    w.h.server.allegiances.nodes.insert(w.me, Node::default());
    w.h.server.allegiances.nodes.insert(
        VASSAL,
        Node {
            patron: w.me,
            ..Node::default()
        },
    );
    let beside = |w: &mut Walled, i: usize| {
        let o = &t.content.objects[i];
        w.put(spot(o.cell, [o.origin[0] + 1.0, o.origin[1], o.origin[2]]));
    };

    // In by the town's portal, on foot to the sign: the permission.
    beside(&mut w, way_in);
    w.use_placed(t, way_in);
    assert_eq!(w.at().cell, arrival.cell, "in, at the hall's landing");
    let s = t.content.objects[sign].clone();
    assert!(w.run_to(s.origin, 2.0), "the sign reached on foot");
    w.use_placed(t, sign);
    assert_eq!(state_of(&w.h, HALL_QUEST), Some((status::UNDERWAY, 1)));

    // On foot to the stone: paid and bound, the permission done.
    w.put(spot(arrival.cell, arrival.origin));
    assert!(w.run_to(stone.origin, 2.0), "the stone reached on foot");
    w.use_placed(t, ondekodo.stone);
    let money = yalain_world::store::money(&w.h.server.players[&world].qualities);
    assert_eq!(money, 5_000, "20,000 paid");
    assert_eq!(
        state_of(&w.h, HALL_QUEST).map(|q| q.0),
        Some(status::COMPLETED)
    );
    let bound = w.h.server.allegiances.hall_of(VASSAL).expect("bound");
    assert_eq!(bound.place.cell, 0x0DFA_0107, "for the whole allegiance");

    // The sign gives no permission again within three days.
    w.put(spot(arrival.cell, arrival.origin));
    assert!(w.run_to(s.origin, 2.0));
    w.use_placed(t, sign);
    assert_eq!(
        state_of(&w.h, HALL_QUEST).map(|q| q.0),
        Some(status::COMPLETED),
        "not again so soon"
    );

    // From town, the recall (a weapon in hand, as a skill needs): to the hall's spot, whence the
    // stone and the way out on foot.
    beside(&mut w, way_in);
    w.h.server.catalog.insert(authored.template(SWORD));
    w.h.arm(w.b, w.me, SWORD);
    w.h.all_hold(ALLEGIANCE_RECALL);
    w.h.bots[w.b].send(
        true,
        queue::WEENIE,
        &server_call(
            skill::USE,
            &[
                auberean_script::args::Arg::Int(1),
                auberean_script::args::Arg::Int(ALLEGIANCE_RECALL),
                auberean_script::args::Arg::LongInt(0),
            ],
        ),
    );
    w.h.run(400);
    assert_eq!(w.at().cell, 0x0DFA_0107, "recalled to the hall");
    for goal in [stone.origin, t.content.objects[way_out].origin] {
        w.put(spot(ondekodo.place.cell, ondekodo.place.origin));
        assert!(
            w.run_to(goal, 2.0),
            "{goal:?} reached from the recall's spot"
        );
    }

    // Every hall's stone on foot from its recall spot, to within the reach its use is carried out
    // at.
    let reach = yalain_world::usable::halls::REACH - 1.0;
    for h in halls {
        let mut w = walled(t, &[h.place.cell >> 16]);
        w.put(spot(h.place.cell, h.place.origin));
        let o = &t.content.objects[h.stone];
        assert!(
            w.run_to(o.origin, reach),
            "{}: its stone from its spot",
            h.key
        );
    }

    // Ikeras's town portal into its hall, its stone reached from there.
    let ikeras = halls
        .iter()
        .find(|h| h.place.cell == 0x0BFB_0109)
        .expect("Ikeras's hall");
    let way_in = way_to(t, 0xCF8A, 0x0BFB_010B);
    let mut w = walled(t, &[0xCF8A, 0x0BFB]);
    beside(&mut w, way_in);
    w.use_placed(t, way_in);
    assert_eq!(w.at().cell, 0x0BFB_010B, "into Ikeras's hall");
    let o = &t.content.objects[ikeras.stone];
    assert!(w.run_to(o.origin, reach), "Ikeras's stone from the landing");
}

/// **The war and peace shrines stand in their three pairs and work**: each pair, the war shrine
/// north of the peace shrine, is reached on foot from a way into its land: where a trip lands in its
/// block, else beside its block's own gateway (where a traveler through it comes and goes), else
/// where a trip lands in a block beside it. The war shrine's use gives and completes the hidden
/// quest at once and grants the permission to be fought anywhere; the peace shrine is then refused
/// until the quest's three days are out, and its use after them revokes the permission. A world
/// older than these rows has none.
/// Behaviour: server.world.war-peace-shrines-walk
#[test]
fn the_war_and_peace_shrines_are_reached_on_foot_and_grant_then_revoke_the_permission() {
    use yalain_world::kingdoms::permission::ANYWHERE;
    const QUEST: u32 = 0x8000_02C7;
    const WAR: u32 = 0x4700_100E;
    const PEACE: u32 = 0x4700_100C;
    let c = compiled();
    let t = &c.tables;
    if !t
        .quests
        .steps
        .iter()
        .any(|s| s.quest == QUEST && s.key == "war")
    {
        return;
    }
    let of = |template: u32| -> Vec<usize> {
        let mut v: Vec<usize> = (0..t.content.objects.len())
            .filter(|&i| t.content.objects[i].template == template)
            .collect();
        v.sort_by_key(|&i| t.content.objects[i].cell);
        v
    };
    let (wars, peaces) = (of(WAR), of(PEACE));
    let blocks: Vec<u32> = wars
        .iter()
        .map(|&i| t.content.objects[i].cell >> 16)
        .collect();
    assert_eq!(blocks, [0x44AB, 0x4DA2, 0xCE8A], "three pairs, one a block");
    let landing_in = |block: u32| {
        t.content
            .objects
            .iter()
            .filter_map(|o| o.destination.as_ref())
            .find(|d| d.cell >> 16 == block)
            .map(|d| spot(d.cell, d.origin))
    };
    let gateway_of = |block: u32| {
        t.content
            .objects
            .iter()
            .find(|o| o.cell >> 16 == block && o.destination.is_some())
            .map(|o| spot(o.cell, [o.origin[0], o.origin[1] - 3.0, o.origin[2]]))
    };
    let beside = |block: u32| {
        let (x, y) = (block >> 8, block & 0xFF);
        [(1, 0), (-1, 0), (0, 1), (0, -1)]
            .iter()
            .find_map(|(dx, dy)| {
                let b = (x.wrapping_add_signed(*dx) << 8) | y.wrapping_add_signed(*dy);
                landing_in(b)
            })
    };
    for (&war, &peace) in wars.iter().zip(&peaces) {
        let block = t.content.objects[war].cell >> 16;
        assert_eq!(t.content.objects[peace].cell >> 16, block);
        let (w_at, p_at) = (
            t.content.objects[war].origin,
            t.content.objects[peace].origin,
        );
        assert!(
            w_at[1] > p_at[1],
            "{block:04X}: the war shrine to the north"
        );
        let start = landing_in(block)
            .or_else(|| gateway_of(block))
            .or_else(|| beside(block))
            .unwrap_or_else(|| panic!("{block:04X}: a way into its land"));
        let mut w = walled(t, &[block, start.cell >> 16]);
        w.h.server.kingdom_rows = t.kingdoms.clone();
        let world = w.world;
        let allowed = |w: &Walled| {
            yalain_world::kingdoms::permissions_of(&yalain_world::quals::read(
                &w.h.server.players[&world].qualities,
            ))
            .0
        };
        w.put(start);
        let shrine = place_of(t, war);
        if start.cell >> 16 == block {
            on_foot_to(&mut w, shrine, "the war shrine");
        } else {
            assert!(
                w.run_far(shrine.cell, shrine.origin, 3.0),
                "{block:04X}: run over from the block beside"
            );
        }
        w.use_placed(t, war);
        assert_eq!(allowed(&w) & ANYWHERE, ANYWHERE, "{block:04X}: granted");
        let done = w.h.server.players[&world]
            .play
            .quests
            .iter()
            .any(|q| q.quest == QUEST && q.status == yalain_world::quests::status::COMPLETED);
        assert!(done, "{block:04X}: the quest given and completed at once");
        on_foot_to(&mut w, place_of(t, peace), "the peace shrine");
        w.use_placed(t, peace);
        assert_eq!(
            allowed(&w) & ANYWHERE,
            ANYWHERE,
            "{block:04X}: not within three days"
        );
        w.h.unix += 259_200;
        w.use_placed(t, peace);
        assert_eq!(allowed(&w) & ANYWHERE, 0, "{block:04X}: revoked after them");
    }
}

/// **The lifestone a wiki region page lists where no recording went stands on open land and
/// binds**: it is a lifestone, more than 500 m from every other lifestone, on the land above the
/// water and on the ground there; a body put on open ground 12 m off runs up to it, where a recall
/// to it lands, and its use binds the player there.
/// Behaviour: server.places.wiki-lifestones-walk-through
#[test]
fn the_wikis_lifestone_no_recording_reached_stands_on_open_land_reached_and_bound_on_foot() {
    use yalain_world::places::{kind, BESIDE_LIFESTONE, LIFESTONE};
    use yalain_world::usable::maps::ground_distance;
    let c = compiled();
    let t = &c.tables;
    let portal = yalain_testkit::authored::Portal::open();
    let objects = &t.content.objects;
    let stones: Vec<usize> = c
        .merged
        .rows
        .iter()
        .filter(|l| l.pack == "wiki-lifestones")
        .filter_map(|l| match &l.row {
            rows::Row::Object(o) => Some((o.template, o.cell.expect("a cell"))),
            _ => None,
        })
        .map(|(template, cell)| {
            objects
                .iter()
                .position(|o| o.template == template && o.cell == cell)
                .expect("placed")
        })
        .collect();
    assert_eq!(stones.len(), 1, "the wiki's lifestone no recording reached");
    let lifestones: Vec<usize> = (0..objects.len())
        .filter(|&i| portal.derives(objects[i].template, &[LIFESTONE]))
        .collect();
    let at = |i: usize| spot(objects[i].cell, objects[i].origin);
    let i = stones[0];
    assert!(lifestones.contains(&i), "{}: a lifestone", objects[i].label);
    let near = lifestones
        .iter()
        .filter(|&&j| j != i)
        .map(|&j| ground_distance(&at(i), &at(j)))
        .fold(f32::INFINITY, f32::min);
    assert!(near > 500.0, "another lifestone {near} m off");
    let stone = at(i);
    let mut w = walled(t, &[stone.cell >> 16]);
    let package = portal.template(objects[i].template).description.package;
    w.h.server.lifestone_packages.insert(package);
    assert!(stone.cell & 0xFFFF < 0x100, "on the land");
    let walls = w.h.server.walls.as_mut().expect("the walls");
    assert!(!under_water(walls, &stone), "above the water");
    walls.read_place(stone.cell);
    let ground = walls
        .land()
        .ground(
            dereth_primitives::CellId(stone.cell).landblock(),
            dereth_primitives::Vec3::new(stone.origin[0], stone.origin[1], 0.0),
        )
        .expect("the ground")
        .0;
    assert!(
        (stone.origin[2] - ground).abs() < 0.5,
        "on the ground, {} against {ground}",
        stone.origin[2]
    );
    // From open ground 12 m off, the first of eight ways round it that is above the water.
    let reached = (0..8u8).any(|k| {
        use dereth_primitives::num::math;
        let a = f32::from(k) * std::f32::consts::TAU / 8.0;
        let (x, y) = (
            stone.origin[0] + 12.0 * math::sinf(a),
            stone.origin[1] + 12.0 * math::cosf(a),
        );
        let (cell, x, y) = yalain_world::spawn::outdoor(stone.cell >> 16, x, y);
        let walls = w.h.server.walls.as_mut().expect("the walls");
        walls.read_place(cell);
        let Some((z, _)) = walls.land().ground(
            dereth_primitives::CellId(cell).landblock(),
            dereth_primitives::Vec3::new(x, y, 0.0),
        ) else {
            return false;
        };
        let off = spot(cell, [x, y, z]);
        if under_water(walls, &off) {
            return false;
        }
        w.put(off);
        w.way_across(&stone, BESIDE_LIFESTONE)
            .is_some_and(|way| w.run_along(&way) == way.len())
    });
    assert!(reached, "reached on foot");
    w.use_placed(t, i);
    let bound = w.h.server.players[&w.world]
        .places
        .iter()
        .find(|(k, _)| *k == kind::LIFESTONE)
        .map(|(_, p)| *p)
        .expect("bound");
    assert!(
        ground_distance(&bound, &stone) <= BESIDE_LIFESTONE + 0.5,
        "bound where it stands"
    );
}
